import os, sys, json, math, statistics, time
from datetime import datetime, timedelta
from neo4j import GraphDatabase
from graphdatascience import GraphDataScience
import pandas as pd

uri = os.getenv('NEO4J_URI')
user = os.getenv('NEO4J_USERNAME')
pwd = os.getenv('NEO4J_PASSWORD')
db = os.getenv('NEO4J_DATABASE')

if not uri or not user or not pwd:
    print(json.dumps({"error":"Missing Neo4j credentials in environment"}))
    sys.exit(0)

# Connect drivers
try:
    driver = GraphDatabase.driver(uri, auth=(user, pwd))
    session = driver.session(database=db) if db else driver.session()
except Exception as e:
    print(json.dumps({"error":"Failed to connect to Neo4j", "details":str(e)}))
    sys.exit(0)

# Connect GDS
try:
    gds = GraphDataScience(uri, auth=(user, pwd), database=db) if db else GraphDataScience(uri, auth=(user, pwd))
    gds.set_database(db) if db else None
    gds_version = gds.version()
except Exception as e:
    print(json.dumps({"error":"Failed to connect to GDS", "details":str(e)}))
    sys.exit(0)

result = {
    'env':{'gds_version':str(gds_version), 'db':db},
}

# Step 1: detect schema
with session as s:
    # relationship types
    rel_types = [r['relationshipType'] for r in s.run('CALL db.relationshipTypes()').data()]
    node_labels = [r['label'] for r in s.run('CALL db.labels()').data()]
result['rel_types'] = rel_types
result['node_labels'] = node_labels

# Function to sample relationship keys per type
rel_keys = {}
with session as s:
    for rt in rel_types:
        try:
            q = f"MATCH ()-[r:`{rt}`]->() RETURN keys(r) AS keys LIMIT 1"
            rec = s.run(q).single()
            rel_keys[rt] = rec['keys'] if rec else []
        except Exception as e:
            rel_keys[rt] = []
result['rel_keys'] = rel_keys

# Candidate transfer rel types
cand_types = []
for rt in rel_types:
    up = rt.upper()
    if any(k in up for k in ['TRANSFER','SENT','SEND','TX','TRANSACTION','PAYMENT','TO']):
        cand_types.append(rt)
# Fallback to all if none
if not cand_types:
    cand_types = rel_types[:]
result['candidate_rel_types'] = cand_types

# Pick amount and time props per rel type
amount_keys_pref = ['value','amount','wei','valueWei','tokenValue','ethValue','value_wei','valueInWei','amountWei','valueUsd','value_usd']
time_keys_pref = ['timestamp','time','blockTimestamp','block_time','blockTime','ts','datetime','block_ts']
rel_props = {}
for rt in cand_types:
    keys = set(rel_keys.get(rt, []))
    amount_prop = next((k for k in amount_keys_pref if k in keys), None)
    time_prop = next((k for k in time_keys_pref if k in keys), None)
    rel_props[rt] = {'amount':amount_prop, 'time':time_prop}
result['rel_props'] = rel_props

# Detect node label(s) for addresses and address property
addr_labels_cand = [l for l in node_labels if l.lower() in ['address','account','wallet','ethaddress','ethereumaddress','node'] or 'Address' in l or 'ACCOUNT' in l]
if not addr_labels_cand:
    addr_labels_cand = node_labels[:]

addr_prop_keys_pref = ['address','addr','hash','id','address_lower','addressHash']
label_addrprop = None
hack_addr = '0x1db92e2eebc8e0c075a02bea49a2935bcd2dfcf4'.lower()

source_node = None
source_label = None
source_prop = None
with session as s:
    for lab in addr_labels_cand:
        # get a sample node's keys
        try:
            rec = s.run(f"MATCH (n:`{lab}`) RETURN keys(n) AS k LIMIT 1").single()
            klist = rec['k'] if rec else []
        except Exception:
            klist = []
        addr_prop = next((k for k in addr_prop_keys_pref if k in klist), None)
        if not addr_prop:
            # try to find by probing common properties
            for prop in addr_prop_keys_pref:
                try:
                    rec = s.run(f"MATCH (n:`{lab}`) WHERE toLower(n.{prop}) = $a RETURN id(n) AS id LIMIT 1", a=hack_addr).single()
                    if rec:
                        source_node = rec['id']
                        source_label = lab
                        source_prop = prop
                        break
                except Exception:
                    continue
            if source_node is not None:
                break
        else:
            # we have an address property, try to find source node
            try:
                rec = s.run(f"MATCH (n:`{lab}`) WHERE toLower(n.{addr_prop}) = $a RETURN id(n) AS id LIMIT 1", a=hack_addr).single()
                if rec:
                    source_node = rec['id']
                    source_label = lab
                    source_prop = addr_prop
                    break
            except Exception:
                pass

result['source_lookup'] = {'nodeId':source_node, 'label':source_label, 'prop':source_prop}

if source_node is None:
    print(json.dumps({"error":"Source address node not found in the database", 'schema':result}))
    sys.exit(0)

# Determine earliest outgoing transfer time and total outflow from source
# We need to know which relationship type connects addresses; try over candidate types
hack_start = None
outflow_total = 0
amount_samples = []
time_prop_any = None
with session as s:
    for rt in cand_types:
        props = rel_props.get(rt, {})
        aprop = props.get('amount')
        tprop = props.get('time')
        if not tprop:
            continue
        q = f"MATCH (n)-[r:`{rt}`]->(m) WHERE id(n) = $id RETURN min(r.{tprop}) AS tmin, sum(r.{aprop}) AS tsum, collect(r.{aprop})[0..100] AS samp"
        try:
            rec = s.run(q, id=source_node).single()
            if rec and rec['tmin'] is not None:
                tmin = rec['tmin']
                tsum = rec['tsum'] if aprop else None
                if hack_start is None or tmin < hack_start:
                    hack_start = tmin
                if tsum:
                    outflow_total += tsum
                if rec['samp']:
                    amount_samples.extend([x for x in rec['samp'] if isinstance(x,(int,float))])
                time_prop_any = tprop
        except Exception as e:
            continue

# If still None, try without requiring time
if hack_start is None:
    with session as s:
        for rt in cand_types:
            props = rel_props.get(rt, {})
            aprop = props.get('amount')
            q = f"MATCH (n)-[r:`{rt}`]->(m) WHERE id(n) = $id RETURN sum(CASE WHEN exists(r.{aprop}) THEN r.{aprop} ELSE 0 END) AS tsum"
            try:
                rec = s.run(q, id=source_node).single()
                if rec and rec['tsum'] is not None:
                    outflow_total += rec['tsum']
            except Exception:
                pass

result['hack_start'] = hack_start
result['outflow_total_raw'] = outflow_total

# Determine if amounts are likely in wei
amount_scale = 1.0
if amount_samples:
    med = statistics.median([abs(x) for x in amount_samples if x is not None])
    # Heuristic: if median > 1e15, it's wei
    if med and med > 1e15:
        amount_scale = 1e18

result['amount_scale'] = amount_scale

# Define time windows
# If hack_start appears to be unix timestamp (10 digits seconds or 13 ms), normalize to seconds
hack_start_sec = None
if isinstance(hack_start,(int,float)):
    # detect ms vs s
    if hack_start > 1e12: # ms
        hack_start_sec = int(hack_start/1000)
    else:
        hack_start_sec = int(hack_start)
else:
    # if it's a datetime string
    try:
        hack_start_sec = int(pd.to_datetime(hack_start).timestamp())
    except Exception:
        hack_start_sec = None

if hack_start_sec is None:
    # fallback: use min timestamp across all outgoing if available in any type
    hack_start_sec = int(time.time()) - 30*24*3600

# Strict and lenient windows in seconds
win_strict = 7*24*3600
win_lenient = 21*24*3600

# Project graphs via Cypher projection with relationship filters by time window if possible
# Build rel queries
rel_queries = []
for rt in cand_types:
    props = rel_props.get(rt, {})
    aprop = props.get('amount')
    tprop = props.get('time')
    if tprop is None:
        continue
    rq = f"MATCH (s:`{source_label}`)-[r:`{rt}`]->(t:`{source_label}`) WHERE r.{tprop} >= $t0 AND r.{tprop} <= $t1 RETURN id(s) AS source, id(t) AS target, r.{aprop} AS amount, r.{tprop} AS ts"
    rel_queries.append({'type':rt, 'query':rq, 'aprop':aprop, 'tprop':tprop})

if not rel_queries:
    print(json.dumps({"error":"No relationship with usable time property found for projection", 'schema':result}))
    sys.exit(0)

# Node query that includes all nodes touching those rels
node_query = f"""
CALL {{
  {' UNION '.join([rq['query'].replace(' RETURN id(s) AS source, id(t) AS target, r.'+rq['aprop']+' AS amount, r.'+rq['tprop']+' AS ts', ' RETURN source, target') for rq in rel_queries])}
}}
WITH collect(DISTINCT source) + collect(DISTINCT target) AS ids
UNWIND ids AS id
RETURN DISTINCT id AS id
"""

# Relationship query union
def make_rel_union(t0, t1):
    parts = []
    for rq in rel_queries:
        parts.append(rq['query'])
    return " UNION ".join(parts)

# Helper to safely drop graph
def drop_graph(name):
    try:
        if gds.graph.exists(name)['exists']:
            gds.graph.drop(name)
    except Exception:
        pass

# Project strict and lenient graphs
G_strict = 'hack_strict'
G_lenient = 'hack_lenient'

# Parameters for projection
params_strict = {'t0': hack_start_sec, 't1': hack_start_sec + win_strict}
params_lenient = {'t0': hack_start_sec, 't1': hack_start_sec + win_lenient}

# Build Cypher relationship queries
rel_query_strict = make_rel_union(**params_strict)
rel_query_lenient = make_rel_union(**params_lenient)

# Project
try:
    drop_graph(G_strict)
    Gs = gds.graph.project.cypher(
        G_strict,
        node_query,
        rel_query_strict,
        params=params_strict,
        relationshipProperties={'amount':'amount','ts':'ts'}
    )
except Exception as e:
    print(json.dumps({"error":"Failed to project strict graph", 'details':str(e), 'schema':result}))
    sys.exit(0)

try:
    drop_graph(G_lenient)
    Gl = gds.graph.project.cypher(
        G_lenient,
        node_query,
        rel_query_lenient,
        params=params_lenient,
        relationshipProperties={'amount':'amount','ts':'ts'}
    )
except Exception as e:
    print(json.dumps({"error":"Failed to project lenient graph", 'details':str(e)}))
    sys.exit(0)

# Map source_node to projected node id space if needed
# In cypher projection we used original ids as ids, so mapping should be identity
src_gds_id = source_node

# Variant 1: BFS-based hop-limited tracing and attributable inflow sum
variant1 = {}
for name, Gname, depth in [("strict", G_strict, 4),("lenient", G_lenient, 5)]:
    # Try gds.beta.bfs.stream first
    bfs_rows = []
    try:
        bfs_rows = gds.beta.bfs.stream(Gname, sourceNode=src_gds_id, maxDepth=depth, relationshipOrientation='NATURAL').to_dataframe()
    except Exception:
        try:
            bfs_rows = gds.bfs.stream(Gname, sourceNode=src_gds_id, maxDepth=depth, relationshipOrientation='NATURAL').to_dataframe()
        except Exception as e:
            variant1[name] = {'error': f'BFS failed: {e}'}
            continue
    # Compute depth per node
    depths = dict(zip(bfs_rows['nodeId'], bfs_rows['depth']))
    # Get set of nodes visited excluding source
    visited_nodes = [int(n) for n in depths.keys() if int(n) != src_gds_id]

    # Sum inbound amounts from previous levels using store graph (not GDS memory) constrained to time window
    t0 = params_strict['t0'] if name=='strict' else params_lenient['t0']
    t1 = params_strict['t1'] if name=='strict' else params_lenient['t1']

    # We'll fetch sums via Cypher using batches for performance
    sums = {}
    batch = []
    B = 1000
    with session as s:
        for nid in visited_nodes:
            d = depths.get(nid, None)
            if d is None or d < 1:
                continue
            batch.append({'nid':nid, 'd':int(d)})
            if len(batch) >= B:
                ids = [b['nid'] for b in batch]
                ds = {b['nid']:b['d'] for b in batch}
                # Build query: sum of inbound amounts from nodes at smaller depth within window across candidate rel types
                rel_matches = []
                for rt in cand_types:
                    props = rel_props.get(rt, {})
                    aprop = props.get('amount')
                    tprop = props.get('time')
                    if not tprop or not aprop:
                        continue
                    rel_matches.append(f"MATCH (src)-[r:`{rt}`]->(dst) WHERE id(dst) IN $ids AND r.{tprop} >= $t0 AND r.{tprop} <= $t1 RETURN id(dst) AS id, sum(r.{aprop}) AS s")
                if not rel_matches:
                    continue
                q = " UNION ALL ".join(rel_matches)
                rows = s.run(q, ids=ids, t0=t0, t1=t1).data()
                tmp = {}
                for row in rows:
                    tmp[row['id']] = tmp.get(row['id'], 0) + (row['s'] or 0)
                for nid2, sval in tmp.items():
                    sums[nid2] = sums.get(nid2, 0) + sval
                batch = []
        # flush
        if batch:
            ids = [b['nid'] for b in batch]
            rel_matches = []
            for rt in cand_types:
                props = rel_props.get(rt, {})
                aprop = props.get('amount')
                tprop = props.get('time')
                if not tprop or not aprop:
                    continue
                rel_matches.append(f"MATCH (src)-[r:`{rt}`]->(dst) WHERE id(dst) IN $ids AND r.{tprop} >= $t0 AND r.{tprop} <= $t1 RETURN id(dst) AS id, sum(r.{aprop}) AS s")
            if rel_matches:
                q = " UNION ALL ".join(rel_matches)
                rows = s.run(q, ids=ids, t0=t0, t1=t1).data()
                tmp = {}
                for row in rows:
                    tmp[row['id']] = tmp.get(row['id'], 0) + (row['s'] or 0)
                for nid2, sval in tmp.items():
                    sums[nid2] = sums.get(nid2, 0) + sval

    # Normalize sums by scale and total outflow (if >0)
    denom = outflow_total if outflow_total else 1.0
    scores = {nid: (sval/amount_scale)/ (denom/amount_scale) for nid, sval in sums.items()}

    # Fetch address strings for nodes and degrees for basic inspection
    addr_map = {}
    deg_map = {}
    with session as s:
        ids = list(scores.keys())
        if ids:
            for i in range(0, len(ids), 1000):
                sub = ids[i:i+1000]
                q = f"MATCH (n:`{source_label}`) WHERE id(n) IN $ids RETURN id(n) AS id, toLower(n.{source_prop}) AS addr"
                for row in s.run(q, ids=sub):
                    addr_map[row['id']] = row['addr']
            # degrees (out-degree in window)
            rel_matches = []
            for rt in cand_types:
                props = rel_props.get(rt, {})
                tprop = props.get('time')
                if not tprop:
                    continue
                rel_matches.append(f"MATCH (n:`{source_label}`)-[r:`{rt}`]->() WHERE id(n) IN $ids AND r.{tprop} >= $t0 AND r.{tprop} <= $t1 RETURN id(n) AS id, count(*) AS c")
            if rel_matches:
                q = " UNION ALL ".join(rel_matches)
                rows = s.run(q, ids=ids, t0=t0, t1=t1).data()
                tmp = {}
                for row in rows:
                    tmp[row['id']] = tmp.get(row['id'], 0) + (row['c'] or 0)
                deg_map = tmp

    df = pd.DataFrame([
        {'nodeId':int(n), 'addr':addr_map.get(int(n)), 'score':scores[n], 'depth':depths.get(int(n)), 'outdeg_win':deg_map.get(int(n),0)}
        for n in scores if addr_map.get(int(n)) and scores[n] > 0
    ])
    df.sort_values(['score','outdeg_win'], ascending=[False, False], inplace=True)
    variant1[name] = df

# Variant 2: Personalized PageRank on strict/lenient
variant2 = {}
for name, Gname in [("strict", G_strict),("lenient", G_lenient)]:
    try:
        pr = gds.pageRank.stream(Gname, sourceNodes=[src_gds_id], relationshipWeightProperty='amount', maxIterations=40, dampingFactor=0.85)
        df = pr.to_dataframe()
    except Exception as e:
        # fallback: non-personalized PR; then filter to nodes within k hops via BFS weights as proxy
        try:
            df = gds.pageRank.stream(Gname, relationshipWeightProperty='amount', maxIterations=40, dampingFactor=0.85).to_dataframe()
        except Exception as e2:
            variant2[name] = {'error': f'PageRank failed: {e2}'}
            continue
        # compute BFS to get reachable set and depths for attenuation
        try:
            bfs_rows = gds.beta.bfs.stream(Gname, sourceNode=src_gds_id, maxDepth=6, relationshipOrientation='NATURAL').to_dataframe()
        except Exception:
            bfs_rows = gds.bfs.stream(Gname, sourceNode=src_gds_id, maxDepth=6, relationshipOrientation='NATURAL').to_dataframe()
        depths = dict(zip(bfs_rows['nodeId'], bfs_rows['depth']))
        # attenuate scores by depth decay
        df['depth'] = df['nodeId'].map(depths)
        df = df[df['depth'].notnull()].copy()
        df['score'] = df['score'] * (0.85 ** df['depth'])
    # Map to addresses and exclude source
    with session as s:
        ids = [int(x) for x in df['nodeId'].tolist() if int(x) != src_gds_id]
        addr_map = {}
        for i in range(0, len(ids), 1000):
            sub = ids[i:i+1000]
            q = f"MATCH (n:`{source_label}`) WHERE id(n) IN $ids RETURN id(n) AS id, toLower(n.{source_prop}) AS addr"
            for row in s.run(q, ids=sub):
                addr_map[row['id']] = row['addr']
    df['addr'] = df['nodeId'].map(addr_map)
    df = df[df['addr'].notnull()].copy()
    df.sort_values('score', ascending=False, inplace=True)
    variant2[name] = df

# Build ranked lists with filtering thresholds and compare
# Define minimum attributable share and min PR score thresholds using quantiles
lists = {}
comparisons = {}
for name in ['strict','lenient']:
    df1 = variant1.get(name)
    df2 = variant2.get(name)
    if isinstance(df1, dict) or isinstance(df2, dict) or df1 is None or df2 is None:
        continue
    # Thresholds: top by cumulative share until 100, and PR top 500 then intersect
    top1 = df1.sort_values('score', ascending=False)
    # Remove extremely small shares (< 0.0001 of outflow)
    top1 = top1[top1['score'] >= 1e-4]
    top1 = top1.head(500)
    top2 = df2.sort_values('score', ascending=False).head(1000)
    # Intersect with ranks
    r1 = {addr:i for i,addr in enumerate(top1['addr'].tolist())}
    r2 = {addr:i for i,addr in enumerate(top2['addr'].tolist())}
    common = [addr for addr in r1 if addr in r2]
    # Rank by combined rank
    ranked = sorted(common, key=lambda a: (r1[a] + r2[a], r1[a]))
    lists[name] = ranked[:100]
    comparisons[name] = {
        'n_v1': len(df1), 'n_v2': len(df2), 'n_common_top': len(common),
        'disagree_only_v1': [a for a in list(r1.keys())[:50] if a not in r2][:20],
        'disagree_only_v2': [a for a in list(r2.keys())[:50] if a not in r1][:20],
    }

# Also compute union-based ranked lists with weighted scores to break ties
def build_ranked(df1, df2):
    if df1 is None or df2 is None or isinstance(df1, dict) or isinstance(df2, dict):
        return []
    s1 = df1.set_index('addr')['score'] if 'addr' in df1 else pd.Series(dtype=float)
    s2 = df2.set_index('addr')['score'] if 'addr' in df2 else pd.Series(dtype=float)
    addrs = set(s1.index).union(set(s2.index))
    rows = []
    for a in addrs:
        rows.append({'addr':a, 's1':float(s1.get(a,0)), 's2':float(s2.get(a,0))})
    df = pd.DataFrame(rows)
    # Normalize s1 to sum 1, s2 z-score
    if not df.empty:
        if df['s1'].sum() > 0:
            df['s1n'] = df['s1']/df['s1'].sum()
        else:
            df['s1n'] = 0
        if df['s2'].std() > 0:
            df['s2n'] = (df['s2'] - df['s2'].mean())/df['s2'].std()
        else:
            df['s2n'] = 0
        df['combo'] = df['s1n']*0.7 + df['s2n']*0.3
        df.sort_values('combo', ascending=False, inplace=True)
    return df['addr'].head(100).tolist()

rank_union = {name: build_ranked(variant1.get(name), variant2.get(name)) for name in ['strict','lenient']}

# Inspect addresses with disagreement between strict and lenient
strict_list = lists.get('strict', [])
lenient_list = lists.get('lenient', [])
intersect = [a for a in strict_list if a in lenient_list]
only_strict = [a for a in strict_list if a not in lenient_list]
only_lenient = [a for a in lenient_list if a not in strict_list]

# For least-sure addresses (present in one variant only), inspect simple stats
inspect_addrs = (only_strict[:10] + only_lenient[:10])[:20]
inspections = {}
with session as s:
    for chunk in [inspect_addrs[i:i+100] for i in range(0, len(inspect_addrs), 100)]:
        if not chunk:
            continue
        q = f"""
        UNWIND $addrs AS a
        MATCH (n:`{source_label}`) WHERE toLower(n.{source_prop}) = a
        WITH n
        OPTIONAL MATCH (n)-[ro]->() WITH n, count(ro) AS outdeg
        OPTIONAL MATCH ()-[ri]->(n) WITH n, outdeg, count(ri) AS indeg
        RETURN toLower(n.{source_prop}) AS addr, indeg, outdeg
        """
        for row in s.run(q, addrs=chunk):
            inspections[row['addr']] = {'indeg': row['indeg'], 'outdeg': row['outdeg']}

# Prepare final ranked list: prefer strict intersection ordering, then add strict-only, then lenient-only until 100
final_ranked = []
# From intersection, we can use combined rank from strict lists
strict_rank = {a:i for i,a in enumerate(strict_list)}
lenient_rank = {a:i for i,a in enumerate(lenient_list)}
for a in intersect:
    final_ranked.append(a)
for a in only_strict:
    if len(final_ranked) < 100:
        final_ranked.append(a)
for a in only_lenient:
    if len(final_ranked) < 100:
        final_ranked.append(a)

# Build summary
summary = {
    'schema': result,
    'comparisons': comparisons,
    'rank_union': rank_union,
    'intersect_count': len(intersect),
    'only_strict_count': len(only_strict),
    'only_lenient_count': len(only_lenient),
    'inspections': inspections,
    'final_count': len(final_ranked),
}

print(json.dumps({'ok': True, 'summary': summary, 'final': final_ranked[:100]}))

import os, sys, json, math, statistics, time
from datetime import datetime, timedelta
from neo4j import GraphDatabase
from graphdatascience import GraphDataScience
import pandas as pd

uri = os.getenv('NEO4J_URI')
user = os.getenv('NEO4J_USERNAME')
pwd = os.getenv('NEO4J_PASSWORD')
db = os.getenv('NEO4J_DATABASE')

if not uri or not user or not pwd:
    print(json.dumps({"error":"Missing Neo4j credentials in environment"}))
    sys.exit(0)

# Connect drivers
try:
    driver = GraphDatabase.driver(uri, auth=(user, pwd))
    session = driver.session(database=db) if db else driver.session()
except Exception as e:
    print(json.dumps({"error":"Failed to connect to Neo4j", "details":str(e)}))
    sys.exit(0)

# Connect GDS
try:
    gds = GraphDataScience(uri, auth=(user, pwd), database=db) if db else GraphDataScience(uri, auth=(user, pwd))
    if db:
        gds.set_database(db)
    # Check plugin by calling gds.version via cypher
    with session as s:
        rec = s.run("CALL gds.version() YIELD version RETURN version LIMIT 1").single()
        gds_version = rec['version'] if rec else 'unknown'
except Exception as e:
    print(json.dumps({"error":"Failed to connect to GDS or GDS not installed", "details":str(e)}))
    sys.exit(0)

result = {
    'env':{'gds_version':str(gds_version), 'db':db},
}

# Step 1: detect schema
with session as s:
    # relationship types
    rel_types = [r['relationshipType'] for r in s.run('CALL db.relationshipTypes()').data()]
    node_labels = [r['label'] for r in s.run('CALL db.labels()').data()]
result['rel_types'] = rel_types
result['node_labels'] = node_labels

# Function to sample relationship keys per type
rel_keys = {}
with session as s:
    for rt in rel_types:
        try:
            q = f"MATCH ()-[r:`{rt}`]->() RETURN keys(r) AS keys LIMIT 1"
            rec = s.run(q).single()
            rel_keys[rt] = rec['keys'] if rec else []
        except Exception as e:
            rel_keys[rt] = []
result['rel_keys'] = rel_keys

# Candidate transfer rel types
cand_types = []
for rt in rel_types:
    up = rt.upper()
    if any(k in up for k in ['TRANSFER','SENT','SEND','TX','TRANSACTION','PAYMENT','TO']):
        cand_types.append(rt)
# Fallback to all if none
if not cand_types:
    cand_types = rel_types[:]
result['candidate_rel_types'] = cand_types

# Pick amount and time props per rel type
amount_keys_pref = ['value','amount','wei','valueWei','tokenValue','ethValue','value_wei','valueInWei','amountWei','valueUsd','value_usd']
time_keys_pref = ['timestamp','time','blockTimestamp','block_time','blockTime','ts','datetime','block_ts']
rel_props = {}
for rt in cand_types:
    keys = set(rel_keys.get(rt, []))
    amount_prop = next((k for k in amount_keys_pref if k in keys), None)
    time_prop = next((k for k in time_keys_pref if k in keys), None)
    rel_props[rt] = {'amount':amount_prop, 'time':time_prop}
result['rel_props'] = rel_props

# Detect node label(s) for addresses and address property
addr_labels_cand = [l for l in node_labels if l.lower() in ['address','account','wallet','ethaddress','ethereumaddress','node'] or 'Address' in l or 'ACCOUNT' in l]
if not addr_labels_cand:
    addr_labels_cand = node_labels[:]

addr_prop_keys_pref = ['address','addr','hash','id','address_lower','addressHash']
label_addrprop = None
hack_addr = '0x1db92e2eebc8e0c075a02bea49a2935bcd2dfcf4'.lower()

source_node = None
source_label = None
source_prop = None
with session as s:
    for lab in addr_labels_cand:
        # get a sample node's keys
        try:
            rec = s.run(f"MATCH (n:`{lab}`) RETURN keys(n) AS k LIMIT 1").single()
            klist = rec['k'] if rec else []
        except Exception:
            klist = []
        addr_prop = next((k for k in addr_prop_keys_pref if k in klist), None)
        if not addr_prop:
            # try to find by probing common properties
            for prop in addr_prop_keys_pref:
                try:
                    rec = s.run(f"MATCH (n:`{lab}`) WHERE toLower(n.{prop}) = $a RETURN id(n) AS id LIMIT 1", a=hack_addr).single()
                    if rec:
                        source_node = rec['id']
                        source_label = lab
                        source_prop = prop
                        break
                except Exception:
                    continue
            if source_node is not None:
                break
        else:
            # we have an address property, try to find source node
            try:
                rec = s.run(f"MATCH (n:`{lab}`) WHERE toLower(n.{addr_prop}) = $a RETURN id(n) AS id LIMIT 1", a=hack_addr).single()
                if rec:
                    source_node = rec['id']
                    source_label = lab
                    source_prop = addr_prop
                    break
            except Exception:
