result['source_lookup'] = {'nodeId':source_node, 'label':source_label, 'prop':source_prop}

if source_node is None:
    print(json.dumps({"error":"Source address node not found in the database", 'schema':result}))
    sys.exit(0)

# Determine earliest outgoing transfer time and total outflow from source
hack_start = None
outflow_total = 0
amount_samples = []
with session as s:
    for rt in cand_types:
        props = rel_props.get(rt, {})
        aprop = props.get('amount')
        tprop = props.get('time')
        if not tprop:
            continue
        q = f"MATCH (n)-[r:`{rt}`]->(m) WHERE id(n) = $id RETURN min(r.{tprop}) AS tmin, sum(CASE WHEN exists(r.{aprop}) THEN r.{aprop} ELSE 0 END) AS tsum, collect(r.{aprop})[0..100] AS samp"
        try:
            rec = s.run(q, id=source_node).single()
            if rec and rec['tmin'] is not None:
                tmin = rec['tmin']
                tsum = rec['tsum'] if aprop else None
                if hack_start is None or tmin < hack_start:
                    hack_start = tmin
                if tsum:
                    outflow_total += tsum
                if rec['samp']:
                    amount_samples.extend([x for x in rec['samp'] if isinstance(x,(int,float))])
        except Exception as e:
            continue

result['hack_start'] = hack_start
result['outflow_total_raw'] = outflow_total

# Determine if amounts are likely in wei
amount_scale = 1.0
if amount_samples:
    med = statistics.median([abs(x) for x in amount_samples if x is not None])
    if med and med > 1e15:
