# Node query: collect distinct ids from rel query unions
node_query = """
CALL {
  %UNION%
}
WITH collect(DISTINCT source) + collect(DISTINCT target) AS ids
UNWIND ids AS id
RETURN DISTINCT id AS id
"""
rel_union_template = " UNION ".join([rq['query'].replace(' RETURN id(s) AS source, id(t) AS target, r.'+rq['aprop']+' AS amount, r.'+rq['tprop']+' AS ts', ' RETURN source, target') for rq in rel_queries])
node_query = node_query.replace('%UNION%', rel_union_template)

rel_union = " UNION ".join([rq['query'] for rq in rel_queries])

# Helper to drop graphs
try:
    def drop_graph(name):
        try:
            exists = gds.run_cypher("CALL gds.graph.exists($name) YIELD exists RETURN exists", params={'name': name})
            if exists and exists[0].get('exists'):
                gds.run_cypher("CALL gds.graph.drop($name)", params={'name': name})
        except Exception:
            pass
except Exception:
    def drop_graph(name):
