                q = "CALL gds.beta.bfs.stream($graph, {sourceNode: $src, maxDepth: 6, relationshipOrientation: 'NATURAL'}) YIELD nodeId, depth RETURN nodeId, depth"
                bfs_df = pd.DataFrame(gds.run_cypher(q, params={'graph': Gname, 'src': src_gds_id}))
            except Exception:
                q = "CALL gds.bfs.stream($graph, {sourceNode: $src, maxDepth: 6, relationshipOrientation: 'NATURAL'}) YIELD nodeId, depth RETURN nodeId, depth"
                bfs_df = pd.DataFrame(gds.run_cypher(q, params={'graph': Gname, 'src': src_gds_id}))
            depths = dict(zip(bfs_df['nodeId'], bfs_df['depth']))
            df['depth'] = df['nodeId'].map(depths)
            df = df[df['depth'].notnull()].copy()
            df['score'] = df['score'] * (0.85 ** df['depth'])
        except Exception as e2:
            variant2[name] = {'error': f'PageRank failed: {e2}'}
            continue
    # Map to addresses and exclude source
    with session as s:
        ids = [int(x) for x in df['nodeId'].tolist() if int(x) != src_gds_id]
        addr_map = {}
        for i in range(0, len(ids), 1000):
            sub = ids[i:i+1000]
            q = f"MATCH (n:`{source_label}`) WHERE id(n) IN $ids RETURN id(n) AS id, toLower(n.{source_prop}) AS addr"
            for row in s.run(q, ids=sub):
                addr_map[row['id']] = row['addr']
    df['addr'] = df['nodeId'].map(addr_map)
    df = df[df['addr'].notnull()].copy()
    if not df.empty:
        df.sort_values('score', ascending=False, inplace=True)
    variant2[name] = df

# Compare and build lists
lists = {}
comparisons = {}
for name in ['strict','lenient']:
    df1 = variant1.get(name)
    df2 = variant2.get(name)
    if isinstance(df1, dict) or isinstance(df2, dict) or df1 is None or df2 is None or df1.empty or df2.empty:
        continue
    # Filter tiny attributable share (< 0.0001)
    df1f = df1[df1['score'] >= 1e-4].head(500)
    df2f = df2.head(1000)
    r1 = {addr:i for i,addr in enumerate(df1f['addr'].tolist())}
    r2 = {addr:i for i,addr in enumerate(df2f['addr'].tolist())}
    common = [addr for addr in r1 if addr in r2]
    ranked = sorted(common, key=lambda a: (r1[a] + r2[a], r1[a]))
    lists[name] = ranked[:100]
    comparisons[name] = {
        'n_v1': int(len(df1)), 'n_v2': int(len(df2)), 'n_common_top': int(len(common)),
        'disagree_only_v1': [a for a in list(r1.keys())[:50] if a not in r2][:20],
        'disagree_only_v2': [a for a in list(r2.keys())[:50] if a not in r1][:20],
    }

# Build final list: prefer strict intersect, then strict-only, then lenient-only
strict_list = lists.get('strict', [])
lenient_list = lists.get('lenient', [])
intersect = [a for a in strict_list if a in lenient_list]
only_strict = [a for a in strict_list if a not in lenient_list]
only_lenient = [a for a in lenient_list if a not in strict_list]

final_ranked = []
final_ranked.extend(intersect)
for a in only_strict:
    if len(final_ranked) < 100:
        final_ranked.append(a)
for a in only_lenient:
    if len(final_ranked) < 100:
        final_ranked.append(a)

# Inspect least sure addresses (present in one list only)
inspect_addrs = (only_strict[:10] + only_lenient[:10])[:20]
inspections = {}
with session as s:
    for chunk in [inspect_addrs[i:i+100] for i in range(0, len(inspect_addrs), 100)]:
        if not chunk:
            continue
        q = f"""
        UNWIND $addrs AS a
        MATCH (n:`{source_label}`) WHERE toLower(n.{source_prop}) = a
        WITH n
        OPTIONAL MATCH (n)-[ro]->() WITH n, count(ro) AS outdeg
        OPTIONAL MATCH ()-[ri]->(n) WITH n, outdeg, count(ri) AS indeg
        RETURN toLower(n.{source_prop}) AS addr, indeg, outdeg
        """
        for row in s.run(q, addrs=chunk):
            inspections[row['addr']] = {'indeg': row['indeg'], 'outdeg': row['outdeg']}

summary = {
    'schema': result,
    'comparisons': comparisons,
    'intersect_count': len(intersect),
    'only_strict_count': len(only_strict),
    'only_lenient_count': len(only_lenient),
    'gds_version': gds_version,
}

print(json.dumps({'ok': True, 'summary': summary, 'final': final_ranked[:100]}))

