        return {"err":"no source"}
    src_id = int(df.id.iloc[0])
    # Sample rels
    reltype_df = rc("MATCH (s) WHERE id(s)=$id MATCH (s)-[r]->() RETURN type(r) as t, count(*) as c ORDER BY c DESC", {"id": src_id})
    if reltype_df.empty:
        return {"err":"no rels"}
    reltype = reltype_df.t.iloc[0]
    s = rc(f"MATCH (s) WHERE id(s)=$id MATCH (s)-[r:`{reltype}`]->() RETURN r LIMIT 10", {"id": src_id})
    props = []
    for row in s.itertuples(index=False):
        r = getattr(row, 'r')
        if isinstance(r, dict):
            props.append(list(r.keys()))
        else:
            props.append(str(type(r)))
    return {"reltype": reltype, "samples": props, "rows": s.to_dict(orient='records')}

