import os
from graphdatascience import GraphDataScience
import pandas as pd

ADDR = '0x1db92e2eebc8e0c075a02bea49a2935bcd2dfcf4'.lower()

uri = os.getenv('NEO4J_URI')
user = os.getenv('NEO4J_USERNAME')
pwd = os.getenv('NEO4J_PASSWORD')
db = os.getenv('NEO4J_DATABASE')

gds = GraphDataScience(uri, auth=(user, pwd))
if db:
    try:
        gds.set_database(db)
    except Exception:
        pass

run = lambda q,p=None: gds.run_cypher(q,p or {})

labels = run("CALL db.labels() YIELD label RETURN label")['label'].tolist()
prop_candidates = ['address','addr','hash','id','address_lc','addressLower','address_lower','addressHash','addr_lower','addressHashLower']
addr_node = None
addr_label = None
addr_prop = None
for label in labels:
    ors = [f"coalesce(toLower(n.{p}), '') = $addr" for p in prop_candidates]
    q = f"MATCH (n:`{label}`) WHERE {' OR '.join(ors)} RETURN id(n) as id LIMIT 1"
    try:
        df = run(q, {'addr': ADDR})
    except Exception:
        continue
    if not df.empty:
        addr_node = int(df.iloc[0]['id'])
        addr_label = label
        for p in prop_candidates:
            try:
                c = int(run(f"MATCH (n:`{label}`) WHERE coalesce(toLower(n.{p}), '')=$a RETURN count(n) as c", {'a': ADDR}).iloc[0]['c'])
                if c>0:
                    addr_prop = p
                    break
            except Exception:
                continue
        break
if not addr_node:
    print({'summary':'Address not found'})
    raise SystemExit()

reltypes_out = run("MATCH (a)-[r]->() WHERE id(a)=$id RETURN type(r) as type, count(*) as c ORDER BY c DESC", {'id': addr_node})
reltypes_in = run("MATCH (a)<-[r]-() WHERE id(a)=$id RETURN type(r) as type, count(*) as c ORDER BY c DESC", {'id': addr_node})
chosen_dir = 'OUT' if not reltypes_out.empty and int(reltypes_out['c'].sum())>0 else 'IN'
rel_candidates_df = reltypes_out if chosen_dir=='OUT' else reltypes_in
reltype = rel_candidates_df.iloc[0]['type']

# Find time property for optional time filtering
probe_dir = '->' if chosen_dir=='OUT' else '<-'
kdf = run(f"MATCH (a) WHERE id(a)=$id MATCH (a)-[r:`{reltype}`]{probe_dir}() WITH r LIMIT 50 RETURN keys(r) AS keys", {'id': addr_node})
all_keys = set()
for _,kr in kdf.iterrows():
    for k in kr['keys']:
        all_keys.add(k)
for k in ['timestamp','block_timestamp','blockTime','time','ts','blockTs','blockNumber','block_number']:
    if k in all_keys:
        time_prop = k
        break
else:
    time_prop = None

if time_prop:
    t0df = run(f"MATCH (a)-[r:`{reltype}`]->() WHERE id(a)=$id RETURN min(toInteger(datetime(r.`{time_prop}`).epochSeconds)) AS t0", {'id': addr_node})
    t0 = int(t0df.iloc[0]['t0']) if not t0df.empty and pd.notna(t0df.iloc[0]['t0']) else 0
else:
    t0 = 0


def get_reachable_ids(max_hops:int, days:int):
    start = t0
    end = t0 + days*24*3600 if (time_prop and t0) else 2**62
    if chosen_dir=='OUT':
        path_dir = f"-[:`{reltype}`*1..{max_hops}]->"
    else:
        path_dir = f"<-[:`{reltype}`*1..{max_hops}]-"
    if time_prop and t0:
        q = f"""
        MATCH (s:`{addr_label}`) WHERE id(s)=$sid
        MATCH p=(s){path_dir}(n:`{addr_label}`)
        WHERE ALL(r IN relationships(p) WHERE toInteger(datetime(r.`{time_prop}`).epochSeconds) >= $start AND toInteger(datetime(r.`{time_prop}`).epochSeconds) <= $end)
        WITH collect(DISTINCT id(n)) AS nodes, id(s) AS sid
        WITH [sid] + nodes AS ids
        UNWIND ids AS id RETURN DISTINCT id
        """
        params = {'sid': addr_node, 'start': start, 'end': end}
    else:
        q = f"""
        MATCH (s:`{addr_label}`) WHERE id(s)=$sid
        MATCH p=(s){path_dir}(n:`{addr_label}`)
        WITH collect(DISTINCT id(n)) AS nodes, id(s) AS sid
        WITH [sid] + nodes AS ids
        UNWIND ids AS id RETURN DISTINCT id
        """
        params = {'sid': addr_node}
    ids = run(q, params)
    return [int(r['id']) for _, r in ids.iterrows()], start, end


def drop_graph_if_exists(name: str):
    try:
        ex = run("CALL gds.graph.exists($n) YIELD exists RETURN exists", {'n': name})
        if not ex.empty and bool(ex.iloc[0]['exists']):
            run("CALL gds.graph.drop($n) YIELD graphName RETURN graphName", {'n': name})
    except Exception:
        pass


def project_graph_simple(name:str, ids, start:int, end:int):
    drop_graph_if_exists(name)
    node_query = "UNWIND $ids AS id MATCH (n) WHERE id(n)=id RETURN id"
    if chosen_dir=='OUT':
        match_rel = f"MATCH (src)-[r:`{reltype}`]->(dst)"
        src_expr = 'id(src) AS source, id(dst) AS target'
    else:
        match_rel = f"MATCH (src)-[r:`{reltype}`]->(dst)"
        src_expr = 'id(dst) AS source, id(src) AS target'
    if time_prop and t0:
        texpr = f"toInteger(datetime(r.`{time_prop}`).epochSeconds)"
        time_filter = f"WHERE id(src) IN $ids AND id(dst) IN $ids AND {texpr} >= $start AND {texpr} <= $end"
    else:
        time_filter = f"WHERE id(src) IN $ids AND id(dst) IN $ids"
    rel_query = f"""
    {match_rel}
    {time_filter}
    RETURN {src_expr}
    """
    cfg = {'parameters': {'ids': ids, 'start': start, 'end': end}}
    run("CALL gds.graph.project.cypher($name, $nq, $rq, $cfg) YIELD graphName, nodeCount, relationshipCount", {'name': name, 'nq': node_query, 'rq': rel_query, 'cfg': cfg})
    return name

results = {}

# Variant 1: Personalized PageRank with two windows/hops
for name, hops, days in [('PPR14d_h4',4,14), ('PPR7d_h3',3,7)]:
    ids, start, end = get_reachable_ids(hops, days)
    if len(ids) < 2:
        continue
    Gname = project_graph_simple(name, ids, start, end)
    try:
        df = run("CALL gds.pageRank.stream($g, $cfg) YIELD nodeId, score RETURN nodeId, score", {'g': Gname, 'cfg': {'sourceNodes':[addr_node], 'maxIterations':50, 'dampingFactor':0.85}})
        nodes_df = run(f"UNWIND $ids AS id MATCH (n) WHERE id(n)=id RETURN id(n) AS nodeId, coalesce(n.{addr_prop}, toString(id(n))) AS address", {'ids': ids})
        merged = df.merge(nodes_df, on='nodeId', how='left')
        merged = merged[merged['nodeId'] != addr_node]
        merged = merged.sort_values('score', ascending=False)
        results[name] = merged[['address','score']].reset_index(drop=True)
    finally:
        drop_graph_if_exists(Gname)

# Variant 2: HITS authority on the larger subgraph
idsX, startX, endX = get_reachable_ids(4, 14)
if len(idsX) >= 2:
    Gname = project_graph_simple('HITS14d_h4', idsX, startX, endX)
    try:
        hits = run("CALL gds.hits.stream($g, $cfg) YIELD nodeId, values RETURN nodeId, values", {'g': Gname, 'cfg': {'iterations': 30}})
        # values is a map with keys 'auth' and 'hub' in some versions, or 'authority'/'hub' in others
        if 'values' in hits.columns:
            # Extract possible keys
            def auth_val(v):
                if isinstance(v, dict):
                    for k in ['authority','auth','authScore','authorityScore']:
                        if k in v:
                            return float(v[k])
                return None
            hits['score'] = hits['values'].apply(auth_val)
            hits = hits.dropna(subset=['score'])
        else:
            # Unexpected, skip
            hits['score'] = 0.0
        nodes_df = run(f"UNWIND $ids AS id MATCH (n) WHERE id(n)=id RETURN id(n) AS nodeId, coalesce(n.{addr_prop}, toString(id(n))) AS address", {'ids': idsX})
        merged = hits.merge(nodes_df, on='nodeId', how='left')
        merged = merged[merged['nodeId'] != addr_node]
        merged = merged.sort_values('score', ascending=False)
        results['HITS14d_h4'] = merged[['address','score']].reset_index(drop=True)
    finally:
        drop_graph_if_exists(Gname)

# Summarize
rankings = {}
for k, df in results.items():
    dfn = df.copy()
    if len(dfn) > 0:
        mx = dfn['score'].max()
        dfn['norm'] = dfn['score'] / mx if mx and mx>0 else 0.0
    else:
        dfn['norm'] = 0.0
    rankings[k] = dfn

stability = {}
if 'PPR14d_h4' in rankings and 'PPR7d_h3' in rankings:
    a = set(rankings['PPR14d_h4'].head(100)['address'].tolist())
    b = set(rankings['PPR7d_h3'].head(100)['address'].tolist())
    inter = a & b
    union = a | b
    stability['PPR_top100_jaccard'] = len(inter)/len(union) if union else None

# Final ranking: take PPR14d base, blend with HITS if available
final_df = None
if 'PPR14d_h4' in rankings:
    base = rankings['PPR14d_h4'][['address','norm']].rename(columns={'norm':'base'})
    if 'HITS14d_h4' in rankings:
        h = rankings['HITS14d_h4'][['address','norm']].rename(columns={'norm':'h'})
        comb = base.merge(h, on='address', how='left')
        comb['h'] = comb['h'].fillna(0.0)
        comb['final'] = 0.7*comb['base'] + 0.3*comb['h']
        final_df = comb.sort_values('final', ascending=False)
    else:
        base['final'] = base['base']
        final_df = base.sort_values('final', ascending=False)

final_list = final_df.head(100)['address'].tolist() if final_df is not None else []

print({'variants': list(results.keys()), 'stability': stability, 'preview': final_list[:10]})

