all_keys=set(); [all_keys.update(kr['keys']) for _,kr in kdf.iterrows()]
for k in ['timestamp','block_timestamp','blockTime','time','ts','blockTs','blockNumber','block_number']:
    if k in all_keys: time_prop=k; break
else: time_prop=None
if time_prop:
    t0 = int(run(f"MATCH (a)-[r:`{reltype}`]->() WHERE id(a)=$id RETURN min(toInteger(datetime(r.`{time_prop}`).epochSeconds)) AS t0", {'id': addr_node}).iloc[0]['t0'] or 0)
