def project_simple(name, ids, start, end):
    if not run("CALL gds.graph.exists($n) YIELD exists RETURN exists", {'n': name}).empty and bool(run("CALL gds.graph.exists($n) YIELD exists RETURN exists", {'n': name}).iloc[0]['exists']):
        run("CALL gds.graph.drop($n) YIELD graphName RETURN graphName", {'n': name})
    node_query="UNWIND $ids AS id MATCH (n) WHERE id(n)=id RETURN id"
    match_rel=f"MATCH (src)-[r:`{reltype}`]->(dst)"; src_expr='id(src) AS source, id(dst) AS target' if chosen_dir=='OUT' else 'id(dst) AS source, id(src) AS target'
    if time_prop and t0:
        texpr=f"toInteger(datetime(r.`{time_prop}`).epochSeconds)"; time_filter=f"WHERE id(src) IN $ids AND id(dst) IN $ids AND {texpr} >= $start AND {texpr} <= $end"
    else:
        time_filter=f"WHERE id(src) IN $ids AND id(dst) IN $ids"
    rel_query=f"{match_rel}\n{time_filter}\nRETURN {src_expr}"
    run("CALL gds.graph.project.cypher($name,$nq,$rq,$cfg) YIELD graphName, nodeCount, relationshipCount", {'name': name,'nq': node_query,'rq': rel_query,'cfg':{'parameters':{'ids':ids,'start':start,'end':end}}})
    return name

results={}
# PPR variants
for name,hops,days in [('PPR14d_h4',4,14),('PPR7d_h3',3,7)]:
    ids,start,end=get_ids(hops,days)
    if len(ids)<2: continue
    G=project_simple(name,ids,start,end)
    df=run("CALL gds.pageRank.stream($g, $cfg) YIELD nodeId, score RETURN nodeId, score", {'g':G,'cfg':{'sourceNodes':[addr_node],'maxIterations':50,'dampingFactor':0.85}})
    nodes=run(f"UNWIND $ids AS id MATCH (n) WHERE id(n)=id RETURN id(n) AS nodeId, coalesce(n.{addr_prop}, toString(id(n))) AS address",{'ids':ids})
    merged=df.merge(nodes,on='nodeId',how='left'); merged=merged[merged['nodeId']!=addr_node].sort_values('score',ascending=False)
    results[name]=merged[['address','score']].reset_index(drop=True)
    run("CALL gds.graph.drop($n) YIELD graphName RETURN graphName",{'n':G})

# HITS variant
idsX,startX,endX=get_ids(4,14)
if len(idsX)>=2:
    G=project_simple('HITS14d_h4',idsX,startX,endX)
    hits=run("CALL gds.hits.stream($g, $cfg) YIELD nodeId, values RETURN nodeId, values", {'g':G,'cfg':{'hitsIterations':30}})
    def auth(v):
        if isinstance(v,dict):
            for k in ['authority','auth','authScore','authorityScore']:
                if k in v: return float(v[k])
        return None
    hits['score']=hits['values'].apply(auth)
    hits=hits.dropna(subset=['score'])
    nodes=run(f"UNWIND $ids AS id MATCH (n) WHERE id(n)=id RETURN id(n) AS nodeId, coalesce(n.{addr_prop}, toString(id(n))) AS address",{'ids':idsX})
    merged=hits.merge(nodes,on='nodeId',how='left'); merged=merged[merged['nodeId']!=addr_node].sort_values('score',ascending=False)
    results['HITS14d_h4']=merged[['address','score']].reset_index(drop=True)
    run("CALL gds.graph.drop($n) YIELD graphName RETURN graphName",{'n':G})

# Build final
rankings={}
for k,df in results.items():
    dfn=df.copy(); mx=dfn['score'].max() if len(dfn)>0 else 0; dfn['norm']=dfn['score']/mx if mx and mx>0 else 0.0; rankings[k]=dfn
stability={}
if 'PPR14d_h4'in rankings and 'PPR7d_h3'in rankings:
    a=set(rankings['PPR14d_h4'].head(100)['address']); b=set(rankings['PPR7d_h3'].head(100)['address']);
    stability['PPR_top100_jaccard']=len(a&b)/len(a|b) if (a|b) else None
final=None
if 'PPR14d_h4' in rankings:
    base=rankings['PPR14d_h4'][['address','norm']].rename(columns={'norm':'base'})
    if 'HITS14d_h4' in rankings:
        h=rankings['HITS14d_h4'][['address','norm']].rename(columns={'norm':'h'})
        comb=base.merge(h,on='address',how='left'); comb['h']=comb['h'].fillna(0.0); comb['final']=0.7*comb['base']+0.3*comb['h']; final=comb.sort_values('final',ascending=False)
    else:
        base['final']=base['base']; final=base.sort_values('final',ascending=False)
else:
    # fallback to HITS
    if 'HITS14d_h4' in rankings:
        h=rankings['HITS14d_h4'][['address','norm']].rename(columns={'norm':'final'}); final=h.sort_values('final',ascending=False)

preview = final.head(10)['address'].tolist() if final is not None else []
print({'variants': list(results.keys()), 'stability': stability, 'preview': preview})

import os, sys
from neo4j import GraphDatabase
from graphdatascience import GraphDataScience
