NEO4J_DATABASE = os.getenv("NEO4J_DATABASE")

if not (NEO4J_URI and NEO4J_USERNAME and NEO4J_PASSWORD):
    print("ERROR: Missing Neo4j credentials in environment.")
    sys.exit(1)

try:
    driver = GraphDatabase.driver(NEO4J_URI, auth=(NEO4J_USERNAME, NEO4J_PASSWORD))
    driver.verify_connectivity()
except Exception as e:
    print(f"ERROR: Cannot connect to Neo4j: {e}")
    sys.exit(1)

if not NEO4J_DATABASE:
    try:
        with driver.session() as sess:
            db = sess.execute_read(lambda tx: tx.run("CALL db.info() YIELD name RETURN name").data())
            if db:
                NEO4J_DATABASE = db[0]['name']
    except Exception:
        pass

addr = "0x1db92e2eebc8e0c075a02bea49a2935bcd2dfcf4".lower()

# Helper

def run(q, p=None):
    with driver.session(database=NEO4J_DATABASE) as s:
        return s.run(q, p or {}).data()

# Find node
node = None
label = None
prop = None

# Try direct on common labels/props
labels = [r['label'] for r in run("CALL db.labels() YIELD label RETURN label")] or []
props = ['address','addr','hash','id','address_lower','addressLower','hex']

cand_labels = [l for l in ['Address','Account','Wallet','EOA','ETHAddress'] if l in labels] + [l for l in labels if l not in ['Address','Account','Wallet','EOA','ETHAddress']]
if not cand_labels:
    cand_labels = [None]

for l in cand_labels:
    for p in props:
        try:
            q = f"MATCH (n{':`'+l+'`' if l else ''}) WHERE toLower(n.{p}) = $a RETURN id(n) AS id, labels(n) AS labels LIMIT 1"
            r = run(q, {'a': addr})
            if r:
                node = r[0]['id']
                label = l or (r[0]['labels'][0] if r[0].get('labels') else None)
                prop = p
                break
        except Exception:
            pass
    if node is not None:
        break

if node is None:
    r = run("MATCH (n) WHERE any(k IN keys(n) WHERE toLower(toString(n[k]))=$a) RETURN id(n) AS id, labels(n) AS labels, [k IN keys(n) WHERE toLower(toString(n[k]))=$a][0] AS prop LIMIT 1", {'a': addr})
    if r:
        node = r[0]['id']
        label = r[0]['labels'][0] if r[0].get('labels') else None
        prop = r[0]['prop']

if node is None:
    print("NOT_FOUND: address node not found")
    sys.exit(0)

# Find best relationship type from this node
rels = [r['relationshipType'] for r in run("CALL db.relationshipTypes() YIELD relationshipType RETURN relationshipType")] or []

best_type = None
best_cnt = -1
for t in rels:
    try:
        c = run(f"MATCH (a)-[r:`{t}`]->(b) WHERE id(a)=$id RETURN count(r) AS c", {'id': node})
        c = c[0]['c'] if c else 0
        if c > best_cnt:
            best_cnt = c
            best_type = t
    except Exception:
        pass

if best_type is None or best_cnt == 0:
    print("NOT_FOUND: no outgoing rels from address")
    sys.exit(0)

# Inspect keys on this relationship type, prioritizing ones from the source node
keys_src = run(f"MATCH (a)-[r:`{best_type}`]->(b) WHERE id(a)=$id UNWIND keys(r) AS k RETURN k, count(*) AS c ORDER BY c DESC LIMIT 100", {'id': node})
keys_all = run(f"MATCH ()-[r:`{best_type}`]->() UNWIND keys(r) AS k RETURN k, count(*) AS c ORDER BY c DESC LIMIT 100")

keys_src_list = [row['k'] for row in keys_src]
keys_all_list = [row['k'] for row in keys_all]

# Choose amount and time keys by heuristics
cands_amt = []
cands_time = []
for k in keys_src_list + [x for x in keys_all_list if x not in keys_src_list]:
    kl = (k or '').lower()
    if any(s in kl for s in ['amount','value','val','qty','quantity','wei','eth']):
        cands_amt.append(k)
    if any(s in kl for s in ['timestamp','blocktimestamp','block_time','blocktime','time','date']):
        cands_time.append(k)

# Deduplicate preserving order
seen=set(); cands_amt=[x for x in cands_amt if not (x in seen or seen.add(x))]; seen=set(); cands_time=[x for x in cands_time if not (x in seen or seen.add(x))]

# Validate by checking numeric types existence
chosen_amt=None; chosen_time=None
for k in cands_amt:
    try:
        r = run(f"MATCH (a)-[r:`{best_type}`]->(b) WHERE id(a)=$id AND exists(r.`{k}`) RETURN toFloat(r.`{k}`) AS v LIMIT 1", {'id': node})
        if r and r[0]['v'] is not None:
            chosen_amt = k
            break
    except Exception:
        pass

for k in cands_time:
    try:
        r = run(f"MATCH (a)-[r:`{best_type}`]->(b) WHERE id(a)=$id AND exists(r.`{k}`) RETURN toInteger(r.`{k}`) AS v LIMIT 1", {'id': node})
        if r and r[0]['v'] is not None:
            chosen_time = k
            break
    except Exception:
        pass

print({'address_label': label, 'address_prop': prop, 'rel_type': best_type, 'out_rel_count': best_cnt, 'candidate_amount_keys': cands_amt[:10], 'candidate_time_keys': cands_time[:10], 'chosen_amount': chosen_amt, 'chosen_time': chosen_time})

import os, sys, time as pytime
import pandas as pd
from neo4j import GraphDatabase
from graphdatascience import GraphDataScience

NEO4J_URI=os.getenv('NEO4J_URI'); NEO4J_USERNAME=os.getenv('NEO4J_USERNAME'); NEO4J_PASSWORD=os.getenv('NEO4J_PASSWORD'); NEO4J_DATABASE=os.getenv('NEO4J_DATABASE')

driver=GraphDatabase.driver(NEO4J_URI, auth=(NEO4J_USERNAME, NEO4J_PASSWORD))
gds=GraphDataScience(NEO4J_URI, auth=(NEO4J_USERNAME, NEO4J_PASSWORD))
if NEO4J_DATABASE:
    gds.set_database(NEO4J_DATABASE)

def run(q,p=None):
    with driver.session(database=NEO4J_DATABASE) as s:
        return s.run(q,p or {}).data()

addr='0x1db92e2eebc8e0c075a02bea49a2935bcd2dfcf4'.lower()
row=run("MATCH (n:Address) WHERE toLower(n.address)=$a RETURN id(n) AS id, labels(n) AS l LIMIT 1",{'a':addr})
if not row:
    print('NOT_FOUND'); sys.exit(0)
node=row[0]['id']; label=row[0]['l'][0]

rels=[r['relationshipType'] for r in run('CALL db.relationshipTypes() YIELD relationshipType RETURN relationshipType')]
best=None; cnt=-1
for t in rels:
    try:
        c=run(f"MATCH (a)-[r:`{t}`]->(b) WHERE id(a)=$id RETURN count(r) AS c",{'id':node})
        c=c[0]['c'] if c else 0
        if c>cnt: cnt=c; best=t
    except Exception: pass
if not best or cnt==0:
    print('NO_RELS'); sys.exit(0)

krows=run(f"MATCH (a)-[r:`{best}`]->(b) WHERE id(a)=$id UNWIND keys(r) AS k RETURN k, count(*) AS c ORDER BY c DESC",{'id':node})
ks=[r['k'] for r in krows]
amt=None; tim=None
for k in ks:
    kl=k.lower()
    if amt is None and any(s in kl for s in ['amount','value','val','qty','quantity','wei','eth']):
        r=run(f"MATCH (a)-[r:`{best}`]->(b) WHERE id(a)=$id AND r.`{k}` IS NOT NULL RETURN toFloat(r.`{k}`) AS v LIMIT 1",{'id':node})
        if r and r[0]['v'] is not None: amt=k
    if tim is None and any(s in kl for s in ['timestamp','blocktimestamp','block_time','blocktime','time','date']):
        r=run(f"MATCH (a)-[r:`{best}`]->(b) WHERE id(a)=$id AND r.`{k}` IS NOT NULL RETURN r.`{k}` AS v LIMIT 1",{'id':node})
        if r and r[0]['v'] is not None: tim=k
    if amt and tim: break

if not amt or not tim:
    print({'error':'missing props','amt':amt,'tim':tim}); sys.exit(0)

r=run(f"MATCH (a)-[r:`{best}`]->(b) WHERE id(a)=$id AND r.`{tim}` IS NOT NULL RETURN min(coalesce(toInteger(r.`{tim}`.epochSeconds), toInteger(r.`{tim}`))) AS t0",{'id':node})
if not r or r[0]['t0'] is None:
    print('NO_T0'); sys.exit(0)

t0=int(r[0]['t0'])
amts=[row['a'] for row in run(f"MATCH (a)-[r:`{best}`]->(b) WHERE id(a)=$id AND r.`{amt}` IS NOT NULL RETURN toFloat(r.`{amt}`) AS a",{'id':node})]
if not amts:
    print('NO_AMTS'); sys.exit(0)
ser=pd.Series(amts); q50=float(ser.quantile(0.5)); q75=float(ser.quantile(0.75)); q90=float(ser.quantile(0.90))

variants=[
    {'name':'A_weighted_time_decay','days':21,'min_amount':max(q50,q75*0.5),'lam':0.15,'mode':'weighted'},
    {'name':'B_unweighted_strict','days':7,'min_amount':max(q75,q90*0.8),'lam':0.0,'mode':'unweighted'}
]

outs={}
for v in variants:
    g=f"g_{int(pytime.time()*1000)}_{v['name']}"
    t1=t0+int(v['days']*86400)
    ts=f"coalesce(toInteger(r.`{tim}`.epochSeconds), toInteger(r.`{tim}`))"
    # embed constants directly
    if v['mode']=='weighted':
        rq=(
            f"MATCH (a:`{label}`)-[r:`{best}`]->(b:`{label}`) "
            f"WHERE r.`{tim}` IS NOT NULL AND r.`{amt}` IS NOT NULL AND {ts} >= {t0} AND {ts} <= {t1} AND toFloat(r.`{amt}`) >= {v['min_amount']} "
            f"WITH id(a) AS source, id(b) AS target, toFloat(r.`{amt}`) AS amt, {ts} AS ts "
            f"WITH source, target, log(1.0+amt) * exp(-{v['lam']} * (ts-{t0})/86400.0) AS weight "
            f"RETURN source, target, weight"
        )
    else:
        rq=(
            f"MATCH (a:`{label}`)-[r:`{best}`]->(b:`{label}`) "
            f"WHERE r.`{tim}` IS NOT NULL AND r.`{amt}` IS NOT NULL AND {ts} >= {t0} AND {ts} <= {t1} AND toFloat(r.`{amt}`) >= {v['min_amount']} "
            f"WITH id(a) AS source, id(b) AS target "
            f"RETURN source, target, 1.0 AS weight"
        )
    nq=(
        f"MATCH (a:`{label}`)-[r:`{best}`]->(b:`{label}`) "
        f"WHERE r.`{tim}` IS NOT NULL AND r.`{amt}` IS NOT NULL AND {ts} >= {t0} AND {ts} <= {t1} AND toFloat(r.`{amt}`) >= {v['min_amount']} "
        f"RETURN id(a) AS id "
        f"UNION "
        f"MATCH (a:`{label}`)-[r:`{best}`]->(b:`{label}`) "
        f"WHERE r.`{tim}` IS NOT NULL AND r.`{amt}` IS NOT NULL AND {ts} >= {t0} AND {ts} <= {t1} AND toFloat(r.`{amt}`) >= {v['min_amount']} "
        f"RETURN id(b) AS id"
    )

    try:
        proj=gds.run_cypher("CALL gds.graph.project.cypher($g,$nq,$rq) YIELD graphName, nodeCount, relationshipCount", {'g':g,'nq':nq,'rq':rq})
    except Exception as e:
        outs[v['name']]={'error':str(e)}
        continue

    if proj.empty or int(proj['nodeCount'][0])==0:
        outs[v['name']]={'error':'empty graph'}
        continue

    try:
        pr=gds.run_cypher("CALL gds.pageRank.stream($g,{sourceNodes:$s,maxIterations:40,dampingFactor:0.85,relationshipWeightProperty:'weight'}) YIELD nodeId, score WITH nodeId, score, gds.util.asNode(nodeId) AS n RETURN nodeId, score, coalesce(n.address,n.hash,n.id,n.addr) AS address ORDER BY score DESC LIMIT 500", {'g':g,'s':[node]})
    except Exception as e:
        outs[v['name']]={'error':f'pr failed: {e}'}
        try:
            gds.run_cypher("CALL gds.graph.drop($g)", {'g':g})
        except Exception:
            pass
        continue

    # Degree
    try:
        indeg=gds.run_cypher("CALL gds.degree.stream($g,{orientation:'IN'}) YIELD nodeId, score RETURN nodeId, score AS inD", {'g':g})
        outdeg=gds.run_cypher("CALL gds.degree.stream($g,{orientation:'OUT'}) YIELD nodeId, score RETURN nodeId, score AS outD", {'g':g})
        indeg=indeg.set_index('nodeId'); outdeg=outdeg.set_index('nodeId')
        deg=indeg.join(outdeg, how='outer').fillna(0.0)
        deg['sinkness']=deg['inD']/(1+deg['outD'])
        pr=pr.merge(deg.reset_index(), on='nodeId', how='left')
    except Exception:
        pr['sinkness']=0.0
    if not pr.empty:
        pr=pr.dropna(subset=['address']); pr=pr[pr['address'].astype(str).str.startswith('0x')]
        m=pr['score'].max(); pr['score_norm']=pr['score']/m if m>0 else 0.0; pr['conf']=pr['score_norm']*(1+pr['sinkness'])

    outs[v['name']]={'df':pr,'proj':{'nodeCount':int(proj['nodeCount'][0]),'relationshipCount':int(proj['relationshipCount'][0])}}
    try:
        gds.run_cypher("CALL gds.graph.drop($g)", {'g':g})
    except Exception:
        pass

# Evaluate
print({k: (('ok', v['proj']['nodeCount'], v['proj']['relationshipCount'], len(v['df'])) if 'df' in v else ('err', v.get('error'))) for k,v in outs.items()})
for k,v in outs.items():
    if 'df' in v:
        print('SAMPLE', k, v['df'].head(30)['address'].tolist())
        break

