        rq=(
            f"MATCH (a:`{label}`)-[r:`{best}`]->(b:`{label}`) "
            f"WHERE r.`{tim}` IS NOT NULL AND r.`{amt}` IS NOT NULL AND {ts} >= {t0} AND {ts} <= {t1} AND toFloat(r.`{amt}`) >= {v['min_amount']} "
            f"WITH id(a) AS source, id(b) AS target "
            f"RETURN source, target, 1.0 AS cost"
        )

    nq=(
        f"MATCH (a:`{label}`)-[r:`{best}`]->(b:`{label}`) "
        f"WHERE r.`{tim}` IS NOT NULL AND r.`{amt}` IS NOT NULL AND {ts} >= {t0} AND {ts} <= {t1} AND toFloat(r.`{amt}`) >= {v['min_amount']} "
        f"RETURN id(a) AS id "
        f"UNION "
        f"MATCH (a:`{label}`)-[r:`{best}`]->(b:`{label}`) "
        f"WHERE r.`{tim}` IS NOT NULL AND r.`{amt}` IS NOT NULL AND {ts} >= {t0} AND {ts} <= {t1} AND toFloat(r.`{amt}`) >= {v['min_amount']} "
        f"RETURN id(b) AS id"
    )

    try:
        proj=gds.run_cypher("CALL gds.graph.project.cypher($g,$nq,$rq) YIELD graphName, nodeCount, relationshipCount", {'g':g,'nq':nq,'rq':rq})
    except Exception as e:
        outs[v['name']]={'error':str(e)}
        continue

    if proj.empty or int(proj['nodeCount'][0])==0:
        outs[v['name']]={'error':'empty graph'}
        continue

    # Run algorithm
    if v['mode']=='weighted':
        # Dijkstra shortest paths cost to all targets up to cutoff hops maybe 5
        try:
            sp=gds.run_cypher("CALL gds.shortestPath.dijkstra.stream($g,{sourceNode:$s, relationshipWeightProperty:'cost'}) YIELD sourceNode, targetNode, totalCost RETURN targetNode AS nodeId, totalCost ORDER BY totalCost ASC LIMIT 1000", {'g':g,'s':node})
            # Attach address
            sp = gds.run_cypher("CALL gds.shortestPath.dijkstra.stream($g,{sourceNode:$s, relationshipWeightProperty:'cost'}) YIELD targetNode, totalCost WITH targetNode, totalCost, gds.util.asNode(targetNode) AS n RETURN targetNode AS nodeId, totalCost, coalesce(n.address,n.hash,n.id,n.addr) AS address ORDER BY totalCost ASC LIMIT 500", {'g':g,'s':node})
        except Exception as e:
            outs[v['name']]={'error':f'dijkstra failed: {e}'}
            try:
                gds.run_cypher("CALL gds.graph.drop($g)", {'g':g})
            except Exception:
                pass
            continue
        df=sp
        # Degree sinkness on same graph
        try:
            indeg=gds.run_cypher("CALL gds.degree.stream($g,{orientation:'IN'}) YIELD nodeId, score RETURN nodeId, score AS inD", {'g':g})
            outdeg=gds.run_cypher("CALL gds.degree.stream($g,{orientation:'OUT'}) YIELD nodeId, score RETURN nodeId, score AS outD", {'g':g})
            indeg=indeg.set_index('nodeId'); outdeg=outdeg.set_index('nodeId')
            deg=indeg.join(outdeg, how='outer').fillna(0.0)
            deg['sinkness']=deg['inD']/(1+deg['outD'])
            df=df.merge(deg.reset_index(), on='nodeId', how='left')
        except Exception:
            df['sinkness']=0.0
        # Confidence: inverse cost times sinkness
        df['conf']= (1.0/(1.0+df['totalCost'])) * (1.0 + df.get('sinkness',0.0))
        df=df.dropna(subset=['address']); df=df[df['address'].astype(str).str.startswith('0x')]
        outs[v['name']]={'df':df, 'proj':{'nodeCount':int(proj['nodeCount'][0]), 'relationshipCount':int(proj['relationshipCount'][0])}}
    else:
        # BFS distances
        try:
            bfs=gds.run_cypher("CALL gds.bfs.stream($g,{sourceNode:$s, maxDepth:5}) YIELD nodeId, depth WITH nodeId, depth, gds.util.asNode(nodeId) AS n RETURN nodeId, depth, coalesce(n.address,n.hash,n.id,n.addr) AS address ORDER BY depth ASC, nodeId ASC LIMIT 2000", {'g':g,'s':node})
        except Exception as e:
            outs[v['name']]={'error':f'bfs failed: {e}'}
            try:
                gds.run_cypher("CALL gds.graph.drop($g)", {'g':g})
            except Exception:
                pass
            continue
        # Degree sinkness
        try:
            indeg=gds.run_cypher("CALL gds.degree.stream($g,{orientation:'IN'}) YIELD nodeId, score RETURN nodeId, score AS inD", {'g':g})
            outdeg=gds.run_cypher("CALL gds.degree.stream($g,{orientation:'OUT'}) YIELD nodeId, score RETURN nodeId, score AS outD", {'g':g})
            indeg=indeg.set_index('nodeId'); outdeg=outdeg.set_index('nodeId')
            deg=indeg.join(outdeg, how='outer').fillna(0.0)
            deg['sinkness']=deg['inD']/(1+deg['outD'])
            bfs=bfs.merge(deg.reset_index(), on='nodeId', how='left')
        except Exception:
            bfs['sinkness']=0.0
        # Confidence: closer depth is higher, weight by sinkness
        bfs['conf']= (1.0/(1.0+bfs['depth'])) * (1.0 + bfs.get('sinkness',0.0))
        bfs=bfs.dropna(subset=['address']); bfs=bfs[bfs['address'].astype(str).str.startswith('0x')]
        outs[v['name']]={'df':bfs, 'proj':{'nodeCount':int(proj['nodeCount'][0]), 'relationshipCount':int(proj['relationshipCount'][0])}}

    try:
        gds.run_cypher("CALL gds.graph.drop($g)", {'g':g})
    except Exception:
        pass

# Summarize status
status={k: (('ok', v['proj']['nodeCount'], v['proj']['relationshipCount'], len(v['df'])) if 'df' in v else ('err', v.get('error'))) for k,v in outs.items()}
print(status)
for k,v in outs.items():
    if 'df' in v:
        print('SAMPLE', k, v['df'].head(30)['address'].tolist())
        break

