import os
from graphdatascience import GraphDataScience
import pandas as pd
import numpy as np
import json
import random
import string
from datetime import datetime, timezone

NEO4J_URI = os.getenv('NEO4J_URI')
NEO4J_USERNAME = os.getenv('NEO4J_USERNAME')
NEO4J_PASSWORD = os.getenv('NEO4J_PASSWORD')
NEO4J_DATABASE = os.getenv('NEO4J_DATABASE') or 'neo4j'

try:
    if not (NEO4J_URI and NEO4J_USERNAME and NEO4J_PASSWORD):
        raise RuntimeError("Missing Neo4j environment variables NEO4J_URI/USERNAME/PASSWORD")

    gds = GraphDataScience(NEO4J_URI, auth=(NEO4J_USERNAME, NEO4J_PASSWORD), database=NEO4J_DATABASE)

    def run_cypher(query, params=None):
        return gds.run_cypher(query, params or {})

    stolen_addr = '0x1db92e2eebc8e0c075a02bea49a2935bcd2dfcf4'

    # 1) Find node for address
    q_find = """
    MATCH (n)
    WHERE (n.address IS NOT NULL AND toLower(n.address) = toLower($addr))
       OR (n.id IS NOT NULL AND toLower(n.id) = toLower($addr))
       OR (n.hash IS NOT NULL AND toLower(n.hash) = toLower($addr))
       OR (n.addr IS NOT NULL AND toLower(n.addr) = toLower($addr))
    RETURN id(n) AS nid, labels(n) AS labels, keys(n) AS keys, n
    LIMIT 1
    """
    df_find = run_cypher(q_find, {"addr": stolen_addr})
    if df_find.empty:
        raise RuntimeError("Could not find node for stolen address in DB")
    nid = int(df_find.loc[0, 'nid'])
    node_props = df_find.loc[0, 'n']

    node_addr_prop_candidates = ['address', 'id', 'hash', 'addr']
    node_addr_prop = None
    for k in node_addr_prop_candidates:
        if k in node_props and isinstance(node_props[k], str) and node_props[k].lower() == stolen_addr.lower():
            node_addr_prop = k
            break
    if node_addr_prop is None:
        for k, v in node_props.items():
            if isinstance(v, str) and v.lower() == stolen_addr.lower():
                node_addr_prop = k
                break
    if node_addr_prop is None:
        node_addr_prop = 'address'

    # 2) Determine relationship type 
    q_reltypes = """
    MATCH (n)-[r]->() WHERE id(n)=$nid
    RETURN type(r) AS type, count(*) AS c ORDER BY c DESC LIMIT 5
    """
    df_types_out = run_cypher(q_reltypes, {"nid": nid})
    if df_types_out.empty:
        raise RuntimeError("No outgoing relationships from stolen address node; cannot analyze transfers")

    type_order_pref = ['TRANSFER', 'TRANSFERS', 'SENT_TO', 'SEND', 'TRANSFERRED_TO', 'TX', 'TRANSACTION', 'SENT', 'TO']
    rel_type = None
    types_list = df_types_out['type'].tolist()
    for pref in type_order_pref:
        for t in types_list:
            if t.upper() == pref:
                rel_type = t
                break
        if rel_type:
            break
    if rel_type is None:
        rel_type = df_types_out.loc[0, 'type']

    # 3) Sample some relationships to identify property keys for value and timestamp
    q_sample = f"""
    MATCH (n)-[r:`{rel_type}`]->() WHERE id(n)=$nid
    RETURN r LIMIT 200
    """
    df_sample = run_cypher(q_sample, {"nid": nid})
    rel_prop_keys = set()
    rel_rows = []
    for _, row in df_sample.iterrows():
        rprops = row['r']
        rel_rows.append(rprops)
        rel_prop_keys.update(rprops.keys())

    TIME_KEYS = ['timestamp', 'block_timestamp', 'blockTimestamp', 'time', 'ts', 'block_time', 'datetime']
    VALUE_KEYS = ['value', 'amount', 'value_eth', 'valueEth', 'eth', 'value_wei', 'valueWei', 'wei', 'amount_wei', 'amountWei']

    time_prop = None
    for k in TIME_KEYS:
        if k in rel_prop_keys:
            time_prop = k
            break
    if time_prop is None and rel_rows:
        for k in rel_prop_keys:
            vals = [rp.get(k) for rp in rel_rows if k in rp]
            if not vals:
                continue
            nums = [v for v in vals if isinstance(v, (int, float))]
            if len(nums) >= max(3, len(vals)//3):
                vmed = float(np.median(nums))
                if vmed > 1e8:
                    time_prop = k
                    break

    value_prop = None
    for k in VALUE_KEYS:
        if k in rel_prop_keys:
            value_prop = k
            break

    # 4) Determine time window by sampling property values
    start_ts_num = None  # seconds since epoch
    end_ts_num = None
    time_kind = None  # 'numeric' | 'string_iso' | 'temporal'

    if time_prop is not None:
        q_times = f"""
        MATCH (n)-[r:`{rel_type}`]->() WHERE id(n)=$nid AND r.`{time_prop}` IS NOT NULL
        RETURN r.`{time_prop}` AS ts LIMIT 2000
        """
        df_times = run_cypher(q_times, {"nid": nid})
        ts_vals = df_times['ts'].dropna().tolist()
        if ts_vals:
            sample = ts_vals[0]
            # numeric
            if isinstance(sample, (int, float)):
                arr = [float(x) for x in ts_vals if isinstance(x, (int, float))]
                vmed = float(np.median(arr))
                if vmed > 1e14:
                    scale = 1e-9
                elif vmed > 1e12:
                    scale = 1e-6
                elif vmed > 1e11:
                    scale = 1e-3
                else:
                    scale = 1.0
                start_raw = min(arr)
                start_ts_num = start_raw * scale
                end_ts_num = start_ts_num + 14*24*3600
                time_kind = 'numeric'
            elif isinstance(sample, str):
                pds = pd.to_datetime(pd.Series(ts_vals), utc=True, errors='coerce')
                pds = pds.dropna()
                if not pds.empty:
                    start_dt = pds.min().to_pydatetime().astimezone(timezone.utc)
                    start_ts_num = start_dt.timestamp()
                    end_ts_num = start_ts_num + 14*24*3600
                    time_kind = 'string_iso'
            else:
                # Try neo4j temporal
                try:
                    from neo4j.time import DateTime as NeoDateTime
                    if isinstance(sample, NeoDateTime):
                        pyts = []
                        for v in ts_vals:
                            try:
                                py = v.to_native()
                            except Exception:
                                py = datetime(v.year, v.month, v.day, v.hour, v.minute, int(v.second), tzinfo=timezone.utc)
                            pyts.append(py)
                        start_dt = min(pyts)
                        start_ts_num = start_dt.replace(tzinfo=timezone.utc).timestamp()
                        end_ts_num = start_ts_num + 14*24*3600
                        time_kind = 'temporal'
                except Exception:
                    pass
        if time_kind is None:
            time_prop = None

    # 5) Determine value scale and thresholds
    value_scale = 1.0
    baseline_min_val_eth = 0.0
    alt_min_val_eth = 0.0
    if value_prop is not None:
        q_vals = f"""
        MATCH (n)-[r:`{rel_type}`]->() WHERE id(n)=$nid AND r.`{value_prop}` IS NOT NULL
        RETURN r.`{value_prop}` AS v LIMIT 5000
        """
        df_vals = run_cypher(q_vals, {"nid": nid})
        raw_vals = df_vals['v'].dropna().tolist()
        vs = []
        for v in raw_vals:
            if isinstance(v, (int, float)):
                vs.append(float(v))
            elif isinstance(v, str):
                try:
                    vs.append(float(v))
                except Exception:
                    continue
        if len(vs) == 0:
            value_prop = None
        else:
            vmed = float(np.median(vs))
            vmax = float(max(vs)) if vs else 0.0
            if vmed > 1e12 or vmax > 1e15:
                value_scale = 1e-18
            else:
                value_scale = 1.0
            vs_eth = [v*value_scale for v in vs]
            if len(vs_eth) >= 5:
                p90 = float(np.percentile(vs_eth, 90))
                p50 = float(np.percentile(vs_eth, 50))
                baseline_min_val_eth = 0.0
                alt_min_val_eth = max(0.01, 0.25*p50, 0.1*p90)
            else:
                baseline_min_val_eth = 0.0
                alt_min_val_eth = 0.0

    # 6) BFS
    def expand_k_hops(max_hops=4, min_val_eth=0.0, time_kind=time_kind, start_ts_num=start_ts_num, end_ts_num=end_ts_num, limit_step=None):
        nodes = set([nid])
        frontier = set([nid])
        edges = set()
        min_val_raw = (min_val_eth / value_scale) if (value_prop is not None) else None
        time_where = ""
        params_base = {}
        if time_prop is not None and time_kind is not None and start_ts_num is not None and end_ts_num is not None:
            if time_kind == 'numeric':
                time_where = f" AND toFloat(r.`{time_prop}`) >= $start AND toFloat(r.`{time_prop}`) <= $end"
                params_base.update({"start": float(start_ts_num), "end": float(end_ts_num)})
            else:
                start_iso = datetime.fromtimestamp(start_ts_num, tz=timezone.utc).isoformat()
                end_iso = datetime.fromtimestamp(end_ts_num, tz=timezone.utc).isoformat()
                time_where = f" AND datetime(r.`{time_prop}`) >= datetime($startIso) AND datetime(r.`{time_prop}`) <= datetime($endIso)"
                params_base.update({"startIso": start_iso, "endIso": end_iso})
        for hop in range(max_hops):
            if not frontier:
                break
            q = f"""
            MATCH (s)-[r:`{rel_type}`]->(t)
            WHERE id(s) IN $frontier
            """
            params = {"frontier": list(frontier)}
            q += time_where
            params.update(params_base)
            if value_prop is not None and min_val_raw is not None and min_val_raw > 0:
                q += f" AND toFloat(r.`{value_prop}`) >= $minVal"
                params.update({"minVal": float(min_val_raw)})
            q += f" RETURN DISTINCT id(s) AS s, id(t) AS t"
            if limit_step is not None:
                q += " LIMIT $lim"
                params.update({"lim": int(limit_step)})
            df_step = run_cypher(q, params)
            new_frontier = set()
            for _, row in df_step.iterrows():
                s = int(row['s']); t = int(row['t'])
                edges.add((s,t))
                if t not in nodes:
                    new_frontier.add(t)
                    nodes.add(t)
            frontier = new_frontier
            if len(nodes) > 200000:
                break
        return nodes, edges

    baseline_params = {
        'max_hops': 4,
        'min_val_eth': baseline_min_val_eth,
        'time_kind': time_kind,
        'start_ts_num': start_ts_num,
        'end_ts_num': end_ts_num
    }
    alt_params = {
        'max_hops': 3,
        'min_val_eth': alt_min_val_eth,
        'time_kind': time_kind,
        'start_ts_num': start_ts_num,
        'end_ts_num': None
    }
    if start_ts_num is not None:
        alt_params['end_ts_num'] = start_ts_num + 7*24*3600

    nodes_base, edges_base = expand_k_hops(**baseline_params)
    nodes_alt, edges_alt = expand_k_hops(**alt_params)

    # Projection via Cypher call
    def project_gds_graph(nodes_set, min_val_eth=0.0, time_kind=time_kind, start_ts_num=start_ts_num, end_ts_num=end_ts_num):
        nodeIds = list(nodes_set)
        gname = 'g_' + ''.join(random.choices(string.ascii_lowercase+string.digits, k=8))
        nodeQuery = "MATCH (n) WHERE id(n) IN $nodeIds RETURN id(n) AS id"
        relQuery = f"MATCH (s)-[r:`{rel_type}`]->(t) WHERE id(s) IN $nodeIds AND id(t) IN $nodeIds"
        params = {"nodeIds": nodeIds}
        if time_prop is not None and time_kind is not None and start_ts_num is not None and end_ts_num is not None:
            if time_kind == 'numeric':
                relQuery += f" AND toFloat(r.`{time_prop}`) >= $start AND toFloat(r.`{time_prop}`) <= $end"
                params.update({"start": float(start_ts_num), "end": float(end_ts_num)})
            else:
                start_iso = datetime.fromtimestamp(start_ts_num, tz=timezone.utc).isoformat()
                end_iso = datetime.fromtimestamp(end_ts_num, tz=timezone.utc).isoformat()
                relQuery += f" AND datetime(r.`{time_prop}`) >= datetime($startIso) AND datetime(r.`{time_prop}`) <= datetime($endIso)"
                params.update({"startIso": start_iso, "endIso": end_iso})
        if value_prop is not None and min_val_eth is not None and min_val_eth > 0:
            min_raw = min_val_eth / value_scale
            relQuery += f" AND toFloat(r.`{value_prop}`) >= $minVal"
            params.update({"minVal": float(min_raw)})
        if value_prop is not None:
            relQuery += f" RETURN id(s) AS source, id(t) AS target, toFloat(r.`{value_prop}`) * $vscale AS weight"
            params.update({"vscale": float(value_scale)})
        else:
            relQuery += f" RETURN id(s) AS source, id(t) AS target"

        q_project = """
        CALL gds.graph.project.cypher($gname, $nodeQuery, $relQuery, {parameters: $params})
        YIELD graphName, nodeCount, relationshipCount
        RETURN graphName, nodeCount, relationshipCount
        """
        df_proj = run_cypher(q_project, {"gname": gname, "nodeQuery": nodeQuery, "relQuery": relQuery, "params": params})
        if df_proj.empty:
            raise RuntimeError("Failed to project graph")
        return gname

    def drop_graph(gname):
        try:
            run_cypher("CALL gds.graph.drop($gname)", {"gname": gname})
        except Exception:
            pass

    def run_ppr(gname):
        config = {
            'maxIterations': 80,
            'dampingFactor': 0.85,
            'personalized': True,
            'sourceNodes': [nid]
        }
        if value_prop is not None:
            config['relationshipWeightProperty'] = 'weight'
        df_scores = gds.pageRank.stream(gname, config)
        neo_ids = df_scores['nodeId'].astype(int).tolist()
        if neo_ids:
            q_map = f"MATCH (n) WHERE id(n) IN $ids RETURN id(n) AS id, n.`{node_addr_prop}` AS addr"
            df_map = run_cypher(q_map, {"ids": neo_ids})
            id2addr = {int(r['id']): r['addr'] for _, r in df_map.iterrows()}
            df_scores['address'] = df_scores['nodeId'].map(id2addr)
            df_scores = df_scores[(df_scores['address'].notna()) & (df_scores['address'].str.lower() != stolen_addr.lower())]
            df_scores = df_scores.sort_values('score', ascending=False)
        else:
            df_scores = pd.DataFrame(columns=['nodeId','score','address'])
        return df_scores

    def fetch_edges(nodes_set, min_val_eth=0.0, time_kind=time_kind, start_ts_num=start_ts_num, end_ts_num=end_ts_num):
        nodeIds = list(nodes_set)
        if not nodeIds:
            return pd.DataFrame(columns=['s','t','w'])
        q = f"MATCH (s)-[r:`{rel_type}`]->(t) WHERE id(s) IN $nodeIds AND id(t) IN $nodeIds"
        params = {"nodeIds": nodeIds}
        if time_prop is not None and time_kind is not None and start_ts_num is not None and end_ts_num is not None:
            if time_kind == 'numeric':
                q += f" AND toFloat(r.`{time_prop}`) >= $start AND toFloat(r.`{time_prop}`) <= $end"
                params.update({"start": float(start_ts_num), "end": float(end_ts_num)})
            else:
                start_iso = datetime.fromtimestamp(start_ts_num, tz=timezone.utc).isoformat()
                end_iso = datetime.fromtimestamp(end_ts_num, tz=timezone.utc).isoformat()
                q += f" AND datetime(r.`{time_prop}`) >= datetime($startIso) AND datetime(r.`{time_prop}`) <= datetime($endIso)"
                params.update({"startIso": start_iso, "endIso": end_iso})
        if value_prop is not None and min_val_eth is not None and min_val_eth > 0:
            min_raw = min_val_eth / value_scale
            q += f" AND toFloat(r.`{value_prop}`) >= $minVal"
            params.update({"minVal": float(min_raw)})
        if value_prop is not None:
            q += f" RETURN id(s) AS s, id(t) AS t, toFloat(r.`{value_prop}`) * $vscale AS w"
            params.update({"vscale": float(value_scale)})
        else:
            q += f" RETURN id(s) AS s, id(t) AS t, 1.0 AS w"
        df = run_cypher(q, params)
        return df

    gname_base = project_gds_graph(nodes_base, min_val_eth=baseline_params['min_val_eth'], time_kind=baseline_params['time_kind'], start_ts_num=baseline_params['start_ts_num'], end_ts_num=baseline_params['end_ts_num'])
    gname_alt = project_gds_graph(nodes_alt, min_val_eth=alt_params['min_val_eth'], time_kind=alt_params['time_kind'], start_ts_num=alt_params['start_ts_num'], end_ts_num=alt_params['end_ts_num'])

    ppr_base_df = run_ppr(gname_base)
    ppr_alt_df = run_ppr(gname_alt)

    drop_graph(gname_base)
    drop_graph(gname_alt)

    def taint_propagation(nodes_set, min_val_eth=0.0, time_kind=time_kind, start_ts_num=start_ts_num, end_ts_num=end_ts_num, K=4):
        df_edges = fetch_edges(nodes_set, min_val_eth=min_val_eth, time_kind=time_kind, start_ts_num=start_ts_num, end_ts_num=end_ts_num)
        out_map = {}
        for _, row in df_edges.iterrows():
            s = int(row['s']); t = int(row['t']); w = float(row['w'])
            out_map.setdefault(s, []).append((t, w))
        denom = {s: sum(w for (_, w) in lst) for s, lst in out_map.items()}
        node_list = list(set(list(df_edges['s'].astype(int)) + list(df_edges['t'].astype(int)) + [nid]))
        id2idx = {n:i for i,n in enumerate(node_list)}
        idx2id = {i:n for n,i in id2idx.items()}
        nN = len(node_list)
        tvec = np.zeros(nN, dtype=float)
        if nid in id2idx:
            tvec[id2idx[nid]] = 1.0
        else:
            return pd.DataFrame(columns=['nodeId', 'score', 'address'])
        cum = np.zeros(nN, dtype=float)
        cur = tvec.copy()
        for step in range(K):
            nxt = np.zeros(nN, dtype=float)
            for s, lst in out_map.items():
                si = id2idx.get(s)
                if si is None:
                    continue
                if denom.get(s, 0.0) <= 0 or cur[si] == 0:
                    continue
                frac = cur[si] / denom[s]
                for (t, w) in lst:
                    ti = id2idx.get(t)
                    if ti is None:
                        continue
                    nxt[ti] += frac * w
            cum += nxt
            cur = nxt
        rows = []
        for i in range(nN):
            node_id = int(idx2id[i])
            score = float(cum[i])
            rows.append((node_id, score))
        df = pd.DataFrame(rows, columns=['nodeId', 'score'])
        neo_ids = df['nodeId'].astype(int).tolist()
        if neo_ids:
            q_map = f"MATCH (n) WHERE id(n) IN $ids RETURN id(n) AS id, n.`{node_addr_prop}` AS addr"
            df_map = run_cypher(q_map, {"ids": neo_ids})
            id2addr = {int(r['id']): r['addr'] for _, r in df_map.iterrows()}
            df['address'] = df['nodeId'].map(id2addr)
            df = df[(df['address'].notna()) & (df['address'].str.lower() != stolen_addr.lower())]
            df = df.sort_values('score', ascending=False)
        else:
            df = pd.DataFrame(columns=['nodeId','score','address'])
        return df

    taint_base_df = taint_propagation(nodes_base, min_val_eth=baseline_params['min_val_eth'], time_kind=baseline_params['time_kind'], start_ts_num=baseline_params['start_ts_num'], end_ts_num=baseline_params['end_ts_num'], K=4)
    taint_alt_df = taint_propagation(nodes_alt, min_val_eth=alt_params['min_val_eth'], time_kind=alt_params['time_kind'], start_ts_num=alt_params['start_ts_num'], end_ts_num=alt_params['end_ts_num'], K=3)

    def topk_addresses(df, k=200):
        if df is None or df.empty:
            return []
        dfn = df.copy()
        maxs = dfn['score'].max()
        if pd.isna(maxs) or maxs == 0:
            dfn['norm'] = 0.0
        else:
            dfn['norm'] = dfn['score'] / maxs
        dfn = dfn[['address', 'score', 'norm']]
        dfn = dfn.dropna(subset=['address'])
        dfn = dfn.groupby('address', as_index=False).agg({'score':'max','norm':'max'})
        dfn = dfn.sort_values(['norm','score'], ascending=[False, False])
        return dfn.head(k).to_dict(orient='records')

    top_ppr_base = topk_addresses(ppr_base_df, 300)
    top_ppr_alt = topk_addresses(ppr_alt_df, 300)
    top_taint_base = topk_addresses(taint_base_df, 300)
    top_taint_alt = topk_addresses(taint_alt_df, 300)

    def to_rank_map(lst):
        return {rec['address'].lower(): i for i, rec in enumerate(lst)}

    r_ppr_b = to_rank_map(top_ppr_base)
    r_ppr_a = to_rank_map(top_ppr_alt)
    r_tai_b = to_rank_map(top_taint_base)
    r_tai_a = to_rank_map(top_taint_alt)

    all_addrs = set(list(r_ppr_b.keys()) + list(r_ppr_a.keys()) + list(r_tai_b.keys()) + list(r_tai_a.keys()))

    stability_rows = []
    for addr in all_addrs:
        ranks = []
        for r in [r_ppr_b, r_ppr_a, r_tai_b, r_tai_a]:
            if addr in r:
                ranks.append(r[addr])
        presence = len(ranks)
        avg_rank = float(np.mean(ranks)) if ranks else None
        best_rank = float(np.min(ranks)) if ranks else None
        stability_rows.append({
            'address': addr,
            'presence': presence,
            'avg_rank': avg_rank,
            'best_rank': best_rank
        })
    stab_df = pd.DataFrame(stability_rows)
    if not stab_df.empty:
        stab_df['stability'] = stab_df['presence']*1.0 + stab_df['best_rank'].apply(lambda x: 0 if x is None else max(0, 200 - x)/200.0)

    if top_taint_base:
        df_final = pd.DataFrame(top_taint_base)
        df_final['addr_lower'] = df_final['address'].str.lower()
        df_stab = stab_df.rename(columns={'address': 'addr_lower'})
        df_merged = pd.merge(df_final, df_stab[['addr_lower','stability','presence']], on='addr_lower', how='left')
        df_merged['stability'] = df_merged['stability'].fillna(0)
        df_merged['presence'] = df_merged['presence'].fillna(0)
        df_merged['composite'] = df_merged['norm'] + 0.2*df_merged['stability'] + 0.1*df_merged['presence']
        df_merged = df_merged.sort_values(['composite','norm','score'], ascending=[False, False, False])
        final_addresses = df_merged['address'].tolist()
    else:
        final_addresses = [rec['address'] for rec in top_ppr_base]

    final_addresses = final_addresses[:100]

    uncertain = []
    if not stab_df.empty:
        df_unc = stab_df.copy()
        df_unc = df_unc[df_unc['presence'] <= 1]
        df_unc = df_unc.sort_values(['presence','best_rank'], ascending=[True, True]).head(20)
        uncertain = [a for a in df_unc['address'].tolist()]

    meta = {
        'db': NEO4J_DATABASE,
        'rel_type': rel_type,
        'time_prop': time_prop,
        'value_prop': value_prop,
        'time_kind': time_kind,
        'value_scale_to_eth': value_scale,
        'baseline_params': baseline_params,
        'alt_params': alt_params,
        'counts': {
            'nodes_base': len(nodes_base), 'edges_base': len(edges_base),
            'nodes_alt': len(nodes_alt), 'edges_alt': len(edges_alt)
        },
    }

    payload = {
        'ok': True,
        'meta': meta,
        'ppr_base_top': top_ppr_base,
        'ppr_alt_top': top_ppr_alt,
        'taint_base_top': top_taint_base,
        'taint_alt_top': top_taint_alt,
        'final_addresses': final_addresses,
        'uncertain_addresses': uncertain
    }
    print(json.dumps(payload))
except Exception as e:
    print(json.dumps({"ok": False, "error": str(e)}))

import os
from graphdatascience import GraphDataScience
import pandas as pd
import numpy as np
import json
import random
import string
from datetime import datetime, timezone

NEO4J_URI = os.getenv('NEO4J_URI')
NEO4J_USERNAME = os.getenv('NEO4J_USERNAME')
NEO4J_PASSWORD = os.getenv('NEO4J_PASSWORD')
NEO4J_DATABASE = os.getenv('NEO4J_DATABASE') or 'neo4j'

try:
    if not (NEO4J_URI and NEO4J_USERNAME and NEO4J_PASSWORD):
        raise RuntimeError("Missing Neo4j environment variables NEO4J_URI/USERNAME/PASSWORD")

    gds = GraphDataScience(NEO4J_URI, auth=(NEO4J_USERNAME, NEO4J_PASSWORD), database=NEO4J_DATABASE)

    def run_cypher(query, params=None):
        return gds.run_cypher(query, params or {})

    stolen_addr = '0x1db92e2eebc8e0c075a02bea49a2935bcd2dfcf4'

    # 1) Find node for address
    q_find = """
    MATCH (n)
    WHERE (n.address IS NOT NULL AND toLower(n.address) = toLower($addr))
       OR (n.id IS NOT NULL AND toLower(n.id) = toLower($addr))
       OR (n.hash IS NOT NULL AND toLower(n.hash) = toLower($addr))
       OR (n.addr IS NOT NULL AND toLower(n.addr) = toLower($addr))
    RETURN id(n) AS nid, labels(n) AS labels, keys(n) AS keys, n
    LIMIT 1
    """
    df_find = run_cypher(q_find, {"addr": stolen_addr})
    if df_find.empty:
        raise RuntimeError("Could not find node for stolen address in DB")
    nid = int(df_find.loc[0, 'nid'])
    node_props = df_find.loc[0, 'n']

    node_addr_prop_candidates = ['address', 'id', 'hash', 'addr']
    node_addr_prop = None
    for k in node_addr_prop_candidates:
        if k in node_props and isinstance(node_props[k], str) and node_props[k].lower() == stolen_addr.lower():
            node_addr_prop = k
            break
    if node_addr_prop is None:
        for k, v in node_props.items():
            if isinstance(v, str) and v.lower() == stolen_addr.lower():
                node_addr_prop = k
                break
    if node_addr_prop is None:
        node_addr_prop = 'address'

    # 2) Determine relationship type 
    q_reltypes = """
    MATCH (n)-[r]->() WHERE id(n)=$nid
    RETURN type(r) AS type, count(*) AS c ORDER BY c DESC LIMIT 5
    """
    df_types_out = run_cypher(q_reltypes, {"nid": nid})
    if df_types_out.empty:
        raise RuntimeError("No outgoing relationships from stolen address node; cannot analyze transfers")

    type_order_pref = ['TRANSFER', 'TRANSFERS', 'SENT_TO', 'SEND', 'TRANSFERRED_TO', 'TX', 'TRANSACTION', 'SENT', 'TO']
    rel_type = None
    types_list = df_types_out['type'].tolist()
    for pref in type_order_pref:
        for t in types_list:
            if t.upper() == pref:
                rel_type = t
                break
        if rel_type:
            break
    if rel_type is None:
        rel_type = df_types_out.loc[0, 'type']

    # 3) Sample some relationships to identify property keys for value and timestamp
    q_sample = f"""
    MATCH (n)-[r:`{rel_type}`]->() WHERE id(n)=$nid
    RETURN r LIMIT 200
    """
    df_sample = run_cypher(q_sample, {"nid": nid})
    rel_prop_keys = set()
    rel_rows = []
    for _, row in df_sample.iterrows():
        rprops = row['r']
        rel_rows.append(rprops)
        rel_prop_keys.update(rprops.keys())

    TIME_KEYS = ['timestamp', 'block_timestamp', 'blockTimestamp', 'time', 'ts', 'block_time', 'datetime']
    VALUE_KEYS = ['value', 'amount', 'value_eth', 'valueEth', 'eth', 'value_wei', 'valueWei', 'wei', 'amount_wei', 'amountWei']

    time_prop = None
    for k in TIME_KEYS:
        if k in rel_prop_keys:
            time_prop = k
            break
    if time_prop is None and rel_rows:
        for k in rel_prop_keys:
            vals = [rp.get(k) for rp in rel_rows if k in rp]
            if not vals:
                continue
            nums = [v for v in vals if isinstance(v, (int, float))]
            if len(nums) >= max(3, len(vals)//3):
                vmed = float(np.median(nums))
                if vmed > 1e8:
                    time_prop = k
                    break

    value_prop = None
    for k in VALUE_KEYS:
        if k in rel_prop_keys:
            value_prop = k
            break

    # 4) Determine time window by sampling property values
    start_ts_num = None  # seconds since epoch
    end_ts_num = None
    time_kind = None  # 'numeric' | 'string_iso' | 'temporal'

    if time_prop is not None:
        q_times = f"""
        MATCH (n)-[r:`{rel_type}`]->() WHERE id(n)=$nid AND r.`{time_prop}` IS NOT NULL
        RETURN r.`{time_prop}` AS ts LIMIT 2000
        """
        df_times = run_cypher(q_times, {"nid": nid})
        ts_vals = df_times['ts'].dropna().tolist()
        if ts_vals:
            sample = ts_vals[0]
            if isinstance(sample, (int, float)):
                arr = [float(x) for x in ts_vals if isinstance(x, (int, float))]
                vmed = float(np.median(arr))
                if vmed > 1e14:
                    scale = 1e-9
                elif vmed > 1e12:
                    scale = 1e-6
                elif vmed > 1e11:
                    scale = 1e-3
                else:
                    scale = 1.0
                start_raw = min(arr)
                start_ts_num = start_raw * scale
                end_ts_num = start_ts_num + 14*24*3600
                time_kind = 'numeric'
            elif isinstance(sample, str):
                pds = pd.to_datetime(pd.Series(ts_vals), utc=True, errors='coerce')
                pds = pds.dropna()
                if not pds.empty:
                    start_dt = pds.min().to_pydatetime().astimezone(timezone.utc)
                    start_ts_num = start_dt.timestamp()
                    end_ts_num = start_ts_num + 14*24*3600
                    time_kind = 'string_iso'
            else:
                try:
                    from neo4j.time import DateTime as NeoDateTime
                    if isinstance(sample, NeoDateTime):
                        pyts = []
                        for v in ts_vals:
                            try:
                                py = v.to_native()
                            except Exception:
                                py = datetime(v.year, v.month, v.day, v.hour, v.minute, int(v.second), tzinfo=timezone.utc)
                            pyts.append(py)
                        start_dt = min(pyts)
                        start_ts_num = start_dt.replace(tzinfo=timezone.utc).timestamp()
                        end_ts_num = start_ts_num + 14*24*3600
                        time_kind = 'temporal'
                except Exception:
                    pass
        if time_kind is None:
            time_prop = None

    # 5) Determine value scale and thresholds
    value_scale = 1.0
    baseline_min_val_eth = 0.0
    alt_min_val_eth = 0.0
    if value_prop is not None:
        q_vals = f"""
        MATCH (n)-[r:`{rel_type}`]->() WHERE id(n)=$nid AND r.`{value_prop}` IS NOT NULL
        RETURN r.`{value_prop}` AS v LIMIT 5000
        """
        df_vals = run_cypher(q_vals, {"nid": nid})
        raw_vals = df_vals['v'].dropna().tolist()
        vs = []
        for v in raw_vals:
            if isinstance(v, (int, float)):
                vs.append(float(v))
            elif isinstance(v, str):
                try:
                    vs.append(float(v))
                except Exception:
                    continue
        if len(vs) == 0:
            value_prop = None
        else:
            vmed = float(np.median(vs))
            vmax = float(max(vs)) if vs else 0.0
            if vmed > 1e12 or vmax > 1e15:
                value_scale = 1e-18
            else:
                value_scale = 1.0
            vs_eth = [v*value_scale for v in vs]
            if len(vs_eth) >= 5:
                p90 = float(np.percentile(vs_eth, 90))
                p50 = float(np.percentile(vs_eth, 50))
                baseline_min_val_eth = 0.0
                alt_min_val_eth = max(0.01, 0.25*p50, 0.1*p90)
            else:
                baseline_min_val_eth = 0.0
                alt_min_val_eth = 0.0

    # 6) BFS
    def expand_k_hops(max_hops=4, min_val_eth=0.0, time_kind=time_kind, start_ts_num=start_ts_num, end_ts_num=end_ts_num, limit_step=None):
        nodes = set([nid])
        frontier = set([nid])
        edges = set()
        min_val_raw = (min_val_eth / value_scale) if (value_prop is not None) else None
        time_where = ""
        params_base = {}
        if time_prop is not None and time_kind is not None and start_ts_num is not None and end_ts_num is not None:
            if time_kind == 'numeric':
                time_where = f" AND toFloat(r.`{time_prop}`) >= $start AND toFloat(r.`{time_prop}`) <= $end"
                params_base.update({"start": float(start_ts_num), "end": float(end_ts_num)})
            else:
                start_iso = datetime.fromtimestamp(start_ts_num, tz=timezone.utc).isoformat()
                end_iso = datetime.fromtimestamp(end_ts_num, tz=timezone.utc).isoformat()
                time_where = f" AND datetime(r.`{time_prop}`) >= datetime($startIso) AND datetime(r.`{time_prop}`) <= datetime($endIso)"
                params_base.update({"startIso": start_iso, "endIso": end_iso})
        for hop in range(max_hops):
            if not frontier:
                break
            q = f"MATCH (s)-[r:`{rel_type}`]->(t) WHERE id(s) IN $frontier"
            params = {"frontier": list(frontier)}
            q += time_where
            params.update(params_base)
            if value_prop is not None and min_val_raw is not None and min_val_raw > 0:
                q += f" AND toFloat(r.`{value_prop}`) >= $minVal"
                params.update({"minVal": float(min_val_raw)})
            q += f" RETURN DISTINCT id(s) AS s, id(t) AS t"
            if limit_step is not None:
                q += " LIMIT $lim"
                params.update({"lim": int(limit_step)})
            df_step = run_cypher(q, params)
            new_frontier = set()
            for _, row in df_step.iterrows():
                s = int(row['s']); t = int(row['t'])
                edges.add((s,t))
                if t not in nodes:
                    new_frontier.add(t)
                    nodes.add(t)
            frontier = new_frontier
            if len(nodes) > 200000:
                break
        return nodes, edges

    baseline_params = {
        'max_hops': 4,
        'min_val_eth': baseline_min_val_eth,
        'time_kind': time_kind,
        'start_ts_num': start_ts_num,
        'end_ts_num': end_ts_num
    }
    alt_params = {
        'max_hops': 3,
        'min_val_eth': alt_min_val_eth,
        'time_kind': time_kind,
        'start_ts_num': start_ts_num,
        'end_ts_num': None
    }
    if start_ts_num is not None:
        alt_params['end_ts_num'] = start_ts_num + 7*24*3600

    nodes_base, edges_base = expand_k_hops(**baseline_params)
    nodes_alt, edges_alt = expand_k_hops(**alt_params)

    def project_gds_graph(nodes_set, min_val_eth=0.0, time_kind=time_kind, start_ts_num=start_ts_num, end_ts_num=end_ts_num):
        nodeIds = list(nodes_set)
        gname = 'g_' + ''.join(random.choices(string.ascii_lowercase+string.digits, k=8))
        nodeQuery = "MATCH (n) WHERE id(n) IN $nodeIds RETURN id(n) AS id"
        relQuery = f"MATCH (s)-[r:`{rel_type}`]->(t) WHERE id(s) IN $nodeIds AND id(t) IN $nodeIds"
        params = {"nodeIds": nodeIds}
        if time_prop is not None and time_kind is not None and start_ts_num is not None and end_ts_num is not None:
            if time_kind == 'numeric':
                relQuery += f" AND toFloat(r.`{time_prop}`) >= $start AND toFloat(r.`{time_prop}`) <= $end"
                params.update({"start": float(start_ts_num), "end": float(end_ts_num)})
            else:
                start_iso = datetime.fromtimestamp(start_ts_num, tz=timezone.utc).isoformat()
                end_iso = datetime.fromtimestamp(end_ts_num, tz=timezone.utc).isoformat()
                relQuery += f" AND datetime(r.`{time_prop}`) >= datetime($startIso) AND datetime(r.`{time_prop}`) <= datetime($endIso)"
                params.update({"startIso": start_iso, "endIso": end_iso})
        if value_prop is not None and min_val_eth is not None and min_val_eth > 0:
            min_raw = min_val_eth / value_scale
            relQuery += f" AND toFloat(r.`{value_prop}`) >= $minVal"
            params.update({"minVal": float(min_raw)})
        if value_prop is not None:
            relQuery += f" RETURN id(s) AS source, id(t) AS target, toFloat(r.`{value_prop}`) * $vscale AS weight"
            params.update({"vscale": float(value_scale)})
        else:
            relQuery += f" RETURN id(s) AS source, id(t) AS target"
        q_project = """
        CALL gds.graph.project.cypher($gname, $nodeQuery, $relQuery, {parameters: $params})
        YIELD graphName, nodeCount, relationshipCount
        RETURN graphName, nodeCount, relationshipCount
        """
        df_proj = run_cypher(q_project, {"gname": gname, "nodeQuery": nodeQuery, "relQuery": relQuery, "params": params})
        if df_proj.empty:
            raise RuntimeError("Failed to project graph")
        return gname

    def drop_graph(gname):
        try:
            run_cypher("CALL gds.graph.drop($gname)", {"gname": gname})
        except Exception:
            pass

    def run_pr(gname):
        config = {
            'maxIterations': 80,
            'dampingFactor': 0.85
        }
        if value_prop is not None:
            config['relationshipWeightProperty'] = 'weight'
        q = """
        CALL gds.pageRank.stream($gname, $config)
        YIELD nodeId, score
        WITH gds.util.asNode(nodeId) AS n, score
        WHERE toLower(n[$addrProp]) <> toLower($stolen)
        RETURN id(n) AS nodeId, score, n[$addrProp] AS address
        ORDER BY score DESC
        """
        df_scores = run_cypher(q, {"gname": gname, "config": config, "addrProp": node_addr_prop, "stolen": stolen_addr})
        return df_scores

    def fetch_edges(nodes_set, min_val_eth=0.0, time_kind=time_kind, start_ts_num=start_ts_num, end_ts_num=end_ts_num):
        nodeIds = list(nodes_set)
        if not nodeIds:
            return pd.DataFrame(columns=['s','t','w'])
        q = f"MATCH (s)-[r:`{rel_type}`]->(t) WHERE id(s) IN $nodeIds AND id(t) IN $nodeIds"
        params = {"nodeIds": nodeIds}
        if time_prop is not None and time_kind is not None and start_ts_num is not None and end_ts_num is not None:
            if time_kind == 'numeric':
                q += f" AND toFloat(r.`{time_prop}`) >= $start AND toFloat(r.`{time_prop}`) <= $end"
                params.update({"start": float(start_ts_num), "end": float(end_ts_num)})
            else:
                start_iso = datetime.fromtimestamp(start_ts_num, tz=timezone.utc).isoformat()
                end_iso = datetime.fromtimestamp(end_ts_num, tz=timezone.utc).isoformat()
                q += f" AND datetime(r.`{time_prop}`) >= datetime($startIso) AND datetime(r.`{time_prop}`) <= datetime($endIso)"
                params.update({"startIso": start_iso, "endIso": end_iso})
        if value_prop is not None and min_val_eth is not None and min_val_eth > 0:
            min_raw = min_val_eth / value_scale
            q += f" AND toFloat(r.`{value_prop}`) >= $minVal"
            params.update({"minVal": float(min_raw)})
        if value_prop is not None:
            q += f" RETURN id(s) AS s, id(t) AS t, toFloat(r.`{value_prop}`) * $vscale AS w"
            params.update({"vscale": float(value_scale)})
        else:
            q += f" RETURN id(s) AS s, id(t) AS t, 1.0 AS w"
        df = run_cypher(q, params)
        return df

    gname_base = project_gds_graph(nodes_base, min_val_eth=baseline_params['min_val_eth'], time_kind=baseline_params['time_kind'], start_ts_num=baseline_params['start_ts_num'], end_ts_num=baseline_params['end_ts_num'])
    gname_alt = project_gds_graph(nodes_alt, min_val_eth=alt_params['min_val_eth'], time_kind=alt_params['time_kind'], start_ts_num=alt_params['start_ts_num'], end_ts_num=alt_params['end_ts_num'])

    pr_base_df = run_pr(gname_base)
    pr_alt_df = run_pr(gname_alt)

    drop_graph(gname_base)
    drop_graph(gname_alt)

    def taint_propagation(nodes_set, min_val_eth=0.0, time_kind=time_kind, start_ts_num=start_ts_num, end_ts_num=end_ts_num, K=4):
        df_edges = fetch_edges(nodes_set, min_val_eth=min_val_eth, time_kind=time_kind, start_ts_num=start_ts_num, end_ts_num=end_ts_num)
        out_map = {}
        for _, row in df_edges.iterrows():
            s = int(row['s']); t = int(row['t']); w = float(row['w'])
            out_map.setdefault(s, []).append((t, w))
        denom = {s: sum(w for (_, w) in lst) for s, lst in out_map.items()}
        node_list = list(set(list(df_edges['s'].astype(int)) + list(df_edges['t'].astype(int)) + [nid]))
        id2idx = {n:i for i,n in enumerate(node_list)}
        idx2id = {i:n for n,i in id2idx.items()}
        nN = len(node_list)
        tvec = np.zeros(nN, dtype=float)
        if nid in id2idx:
            tvec[id2idx[nid]] = 1.0
        else:
            return pd.DataFrame(columns=['nodeId', 'score', 'address'])
        cum = np.zeros(nN, dtype=float)
        cur = tvec.copy()
        for step in range(K):
            nxt = np.zeros(nN, dtype=float)
            for s, lst in out_map.items():
                si = id2idx.get(s)
                if si is None:
                    continue
                if denom.get(s, 0.0) <= 0 or cur[si] == 0:
                    continue
                frac = cur[si] / denom[s]
                for (t, w) in lst:
                    ti = id2idx.get(t)
                    if ti is None:
                        continue
                    nxt[ti] += frac * w
            cum += nxt
            cur = nxt
        rows = []
        for i in range(nN):
            node_id = int(idx2id[i])
            score = float(cum[i])
            rows.append((node_id, score))
        df = pd.DataFrame(rows, columns=['nodeId', 'score'])
        neo_ids = df['nodeId'].astype(int).tolist()
        if neo_ids:
            q_map = f"MATCH (n) WHERE id(n) IN $ids RETURN id(n) AS id, n.`{node_addr_prop}` AS addr"
            df_map = run_cypher(q_map, {"ids": neo_ids})
            id2addr = {int(r['id']): r['addr'] for _, r in df_map.iterrows()}
            df['address'] = df['nodeId'].map(id2addr)
            df = df[(df['address'].notna()) & (df['address'].str.lower() != stolen_addr.lower())]
            df = df.sort_values('score', ascending=False)
        else:
            df = pd.DataFrame(columns=['nodeId','score','address'])
        return df

    taint_base_df = taint_propagation(nodes_base, min_val_eth=baseline_params['min_val_eth'], time_kind=baseline_params['time_kind'], start_ts_num=baseline_params['start_ts_num'], end_ts_num=baseline_params['end_ts_num'], K=4)
    taint_alt_df = taint_propagation(nodes_alt, min_val_eth=alt_params['min_val_eth'], time_kind=alt_params['time_kind'], start_ts_num=alt_params['start_ts_num'], end_ts_num=alt_params['end_ts_num'], K=3)

    def topk_addresses(df, k=200):
        if df is None or df.empty:
            return []
        dfn = df.copy()
        maxs = dfn['score'].max()
        if pd.isna(maxs) or maxs == 0:
            dfn['norm'] = 0.0
        else:
            dfn['norm'] = dfn['score'] / maxs
        dfn = dfn[['address', 'score', 'norm']]
        dfn = dfn.dropna(subset=['address'])
        dfn = dfn.groupby('address', as_index=False).agg({'score':'max','norm':'max'})
        dfn = dfn.sort_values(['norm','score'], ascending=[False, False])
        return dfn.head(k).to_dict(orient='records')

    top_pr_base = topk_addresses(pr_base_df, 300)
    top_pr_alt = topk_addresses(pr_alt_df, 300)
    top_taint_base = topk_addresses(taint_base_df, 300)
    top_taint_alt = topk_addresses(taint_alt_df, 300)

    def to_rank_map(lst):
        return {rec['address'].lower(): i for i, rec in enumerate(lst)}

    r_pr_b = to_rank_map(top_pr_base)
    r_pr_a = to_rank_map(top_pr_alt)
    r_tai_b = to_rank_map(top_taint_base)
    r_tai_a = to_rank_map(top_taint_alt)

    all_addrs = set(list(r_pr_b.keys()) + list(r_pr_a.keys()) + list(r_tai_b.keys()) + list(r_tai_a.keys()))

    stability_rows = []
    for addr in all_addrs:
        ranks = []
        for r in [r_pr_b, r_pr_a, r_tai_b, r_tai_a]:
            if addr in r:
                ranks.append(r[addr])
        presence = len(ranks)
        avg_rank = float(np.mean(ranks)) if ranks else None
        best_rank = float(np.min(ranks)) if ranks else None
        stability_rows.append({
            'address': addr,
            'presence': presence,
            'avg_rank': avg_rank,
            'best_rank': best_rank
        })
    stab_df = pd.DataFrame(stability_rows)
    if not stab_df.empty:
        stab_df['stability'] = stab_df['presence']*1.0 + stab_df['best_rank'].apply(lambda x: 0 if x is None else max(0, 200 - x)/200.0)

    if top_taint_base:
        df_final = pd.DataFrame(top_taint_base)
        df_final['addr_lower'] = df_final['address'].str.lower()
        df_stab = stab_df.rename(columns={'address': 'addr_lower'})
        df_merged = pd.merge(df_final, df_stab[['addr_lower','stability','presence']], on='addr_lower', how='left')
        df_merged['stability'] = df_merged['stability'].fillna(0)
        df_merged['presence'] = df_merged['presence'].fillna(0)
        df_merged['composite'] = df_merged['norm'] + 0.2*df_merged['stability'] + 0.1*df_merged['presence']
        df_merged = df_merged.sort_values(['composite','norm','score'], ascending=[False, False, False])
        final_addresses = df_merged['address'].tolist()
    else:
        final_addresses = [rec['address'] for rec in top_pr_base]

    final_addresses = final_addresses[:100]

    uncertain = []
    if not stab_df.empty:
        df_unc = stab_df.copy()
        df_unc = df_unc[df_unc['presence'] <= 1]
        df_unc = df_unc.sort_values(['presence','best_rank'], ascending=[True, True]).head(20)
        uncertain = [a for a in df_unc['address'].tolist()]

    meta = {
        'db': NEO4J_DATABASE,
        'rel_type': rel_type,
        'time_prop': time_prop,
        'value_prop': value_prop,
        'time_kind': time_kind,
        'value_scale_to_eth': value_scale,
        'baseline_params': baseline_params,
        'alt_params': alt_params,
        'counts': {
            'nodes_base': len(nodes_base), 'edges_base': len(edges_base),
            'nodes_alt': len(nodes_alt), 'edges_alt': len(edges_alt)
        },
    }

    payload = {
        'ok': True,
        'meta': meta,
        'pr_base_top': top_pr_base,
        'pr_alt_top': top_pr_alt,
        'taint_base_top': top_taint_base,
        'taint_alt_top': top_taint_alt,
        'final_addresses': final_addresses,
        'uncertain_addresses': uncertain
    }
    print(json.dumps(payload))
except Exception as e:
    print(json.dumps({"ok": False, "error": str(e)}))

import os
from graphdatascience import GraphDataScience
import pandas as pd
import numpy as np
import json
import random
import string
from datetime import datetime, timezone

NEO4J_URI = os.getenv('NEO4J_URI')
NEO4J_USERNAME = os.getenv('NEO4J_USERNAME')
NEO4J_PASSWORD = os.getenv('NEO4J_PASSWORD')
NEO4J_DATABASE = os.getenv('NEO4J_DATABASE') or 'neo4j'

try:
    if not (NEO4J_URI and NEO4J_USERNAME and NEO4J_PASSWORD):
        raise RuntimeError("Missing Neo4j environment variables NEO4J_URI/USERNAME/PASSWORD")

    gds = GraphDataScience(NEO4J_URI, auth=(NEO4J_USERNAME, NEO4J_PASSWORD), database=NEO4J_DATABASE)

    def run_cypher(query, params=None):
        return gds.run_cypher(query, params or {})

    stolen_addr = '0x1db92e2eebc8e0c075a02bea49a2935bcd2dfcf4'

    # 1) Find node for address
    q_find = """
    MATCH (n)
    WHERE (n.address IS NOT NULL AND toLower(n.address) = toLower($addr))
       OR (n.id IS NOT NULL AND toLower(n.id) = toLower($addr))
       OR (n.hash IS NOT NULL AND toLower(n.hash) = toLower($addr))
       OR (n.addr IS NOT NULL AND toLower(n.addr) = toLower($addr))
    RETURN id(n) AS nid, n
    LIMIT 1
    """
    df_find = run_cypher(q_find, {"addr": stolen_addr})
    if df_find.empty:
        raise RuntimeError("Could not find node for stolen address in DB")
    nid = int(df_find.loc[0, 'nid'])
    node_props = df_find.loc[0, 'n']

    # choose node address property
    node_addr_prop_candidates = ['address', 'id', 'hash', 'addr']
    node_addr_prop = None
    for k in node_addr_prop_candidates:
        if k in node_props and isinstance(node_props[k], str) and node_props[k].lower() == stolen_addr.lower():
            node_addr_prop = k
            break
    if node_addr_prop is None:
        for k, v in node_props.items():
            if isinstance(v, str) and v.lower() == stolen_addr.lower():
                node_addr_prop = k
                break
    if node_addr_prop is None:
        node_addr_prop = 'address'

    # 2) Determine relationship type 
    q_reltypes = """
    MATCH (n)-[r]->() WHERE id(n)=$nid
    RETURN type(r) AS type, count(*) AS c ORDER BY c DESC LIMIT 5
    """
    df_types_out = run_cypher(q_reltypes, {"nid": nid})
    if df_types_out.empty:
        raise RuntimeError("No outgoing relationships from stolen address node; cannot analyze transfers")

    type_order_pref = ['TRANSFER', 'TRANSFERS', 'SENT_TO', 'SEND', 'TRANSFERRED_TO', 'TX', 'TRANSACTION', 'SENT', 'TO']
    rel_type = None
    types_list = df_types_out['type'].tolist()
    for pref in type_order_pref:
        for t in types_list:
            if t.upper() == pref:
                rel_type = t
                break
        if rel_type:
            break
    if rel_type is None:
        rel_type = df_types_out.loc[0, 'type']

    # 3) Sample some relationships to identify property keys for value and timestamp
    q_sample = f"MATCH (n)-[r:`{rel_type}`]->() WHERE id(n)=$nid RETURN r LIMIT 200"
    df_sample = run_cypher(q_sample, {"nid": nid})
    rel_prop_keys = set()
    rel_rows = []
    for _, row in df_sample.iterrows():
        rprops = row['r']
        rel_rows.append(rprops)
        rel_prop_keys.update(rprops.keys())

    TIME_KEYS = ['timestamp', 'block_timestamp', 'blockTimestamp', 'time', 'ts', 'block_time', 'datetime']
    VALUE_KEYS = ['value', 'amount', 'value_eth', 'valueEth', 'eth', 'value_wei', 'valueWei', 'wei', 'amount_wei', 'amountWei']

    time_prop = None
    for k in TIME_KEYS:
        if k in rel_prop_keys:
            time_prop = k
            break
    if time_prop is None and rel_rows:
        for k in rel_prop_keys:
            vals = [rp.get(k) for rp in rel_rows if k in rp]
            if not vals:
                continue
            nums = [v for v in vals if isinstance(v, (int, float))]
            if len(nums) >= max(3, len(vals)//3):
                vmed = float(np.median(nums))
                if vmed > 1e8:
                    time_prop = k
                    break

    value_prop = None
    for k in VALUE_KEYS:
        if k in rel_prop_keys:
            value_prop = k
            break

    # 4) Determine time window by sampling property values
    start_ts_num = None  # seconds since epoch
    end_ts_num = None
    time_kind = None  # 'numeric' | 'string_iso' | 'temporal'

    if time_prop is not None:
        q_times = f"MATCH (n)-[r:`{rel_type}`]->() WHERE id(n)=$nid AND r.`{time_prop}` IS NOT NULL RETURN r.`{time_prop}` AS ts LIMIT 2000"
        df_times = run_cypher(q_times, {"nid": nid})
        ts_vals = df_times['ts'].dropna().tolist()
        if ts_vals:
            sample = ts_vals[0]
            if isinstance(sample, (int, float)):
                arr = [float(x) for x in ts_vals if isinstance(x, (int, float))]
                vmed = float(np.median(arr))
                if vmed > 1e14:
                    scale = 1e-9
                elif vmed > 1e12:
                    scale = 1e-6
                elif vmed > 1e11:
                    scale = 1e-3
                else:
                    scale = 1.0
                start_raw = min(arr)
                start_ts_num = start_raw * scale
                end_ts_num = start_ts_num + 14*24*3600
                time_kind = 'numeric'
            elif isinstance(sample, str):
                pds = pd.to_datetime(pd.Series(ts_vals), utc=True, errors='coerce')
                pds = pds.dropna()
                if not pds.empty:
                    start_dt = pds.min().to_pydatetime().astimezone(timezone.utc)
                    start_ts_num = start_dt.timestamp()
                    end_ts_num = start_ts_num + 14*24*3600
                    time_kind = 'string_iso'
            else:
                try:
                    from neo4j.time import DateTime as NeoDateTime
                    if isinstance(sample, NeoDateTime):
                        pyts = []
                        for v in ts_vals:
                            try:
                                py = v.to_native()
                            except Exception:
                                py = datetime(v.year, v.month, v.day, v.hour, v.minute, int(v.second), tzinfo=timezone.utc)
                            pyts.append(py)
                        start_dt = min(pyts)
                        start_ts_num = start_dt.replace(tzinfo=timezone.utc).timestamp()
                        end_ts_num = start_ts_num + 14*24*3600
                        time_kind = 'temporal'
                except Exception:
                    pass
        if time_kind is None:
            time_prop = None

    # 5) Determine value scale and thresholds
    value_scale = 1.0
    baseline_min_val_eth = 0.0
    alt_min_val_eth = 0.0
    if value_prop is not None:
        q_vals = f"MATCH (n)-[r:`{rel_type}`]->() WHERE id(n)=$nid AND r.`{value_prop}` IS NOT NULL RETURN r.`{value_prop}` AS v LIMIT 5000"
        df_vals = run_cypher(q_vals, {"nid": nid})
        raw_vals = df_vals['v'].dropna().tolist()
        vs = []
        for v in raw_vals:
            if isinstance(v, (int, float)):
                vs.append(float(v))
            elif isinstance(v, str):
                try:
                    vs.append(float(v))
                except Exception:
                    continue
        if len(vs) == 0:
            value_prop = None
        else:
            vmed = float(np.median(vs))
            vmax = float(max(vs)) if vs else 0.0
            if vmed > 1e12 or vmax > 1e15:
                value_scale = 1e-18
            else:
                value_scale = 1.0
            vs_eth = [v*value_scale for v in vs]
            if len(vs_eth) >= 5:
                p90 = float(np.percentile(vs_eth, 90))
                p50 = float(np.percentile(vs_eth, 50))
                baseline_min_val_eth = 0.0
                alt_min_val_eth = max(0.01, 0.25*p50, 0.1*p90)
            else:
                baseline_min_val_eth = 0.0
                alt_min_val_eth = 0.0

    # 6) BFS
    def expand_k_hops(max_hops=4, min_val_eth=0.0, time_kind=time_kind, start_ts_num=start_ts_num, end_ts_num=end_ts_num, max_nodes=50000):
        nodes = set([nid])
        frontier = set([nid])
        edges = set()
        min_val_raw = (min_val_eth / value_scale) if (value_prop is not None) else None
        time_where = ""
        params_base = {}
        if time_prop is not None and time_kind is not None and start_ts_num is not None and end_ts_num is not None:
            if time_kind == 'numeric':
                time_where = f" AND toFloat(r.`{time_prop}`) >= $start AND toFloat(r.`{time_prop}`) <= $end"
                params_base.update({"start": float(start_ts_num), "end": float(end_ts_num)})
            else:
                start_iso = datetime.fromtimestamp(start_ts_num, tz=timezone.utc).isoformat()
                end_iso = datetime.fromtimestamp(end_ts_num, tz=timezone.utc).isoformat()
                time_where = f" AND datetime(r.`{time_prop}`) >= datetime($startIso) AND datetime(r.`{time_prop}`) <= datetime($endIso)"
                params_base.update({"startIso": start_iso, "endIso": end_iso})
        for hop in range(max_hops):
            if not frontier or len(nodes) >= max_nodes:
                break
            q = f"MATCH (s)-[r:`{rel_type}`]->(t) WHERE id(s) IN $frontier"
            params = {"frontier": list(frontier)}
            q += time_where
            params.update(params_base)
            if value_prop is not None and min_val_raw is not None and min_val_raw > 0:
                q += f" AND toFloat(r.`{value_prop}`) >= $minVal"
                params.update({"minVal": float(min_val_raw)})
            q += f" RETURN DISTINCT id(s) AS s, id(t) AS t LIMIT 20000"
            df_step = run_cypher(q, params)
            new_frontier = set()
            for _, row in df_step.iterrows():
                s = int(row['s']); t = int(row['t'])
                edges.add((s,t))
                if t not in nodes:
                    new_frontier.add(t)
                    nodes.add(t)
                    if len(nodes) >= max_nodes:
                        break
            frontier = new_frontier
        return nodes, edges

    baseline_params = {
        'max_hops': 4,
        'min_val_eth': baseline_min_val_eth,
        'time_kind': time_kind,
        'start_ts_num': start_ts_num,
        'end_ts_num': end_ts_num,
        'max_nodes': 30000
    }
    alt_params = {
        'max_hops': 3,
        'min_val_eth': alt_min_val_eth,
        'time_kind': time_kind,
        'start_ts_num': start_ts_num,
        'end_ts_num': start_ts_num + 7*24*3600 if start_ts_num is not None else None,
        'max_nodes': 20000
    }

    nodes_base, edges_base = expand_k_hops(**baseline_params)
    nodes_alt, edges_alt = expand_k_hops(**alt_params)

    def project_gds_graph(nodes_set, min_val_eth=0.0, time_kind=time_kind, start_ts_num=start_ts_num, end_ts_num=end_ts_num):
        nodeIds = list(nodes_set)
        gname = 'g_' + ''.join(random.choices(string.ascii_lowercase+string.digits, k=8))
        nodeQuery = "MATCH (n) WHERE id(n) IN $nodeIds RETURN id(n) AS id"
        relQuery = f"MATCH (s)-[r:`{rel_type}`]->(t) WHERE id(s) IN $nodeIds AND id(t) IN $nodeIds"
        params = {"nodeIds": nodeIds}
        if time_prop is not None and time_kind is not None and start_ts_num is not None and end_ts_num is not None:
            if time_kind == 'numeric':
                relQuery += f" AND toFloat(r.`{time_prop}`) >= $start AND toFloat(r.`{time_prop}`) <= $end"
                params.update({"start": float(start_ts_num), "end": float(end_ts_num)})
            else:
                start_iso = datetime.fromtimestamp(start_ts_num, tz=timezone.utc).isoformat()
                end_iso = datetime.fromtimestamp(end_ts_num, tz=timezone.utc).isoformat()
                relQuery += f" AND datetime(r.`{time_prop}`) >= datetime($startIso) AND datetime(r.`{time_prop}`) <= datetime($endIso)"
                params.update({"startIso": start_iso, "endIso": end_iso})
        if value_prop is not None and min_val_eth is not None and min_val_eth > 0:
            min_raw = min_val_eth / value_scale
            relQuery += f" AND toFloat(r.`{value_prop}`) >= $minVal"
            params.update({"minVal": float(min_raw)})
        # limit relationships in projection for safety
        relQuery += " WITH s, t, r LIMIT 200000"
        if value_prop is not None:
            relQuery += f" RETURN id(s) AS source, id(t) AS target, toFloat(r.`{value_prop}`) * $vscale AS weight"
            params.update({"vscale": float(value_scale)})
        else:
            relQuery += f" RETURN id(s) AS source, id(t) AS target"
        q_project = """
        CALL gds.graph.project.cypher($gname, $nodeQuery, $relQuery, {parameters: $params})
        YIELD graphName, nodeCount, relationshipCount
        RETURN graphName, nodeCount, relationshipCount
        """
        df_proj = run_cypher(q_project, {"gname": gname, "nodeQuery": nodeQuery, "relQuery": relQuery, "params": params})
        if df_proj.empty:
            raise RuntimeError("Failed to project graph")
        return gname, int(df_proj.loc[0,'nodeCount']), int(df_proj.loc[0,'relationshipCount'])

    def drop_graph(gname):
        try:
            run_cypher("CALL gds.graph.drop($gname)", {"gname": gname})
        except Exception:
            pass

    def run_degree(gname):
        # Outgoing degree (fund distribution) and incoming degree (collection points)
        q = """
        CALL gds.degree.stream($gname, {orientation: 'NATURAL'})
        YIELD nodeId, score
        WITH gds.util.asNode(nodeId) AS n, score
        WHERE toLower(n[$addrProp]) <> toLower($stolen)
        RETURN id(n) AS nodeId, score, n[$addrProp] AS address
        ORDER BY score DESC
        """
        return run_cypher(q, {"gname": gname, "addrProp": node_addr_prop, "stolen": stolen_addr})

    def fetch_edges(nodes_set, min_val_eth=0.0, time_kind=time_kind, start_ts_num=start_ts_num, end_ts_num=end_ts_num):
        nodeIds = list(nodes_set)
        if not nodeIds:
            return pd.DataFrame(columns=['s','t','w'])
        q = f"MATCH (s)-[r:`{rel_type}`]->(t) WHERE id(s) IN $nodeIds AND id(t) IN $nodeIds"
        params = {"nodeIds": nodeIds}
        if time_prop is not None and time_kind is not None and start_ts_num is not None and end_ts_num is not None:
            if time_kind == 'numeric':
                q += f" AND toFloat(r.`{time_prop}`) >= $start AND toFloat(r.`{time_prop}`) <= $end"
                params.update({"start": float(start_ts_num), "end": float(end_ts_num)})
            else:
                start_iso = datetime.fromtimestamp(start_ts_num, tz=timezone.utc).isoformat()
                end_iso = datetime.fromtimestamp(end_ts_num, tz=timezone.utc).isoformat()
                q += f" AND datetime(r.`{time_prop}`) >= datetime($startIso) AND datetime(r.`{time_prop}`) <= datetime($endIso)"
                params.update({"startIso": start_iso, "endIso": end_iso})
        if value_prop is not None and min_val_eth is not None and min_val_eth > 0:
            min_raw = min_val_eth / value_scale
            q += f" AND toFloat(r.`{value_prop}`) >= $minVal"
            params.update({"minVal": float(min_raw)})
        if value_prop is not None:
            q += f" RETURN id(s) AS s, id(t) AS t, toFloat(r.`{value_prop}`) * $vscale AS w"
            params.update({"vscale": float(value_scale)})
        else:
            q += f" RETURN id(s) AS s, id(t) AS t, 1.0 AS w"
        df = run_cypher(q, params)
        return df

    # Project graphs and run degree
    gname_base, nodeCountB, relCountB = project_gds_graph(nodes_base, min_val_eth=baseline_params['min_val_eth'], time_kind=baseline_params['time_kind'], start_ts_num=baseline_params['start_ts_num'], end_ts_num=baseline_params['end_ts_num'])
    gname_alt, nodeCountA, relCountA = project_gds_graph(nodes_alt, min_val_eth=alt_params['min_val_eth'], time_kind=alt_params['time_kind'], start_ts_num=alt_params['start_ts_num'], end_ts_num=alt_params['end_ts_num'])

    deg_base_df = run_degree(gname_base)
    deg_alt_df = run_degree(gname_alt)

    drop_graph(gname_base)
    drop_graph(gname_alt)

    # Method 2: taint propagation
    def taint_propagation(nodes_set, min_val_eth=0.0, time_kind=time_kind, start_ts_num=start_ts_num, end_ts_num=end_ts_num, K=4):
        df_edges = fetch_edges(nodes_set, min_val_eth=min_val_eth, time_kind=time_kind, start_ts_num=start_ts_num, end_ts_num=end_ts_num)
        out_map = {}
        for _, row in df_edges.iterrows():
            s = int(row['s']); t = int(row['t']); w = float(row['w'])
            out_map.setdefault(s, []).append((t, w))
        denom = {s: sum(w for (_, w) in lst) for s, lst in out_map.items()}
        node_list = list(set(list(df_edges['s'].astype(int)) + list(df_edges['t'].astype(int)) + [nid]))
        id2idx = {n:i for i,n in enumerate(node_list)}
        idx2id = {i:n for n,i in id2idx.items()}
        nN = len(node_list)
        tvec = np.zeros(nN, dtype=float)
        if nid in id2idx:
            tvec[id2idx[nid]] = 1.0
        else:
            return pd.DataFrame(columns=['nodeId', 'score', 'address'])
        cum = np.zeros(nN, dtype=float)
        cur = tvec.copy()
        for step in range(K):
            nxt = np.zeros(nN, dtype=float)
            for s, lst in out_map.items():
                si = id2idx.get(s)
                if si is None:
                    continue
                if denom.get(s, 0.0) <= 0 or cur[si] == 0:
                    continue
                frac = cur[si] / denom[s]
                for (t, w) in lst:
                    ti = id2idx.get(t)
                    if ti is None:
                        continue
                    nxt[ti] += frac * w
            cum += nxt
            cur = nxt
        rows = []
        for i in range(nN):
            node_id = int(idx2id[i])
            score = float(cum[i])
            rows.append((node_id, score))
        df = pd.DataFrame(rows, columns=['nodeId', 'score'])
        neo_ids = df['nodeId'].astype(int).tolist()
        if neo_ids:
            q_map = f"MATCH (n) WHERE id(n) IN $ids RETURN id(n) AS id, n.`{node_addr_prop}` AS addr"
            df_map = run_cypher(q_map, {"ids": neo_ids})
            id2addr = {int(r['id']): r['addr'] for _, r in df_map.iterrows()}
            df['address'] = df['nodeId'].map(id2addr)
            df = df[(df['address'].notna()) & (df['address'].str.lower() != stolen_addr.lower())]
            df = df.sort_values('score', ascending=False)
        else:
            df = pd.DataFrame(columns=['nodeId','score','address'])
        return df

    taint_base_df = taint_propagation(nodes_base, min_val_eth=baseline_params['min_val_eth'], time_kind=baseline_params['time_kind'], start_ts_num=baseline_params['start_ts_num'], end_ts_num=baseline_params['end_ts_num'], K=4)
    taint_alt_df = taint_propagation(nodes_alt, min_val_eth=alt_params['min_val_eth'], time_kind=alt_params['time_kind'], start_ts_num=alt_params['start_ts_num'], end_ts_num=alt_params['end_ts_num'], K=3)

    def topk_addresses(df, k=200):
        if df is None or df.empty:
            return []
        dfn = df.copy()
        maxs = dfn['score'].max()
        if pd.isna(maxs) or maxs == 0:
            dfn['norm'] = 0.0
        else:
            dfn['norm'] = dfn['score'] / maxs
        dfn = dfn[['address', 'score', 'norm']]
        dfn = dfn.dropna(subset=['address'])
        dfn = dfn.groupby('address', as_index=False).agg({'score':'max','norm':'max'})
        dfn = dfn.sort_values(['norm','score'], ascending=[False, False])
        return dfn.head(k).to_dict(orient='records')

    top_deg_base = topk_addresses(deg_base_df, 300)
    top_deg_alt = topk_addresses(deg_alt_df, 300)
    top_taint_base = topk_addresses(taint_base_df, 300)
    top_taint_alt = topk_addresses(taint_alt_df, 300)

    def to_rank_map(lst):
        return {rec['address'].lower(): i for i, rec in enumerate(lst)}

    r_deg_b = to_rank_map(top_deg_base)
    r_deg_a = to_rank_map(top_deg_alt)
    r_tai_b = to_rank_map(top_taint_base)
    r_tai_a = to_rank_map(top_taint_alt)

    all_addrs = set(list(r_deg_b.keys()) + list(r_deg_a.keys()) + list(r_tai_b.keys()) + list(r_tai_a.keys()))

    stability_rows = []
    for addr in all_addrs:
        ranks = []
        for r in [r_deg_b, r_deg_a, r_tai_b, r_tai_a]:
            if addr in r:
                ranks.append(r[addr])
        presence = len(ranks)
        avg_rank = float(np.mean(ranks)) if ranks else None
        best_rank = float(np.min(ranks)) if ranks else None
        stability_rows.append({
            'address': addr,
            'presence': presence,
            'avg_rank': avg_rank,
            'best_rank': best_rank
        })
    stab_df = pd.DataFrame(stability_rows)
    if not stab_df.empty:
        stab_df['stability'] = stab_df['presence']*1.0 + stab_df['best_rank'].apply(lambda x: 0 if x is None else max(0, 200 - x)/200.0)

    if top_taint_base:
        df_final = pd.DataFrame(top_taint_base)
        df_final['addr_lower'] = df_final['address'].str.lower()
        df_stab = stab_df.rename(columns={'address': 'addr_lower'})
        df_merged = pd.merge(df_final, df_stab[['addr_lower','stability','presence']], on='addr_lower', how='left')
        df_merged['stability'] = df_merged['stability'].fillna(0)
        df_merged['presence'] = df_merged['presence'].fillna(0)
        df_merged['composite'] = df_merged['norm'] + 0.2*df_merged['stability'] + 0.1*df_merged['presence']
        df_merged = df_merged.sort_values(['composite','norm','score'], ascending=[False, False, False])
        final_addresses = df_merged['address'].tolist()
    else:
        final_addresses = [rec['address'] for rec in top_deg_base]

    final_addresses = final_addresses[:100]

    uncertain = []
    if not stab_df.empty:
        df_unc = stab_df.copy()
        df_unc = df_unc[df_unc['presence'] <= 1]
        df_unc = df_unc.sort_values(['presence','best_rank'], ascending=[True, True]).head(20)
        uncertain = [a for a in df_unc['address'].tolist()]

    meta = {
        'db': NEO4J_DATABASE,
        'rel_type': rel_type,
        'time_prop': time_prop,
        'value_prop': value_prop,
        'time_kind': time_kind,
        'value_scale_to_eth': value_scale,
        'baseline_params': baseline_params,
        'alt_params': alt_params,
        'counts': {
            'nodes_base': len(nodes_base), 'edges_base': len(edges_base),
            'nodes_alt': len(nodes_alt), 'edges_alt': len(edges_alt)
        },
    }

    payload = {
        'ok': True,
        'meta': meta,
        'deg_base_top': top_deg_base,
        'deg_alt_top': top_deg_alt,
        'taint_base_top': top_taint_base,
        'taint_alt_top': top_taint_alt,
        'final_addresses': final_addresses,
        'uncertain_addresses': uncertain
    }
    print(json.dumps(payload))
except Exception as e:
    print(json.dumps({"ok": False, "error": str(e)}))

import os
from graphdatascience import GraphDataScience
import pandas as pd
import numpy as np
import json
from datetime import datetime, timezone

NEO4J_URI = os.getenv('NEO4J_URI')
NEO4J_USERNAME = os.getenv('NEO4J_USERNAME')
NEO4J_PASSWORD = os.getenv('NEO4J_PASSWORD')
NEO4J_DATABASE = os.getenv('NEO4J_DATABASE') or 'neo4j'

try:
    if not (NEO4J_URI and NEO4J_USERNAME and NEO4J_PASSWORD):
        raise RuntimeError("Missing Neo4j environment variables NEO4J_URI/USERNAME/PASSWORD")

    gds = GraphDataScience(NEO4J_URI, auth=(NEO4J_USERNAME, NEO4J_PASSWORD), database=NEO4J_DATABASE)

    def run_cypher(query, params=None):
        return gds.run_cypher(query, params or {})

    stolen_addr = '0x1db92e2eebc8e0c075a02bea49a2935bcd2dfcf4'

    # 1) Find node for address
    q_find = """
    MATCH (n)
    WHERE (n.address IS NOT NULL AND toLower(n.address) = toLower($addr))
       OR (n.id IS NOT NULL AND toLower(n.id) = toLower($addr))
       OR (n.hash IS NOT NULL AND toLower(n.hash) = toLower($addr))
       OR (n.addr IS NOT NULL AND toLower(n.addr) = toLower($addr))
    RETURN id(n) AS nid, n
    LIMIT 1
    """
    df_find = run_cypher(q_find, {"addr": stolen_addr})
    if df_find.empty:
        raise RuntimeError("Could not find node for stolen address in DB")
    nid = int(df_find.loc[0, 'nid'])
    node_props = df_find.loc[0, 'n']

    # choose node address property
    node_addr_prop_candidates = ['address', 'id', 'hash', 'addr']
    node_addr_prop = None
    for k in node_addr_prop_candidates:
        if k in node_props and isinstance(node_props[k], str) and node_props[k].lower() == stolen_addr.lower():
            node_addr_prop = k
            break
    if node_addr_prop is None:
        for k, v in node_props.items():
            if isinstance(v, str) and v.lower() == stolen_addr.lower():
                node_addr_prop = k
                break
    if node_addr_prop is None:
        node_addr_prop = 'address'

    # 2) Determine relationship type 
    q_reltypes = """
    MATCH (n)-[r]->() WHERE id(n)=$nid
    RETURN type(r) AS type, count(*) AS c ORDER BY c DESC LIMIT 5
    """
    df_types_out = run_cypher(q_reltypes, {"nid": nid})
    if df_types_out.empty:
        raise RuntimeError("No outgoing relationships from stolen address node; cannot analyze transfers")

    type_order_pref = ['TRANSFER', 'TRANSFERS', 'SENT_TO', 'SEND', 'TRANSFERRED_TO', 'TX', 'TRANSACTION', 'SENT', 'TO']
    rel_type = None
    types_list = df_types_out['type'].tolist()
    for pref in type_order_pref:
        for t in types_list:
            if t.upper() == pref:
                rel_type = t
                break
        if rel_type:
            break
    if rel_type is None:
        rel_type = df_types_out.loc[0, 'type']

    # 3) Sample some relationships to identify property keys for value and timestamp
    q_sample = f"MATCH (n)-[r:`{rel_type}`]->() WHERE id(n)=$nid RETURN r LIMIT 200"
    df_sample = run_cypher(q_sample, {"nid": nid})
    rel_prop_keys = set()
    rel_rows = []
    for _, row in df_sample.iterrows():
        rprops = row['r']
        rel_rows.append(rprops)
        rel_prop_keys.update(rprops.keys())

    TIME_KEYS = ['timestamp', 'block_timestamp', 'blockTimestamp', 'time', 'ts', 'block_time', 'datetime']
    VALUE_KEYS = ['value', 'amount', 'value_eth', 'valueEth', 'eth', 'value_wei', 'valueWei', 'wei', 'amount_wei', 'amountWei']

    time_prop = None
    for k in TIME_KEYS:
        if k in rel_prop_keys:
            time_prop = k
            break
    if time_prop is None and rel_rows:
        for k in rel_prop_keys:
            vals = [rp.get(k) for rp in rel_rows if k in rp]
            if not vals:
                continue
            nums = [v for v in vals if isinstance(v, (int, float))]
            if len(nums) >= max(3, len(vals)//3):
                vmed = float(np.median(nums))
                if vmed > 1e8:
                    time_prop = k
                    break

    value_prop = None
    for k in VALUE_KEYS:
        if k in rel_prop_keys:
            value_prop = k
            break

    # 4) Determine time window by sampling property values
    start_ts_num = None  # seconds since epoch
    end_ts_num = None
    time_kind = None  # 'numeric' | 'string_iso' | 'temporal'

    if time_prop is not None:
        q_times = f"MATCH (n)-[r:`{rel_type}`]->() WHERE id(n)=$nid AND r.`{time_prop}` IS NOT NULL RETURN r.`{time_prop}` AS ts LIMIT 2000"
        df_times = run_cypher(q_times, {"nid": nid})
        ts_vals = df_times['ts'].dropna().tolist()
        if ts_vals:
            sample = ts_vals[0]
            if isinstance(sample, (int, float)):
                arr = [float(x) for x in ts_vals if isinstance(x, (int, float))]
                vmed = float(np.median(arr))
                if vmed > 1e14:
                    scale = 1e-9
                elif vmed > 1e12:
                    scale = 1e-6
                elif vmed > 1e11:
                    scale = 1e-3
                else:
                    scale = 1.0
                start_raw = min(arr)
                start_ts_num = start_raw * scale
                end_ts_num = start_ts_num + 14*24*3600
                time_kind = 'numeric'
            elif isinstance(sample, str):
                pds = pd.to_datetime(pd.Series(ts_vals), utc=True, errors='coerce')
                pds = pds.dropna()
                if not pds.empty:
                    start_dt = pds.min().to_pydatetime().astimezone(timezone.utc)
                    start_ts_num = start_dt.timestamp()
                    end_ts_num = start_ts_num + 14*24*3600
                    time_kind = 'string_iso'
            else:
                try:
                    from neo4j.time import DateTime as NeoDateTime
                    if isinstance(sample, NeoDateTime):
                        pyts = []
                        for v in ts_vals:
                            try:
                                py = v.to_native()
                            except Exception:
                                py = datetime(v.year, v.month, v.day, v.hour, v.minute, int(v.second), tzinfo=timezone.utc)
                            pyts.append(py)
                        start_dt = min(pyts)
                        start_ts_num = start_dt.replace(tzinfo=timezone.utc).timestamp()
                        end_ts_num = start_ts_num + 14*24*3600
                        time_kind = 'temporal'
                except Exception:
                    pass
        if time_kind is None:
            time_prop = None

    # 5) Determine value scale and thresholds
    value_scale = 1.0
    baseline_min_val_eth = 0.0
    alt_min_val_eth = 0.0
    if value_prop is not None:
        q_vals = f"MATCH (n)-[r:`{rel_type}`]->() WHERE id(n)=$nid AND r.`{value_prop}` IS NOT NULL RETURN r.`{value_prop}` AS v LIMIT 5000"
        df_vals = run_cypher(q_vals, {"nid": nid})
        raw_vals = df_vals['v'].dropna().tolist()
        vs = []
        for v in raw_vals:
            if isinstance(v, (int, float)):
                vs.append(float(v))
            elif isinstance(v, str):
                try:
                    vs.append(float(v))
                except Exception:
                    continue
        if len(vs) == 0:
            value_prop = None
        else:
            vmed = float(np.median(vs))
            vmax = float(max(vs)) if vs else 0.0
            if vmed > 1e12 or vmax > 1e15:
                value_scale = 1e-18
            else:
                value_scale = 1.0
            vs_eth = [v*value_scale for v in vs]
            if len(vs_eth) >= 5:
                p90 = float(np.percentile(vs_eth, 90))
                p50 = float(np.percentile(vs_eth, 50))
                baseline_min_val_eth = 0.0
                alt_min_val_eth = max(0.01, 0.25*p50, 0.1*p90)
            else:
                baseline_min_val_eth = 0.0
                alt_min_val_eth = 0.0

    # 6) BFS and edge fetch
    def expand_k_hops(max_hops=4, min_val_eth=0.0, time_kind=time_kind, start_ts_num=start_ts_num, end_ts_num=end_ts_num, max_nodes=50000):
        nodes = set([nid])
        frontier = set([nid])
        edges = set()
        min_val_raw = (min_val_eth / value_scale) if (value_prop is not None) else None
        time_where = ""
        params_base = {}
        if time_prop is not None and time_kind is not None and start_ts_num is not None and end_ts_num is not None:
            if time_kind == 'numeric':
                time_where = f" AND toFloat(r.`{time_prop}`) >= $start AND toFloat(r.`{time_prop}`) <= $end"
                params_base.update({"start": float(start_ts_num), "end": float(end_ts_num)})
            else:
                start_iso = datetime.fromtimestamp(start_ts_num, tz=timezone.utc).isoformat()
                end_iso = datetime.fromtimestamp(end_ts_num, tz=timezone.utc).isoformat()
                time_where = f" AND datetime(r.`{time_prop}`) >= datetime($startIso) AND datetime(r.`{time_prop}`) <= datetime($endIso)"
                params_base.update({"startIso": start_iso, "endIso": end_iso})
        for hop in range(max_hops):
            if not frontier or len(nodes) >= max_nodes:
                break
            q = f"MATCH (s)-[r:`{rel_type}`]->(t) WHERE id(s) IN $frontier"
            params = {"frontier": list(frontier)}
            q += time_where
            params.update(params_base)
            if value_prop is not None and min_val_raw is not None and min_val_raw > 0:
                q += f" AND toFloat(r.`{value_prop}`) >= $minVal"
                params.update({"minVal": float(min_val_raw)})
            q += f" RETURN DISTINCT id(s) AS s, id(t) AS t LIMIT 20000"
            df_step = run_cypher(q, params)
            new_frontier = set()
            for _, row in df_step.iterrows():
                s = int(row['s']); t = int(row['t'])
                edges.add((s,t))
                if t not in nodes:
                    new_frontier.add(t)
                    nodes.add(t)
                    if len(nodes) >= max_nodes:
                        break
            frontier = new_frontier
        return nodes, edges

    def fetch_edges(nodes_set, min_val_eth=0.0, time_kind=time_kind, start_ts_num=start_ts_num, end_ts_num=end_ts_num):
        nodeIds = list(nodes_set)
        if not nodeIds:
            return pd.DataFrame(columns=['s','t','w'])
        q = f"MATCH (s)-[r:`{rel_type}`]->(t) WHERE id(s) IN $nodeIds AND id(t) IN $nodeIds"
        params = {"nodeIds": nodeIds}
        if time_prop is not None and time_kind is not None and start_ts_num is not None and end_ts_num is not None:
            if time_kind == 'numeric':
                q += f" AND toFloat(r.`{time_prop}`) >= $start AND toFloat(r.`{time_prop}`) <= $end"
                params.update({"start": float(start_ts_num), "end": float(end_ts_num)})
            else:
                start_iso = datetime.fromtimestamp(start_ts_num, tz=timezone.utc).isoformat()
                end_iso = datetime.fromtimestamp(end_ts_num, tz=timezone.utc).isoformat()
                q += f" AND datetime(r.`{time_prop}`) >= datetime($startIso) AND datetime(r.`{time_prop}`) <= datetime($endIso)"
                params.update({"startIso": start_iso, "endIso": end_iso})
        if value_prop is not None and min_val_eth is not None and min_val_eth > 0:
            min_raw = min_val_eth / value_scale
            q += f" AND toFloat(r.`{value_prop}`) >= $minVal"
            params.update({"minVal": float(min_raw)})
        if value_prop is not None:
            q += f" RETURN id(s) AS s, id(t) AS t, toFloat(r.`{value_prop}`) * $vscale AS w"
            params.update({"vscale": float(value_scale)})
        else:
            q += f" RETURN id(s) AS s, id(t) AS t, 1.0 AS w"
        df = run_cypher(q, params)
        return df

    baseline_params = {
        'max_hops': 4,
        'min_val_eth': baseline_min_val_eth,
        'time_kind': time_kind,
        'start_ts_num': start_ts_num,
        'end_ts_num': end_ts_num,
        'max_nodes': 30000
    }
    alt_params = {
        'max_hops': 3,
        'min_val_eth': alt_min_val_eth,
        'time_kind': time_kind,
        'start_ts_num': start_ts_num,
        'end_ts_num': start_ts_num + 7*24*3600 if start_ts_num is not None else None,
        'max_nodes': 20000
    }

    nodes_base, edges_base = expand_k_hops(**baseline_params)
    nodes_alt, edges_alt = expand_k_hops(**alt_params)

    df_edges_base = fetch_edges(nodes_base, min_val_eth=baseline_params['min_val_eth'], time_kind=baseline_params['time_kind'], start_ts_num=baseline_params['start_ts_num'], end_ts_num=baseline_params['end_ts_num'])
    df_edges_alt = fetch_edges(nodes_alt, min_val_eth=alt_params['min_val_eth'], time_kind=alt_params['time_kind'], start_ts_num=alt_params['start_ts_num'], end_ts_num=alt_params['end_ts_num'])

    # Method A: value-proportional taint propagation
    def taint_propagation_from_edges(df_edges, K=4):
        out_map = {}
        for _, row in df_edges.iterrows():
            s = int(row['s']); t = int(row['t']); w = float(row['w'])
            out_map.setdefault(s, []).append((t, w))
        denom = {s: sum(w for (_, w) in lst) for s, lst in out_map.items()}
        node_list = list(set(list(df_edges['s'].astype(int)) + list(df_edges['t'].astype(int)) + [nid]))
        id2idx = {n:i for i,n in enumerate(node_list)}
        idx2id = {i:n for n,i in id2idx.items()}
        nN = len(node_list)
        tvec = np.zeros(nN, dtype=float)
        if nid in id2idx:
            tvec[id2idx[nid]] = 1.0
        else:
            return pd.DataFrame(columns=['nodeId','score','address'])
        cum = np.zeros(nN, dtype=float)
        cur = tvec.copy()
        for step in range(K):
            nxt = np.zeros(nN, dtype=float)
            for s, lst in out_map.items():
                si = id2idx.get(s)
                if si is None:
                    continue
                if denom.get(s, 0.0) <= 0 or cur[si] == 0:
                    continue
                frac = cur[si] / denom[s]
                for (t, w) in lst:
                    ti = id2idx.get(t)
                    if ti is None:
                        continue
                    nxt[ti] += frac * w
            cum += nxt
            cur = nxt
        rows = [(int(idx2id[i]), float(cum[i])) for i in range(nN)]
        df = pd.DataFrame(rows, columns=['nodeId', 'score'])
        if not df.empty:
            q_map = f"MATCH (n) WHERE id(n) IN $ids RETURN id(n) AS id, n.`{node_addr_prop}` AS addr"
            df_map = run_cypher(q_map, {"ids": df['nodeId'].astype(int).tolist()})
            id2addr = {int(r['id']): r['addr'] for _, r in df_map.iterrows()}
            df['address'] = df['nodeId'].map(id2addr)
            df = df[(df['address'].notna()) & (df['address'].str.lower() != stolen_addr.lower())]
            df = df.sort_values('score', ascending=False)
        return df

    # Method B: Random Walk with Restart (Python implementation akin to personalized PR)
    def rwr_from_edges(df_edges, alpha=0.15, tol=1e-8, max_iter=100):
        # Build adjacency normalized by outgoing sum
        out_map = {}
        for _, row in df_edges.iterrows():
            s = int(row['s']); t = int(row['t']); w = float(row['w'])
            out_map.setdefault(s, []).append((t, w))
        denom = {s: sum(w for (_, w) in lst) for s, lst in out_map.items()}
        node_list = list(set(list(df_edges['s'].astype(int)) + list(df_edges['t'].astype(int)) + [nid]))
        id2idx = {n:i for i,n in enumerate(node_list)}
        idx2id = {i:n for n,i in id2idx.items()}
        nN = len(node_list)
        r = np.zeros(nN, dtype=float)
        if nid not in id2idx:
            return pd.DataFrame(columns=['nodeId','score','address'])
        r[id2idx[nid]] = 1.0
        p = r.copy()
        for it in range(max_iter):
            p_new = np.zeros(nN, dtype=float)
            # distribute
            for s, lst in out_map.items():
                si = id2idx.get(s)
                if si is None or denom.get(s,0)==0:
                    continue
                contrib = (1-alpha) * (p[si]/denom[s])
                if contrib == 0:
                    continue
                for t, w in lst:
                    ti = id2idx.get(t)
                    if ti is None:
                        continue
                    p_new[ti] += contrib * w
            p_new += alpha * r
            if np.linalg.norm(p_new - p, 1) < tol:
                p = p_new
                break
            p = p_new
        rows = [(int(idx2id[i]), float(p[i])) for i in range(nN)]
        df = pd.DataFrame(rows, columns=['nodeId','score'])
        if not df.empty:
            q_map = f"MATCH (n) WHERE id(n) IN $ids RETURN id(n) AS id, n.`{node_addr_prop}` AS addr"
            df_map = run_cypher(q_map, {"ids": df['nodeId'].astype(int).tolist()})
            id2addr = {int(r['id']): r['addr'] for _, r in df_map.iterrows()}
            df['address'] = df['nodeId'].map(id2addr)
            df = df[(df['address'].notna()) & (df['address'].str.lower() != stolen_addr.lower())]
            df = df.sort_values('score', ascending=False)
        return df

    # Compute variants
    taint_base_df = taint_propagation_from_edges(df_edges_base, K=4)
    taint_alt_df = taint_propagation_from_edges(df_edges_alt, K=3)

    rwr_base_df = rwr_from_edges(df_edges_base, alpha=0.2)
    rwr_alt_df = rwr_from_edges(df_edges_alt, alpha=0.2)

    def topk_addresses(df, k=200):
        if df is None or df.empty:
            return []
        dfn = df.copy()
        maxs = dfn['score'].max()
        if pd.isna(maxs) or maxs == 0:
            dfn['norm'] = 0.0
        else:
            dfn['norm'] = dfn['score'] / maxs
        dfn = dfn[['address', 'score', 'norm']]
        dfn = dfn.dropna(subset=['address'])
        dfn = dfn.groupby('address', as_index=False).agg({'score':'max','norm':'max'})
        dfn = dfn.sort_values(['norm','score'], ascending=[False, False])
        return dfn.head(k).to_dict(orient='records')

    top_taint_base = topk_addresses(taint_base_df, 300)
    top_taint_alt = topk_addresses(taint_alt_df, 300)
    top_rwr_base = topk_addresses(rwr_base_df, 300)
    top_rwr_alt = topk_addresses(rwr_alt_df, 300)

    def to_rank_map(lst):
        return {rec['address'].lower(): i for i, rec in enumerate(lst)}

    r_tai_b = to_rank_map(top_taint_base)
    r_tai_a = to_rank_map(top_taint_alt)
    r_rwr_b = to_rank_map(top_rwr_base)
    r_rwr_a = to_rank_map(top_rwr_alt)

    all_addrs = set(list(r_tai_b.keys()) + list(r_tai_a.keys()) + list(r_rwr_b.keys()) + list(r_rwr_a.keys()))

    stability_rows = []
    for addr in all_addrs:
        ranks = []
        for r in [r_tai_b, r_tai_a, r_rwr_b, r_rwr_a]:
            if addr in r:
                ranks.append(r[addr])
        presence = len(ranks)
        avg_rank = float(np.mean(ranks)) if ranks else None
        best_rank = float(np.min(ranks)) if ranks else None
        stability_rows.append({
            'address': addr,
            'presence': presence,
            'avg_rank': avg_rank,
            'best_rank': best_rank
        })
    stab_df = pd.DataFrame(stability_rows)
    if not stab_df.empty:
        stab_df['stability'] = stab_df['presence']*1.0 + stab_df['best_rank'].apply(lambda x: 0 if x is None else max(0, 200 - x)/200.0)

    # Build final list based on RWR (more robust) and Taint consensus
    base_df = pd.DataFrame(top_rwr_base)
    if not base_df.empty:
        base_df['addr_lower'] = base_df['address'].str.lower()
        df_stab = stab_df.rename(columns={'address': 'addr_lower'})
        df_merged = pd.merge(base_df, df_stab[['addr_lower','stability','presence']], on='addr_lower', how='left')
        df_merged['stability'] = df_merged['stability'].fillna(0)
        df_merged['presence'] = df_merged['presence'].fillna(0)
        # boost items that also appear in taint_base top
        in_taint = set([a['address'].lower() for a in top_taint_base])
        df_merged['consensus_boost'] = df_merged['addr_lower'].apply(lambda a: 0.1 if a in in_taint else 0.0)
        df_merged['composite'] = df_merged['norm'] + 0.2*df_merged['stability'] + 0.1*df_merged['presence'] + df_merged['consensus_boost']
        df_merged = df_merged.sort_values(['composite','norm','score'], ascending=[False, False, False])
        final_addresses = df_merged['address'].tolist()[:100]
    else:
        final_addresses = [rec['address'] for rec in top_taint_base][:100]

    # Uncertain: low presence across variants
    uncertain = []
    if not stab_df.empty:
        df_unc = stab_df.copy()
        df_unc = df_unc[df_unc['presence'] <= 1]
        df_unc = df_unc.sort_values(['presence','best_rank'], ascending=[True, True]).head(20)
        uncertain = [a for a in df_unc['address'].tolist()]

    meta = {
        'db': NEO4J_DATABASE,
        'rel_type': rel_type,
        'time_prop': time_prop,
        'value_prop': value_prop,
        'time_kind': time_kind,
        'value_scale_to_eth': value_scale,
        'baseline_params': baseline_params,
        'alt_params': alt_params,
        'counts': {
            'nodes_base': len(nodes_base), 'edges_base': len(edges_base),
            'nodes_alt': len(nodes_alt), 'edges_alt': len(edges_alt),
            'edges_base_rows': int(len(df_edges_base)), 'edges_alt_rows': int(len(df_edges_alt))
        },
    }

    payload = {
        'ok': True,
        'meta': meta,
        'taint_base_top': top_taint_base,
        'taint_alt_top': top_taint_alt,
        'rwr_base_top': top_rwr_base,
        'rwr_alt_top': top_rwr_alt,
        'final_addresses': final_addresses,
        'uncertain_addresses': uncertain
    }
    print(json.dumps(payload))
except Exception as e:
    print(json.dumps({"ok": False, "error": str(e)}))

import os
from graphdatascience import GraphDataScience
import pandas as pd
import numpy as np
import json
from datetime import datetime, timezone

NEO4J_URI = os.getenv('NEO4J_URI')
NEO4J_USERNAME = os.getenv('NEO4J_USERNAME')
NEO4J_PASSWORD = os.getenv('NEO4J_PASSWORD')
NEO4J_DATABASE = os.getenv('NEO4J_DATABASE') or 'neo4j'

try:
    if not (NEO4J_URI and NEO4J_USERNAME and NEO4J_PASSWORD):
        raise RuntimeError("Missing Neo4j environment variables NEO4J_URI/USERNAME/PASSWORD")

    gds = GraphDataScience(NEO4J_URI, auth=(NEO4J_USERNAME, NEO4J_PASSWORD), database=NEO4J_DATABASE)

    def run_cypher(query, params=None):
        return gds.run_cypher(query, params or {})

    stolen_addr = '0x1db92e2eebc8e0c075a02bea49a2935bcd2dfcf4'

    # Find node and props
    q_find = """
    MATCH (n)
    WHERE (n.address IS NOT NULL AND toLower(n.address) = toLower($addr))
       OR (n.id IS NOT NULL AND toLower(n.id) = toLower($addr))
       OR (n.hash IS NOT NULL AND toLower(n.hash) = toLower($addr))
       OR (n.addr IS NOT NULL AND toLower(n.addr) = toLower($addr))
    RETURN id(n) AS nid, n LIMIT 1
    """
    df_find = run_cypher(q_find, {"addr": stolen_addr})
    if df_find.empty:
        raise RuntimeError("Could not find node for stolen address in DB")
    nid = int(df_find.loc[0, 'nid'])
    node_props = df_find.loc[0, 'n']
    node_addr_prop = None
    for k in ['address','id','hash','addr']:
        if k in node_props and isinstance(node_props[k], str) and node_props[k].lower() == stolen_addr.lower():
            node_addr_prop = k
            break
    if node_addr_prop is None:
        for k, v in node_props.items():
            if isinstance(v, str) and v.lower() == stolen_addr.lower():
                node_addr_prop = k
                break
    if node_addr_prop is None:
        node_addr_prop = 'address'

    # Determine rel type
    df_types_out = run_cypher("MATCH (n)-[r]->() WHERE id(n)=$nid RETURN type(r) AS type, count(*) AS c ORDER BY c DESC LIMIT 5", {"nid": nid})
    if df_types_out.empty:
        raise RuntimeError("No outgoing relationships from stolen address node; cannot analyze transfers")
    rel_type = None
    for pref in ['TRANSFER','TRANSFERS','SENT_TO','SEND','TRANSFERRED_TO','TX','TRANSACTION','SENT','TO']:
        for t in df_types_out['type'].tolist():
            if t.upper() == pref:
                rel_type = t
                break
        if rel_type:
            break
    if rel_type is None:
        rel_type = df_types_out.loc[0,'type']

    # Inspect rel properties
    df_sample = run_cypher(f"MATCH (n)-[r:`{rel_type}`]->() WHERE id(n)=$nid RETURN r LIMIT 200", {"nid": nid})
    rel_rows = [row['r'] for _,row in df_sample.iterrows()]
    rel_prop_keys = set().union(*[set(r.keys()) for r in rel_rows]) if rel_rows else set()
    TIME_KEYS = ['timestamp','block_timestamp','blockTimestamp','time','ts','block_time','datetime']
    VALUE_KEYS = ['value','amount','value_eth','valueEth','eth','value_wei','valueWei','wei','amount_wei','amountWei']
    time_prop = next((k for k in TIME_KEYS if k in rel_prop_keys), None)
    if time_prop is None and rel_rows:
        for k in rel_prop_keys:
            vals = [rp.get(k) for rp in rel_rows if k in rp]
            nums = [v for v in vals if isinstance(v,(int,float))]
            if nums and float(np.median(nums)) > 1e8:
                time_prop = k
                break
    value_prop = next((k for k in VALUE_KEYS if k in rel_prop_keys), None)

    # Time window
    start_ts_num = None; end_ts_num=None; time_kind=None
    if time_prop is not None:
        df_times = run_cypher(f"MATCH (n)-[r:`{rel_type}`]->() WHERE id(n)=$nid AND r.`{time_prop}` IS NOT NULL RETURN r.`{time_prop}` AS ts LIMIT 2000", {"nid": nid})
        ts_vals = df_times['ts'].dropna().tolist()
        if ts_vals:
            s = ts_vals[0]
            if isinstance(s,(int,float)):
                arr=[float(x) for x in ts_vals if isinstance(x,(int,float))]
                vmed=float(np.median(arr))
                if vmed>1e14: scale=1e-9
                elif vmed>1e12: scale=1e-6
                elif vmed>1e11: scale=1e-3
                else: scale=1.0
                start_ts_num=min(arr)*scale
                end_ts_num=start_ts_num+14*24*3600
                time_kind='numeric'
            elif isinstance(s,str):
                pds=pd.to_datetime(pd.Series(ts_vals),utc=True,errors='coerce').dropna()
                if not pds.empty:
                    start_ts_num=pds.min().to_pydatetime().astimezone(timezone.utc).timestamp()
                    end_ts_num=start_ts_num+14*24*3600
                    time_kind='string_iso'
            else:
                try:
                    from neo4j.time import DateTime as NeoDateTime
                    if isinstance(s,NeoDateTime):
                        pyts=[]
                        for v in ts_vals:
                            try: py=v.to_native()
                            except Exception: py=datetime(v.year,v.month,v.day,v.hour,v.minute,int(v.second),tzinfo=timezone.utc)
                            pyts.append(py)
                        start_ts_num=min(pyts).timestamp()
                        end_ts_num=start_ts_num+14*24*3600
                        time_kind='temporal'
                except Exception:
                    pass
        if time_kind is None:
            time_prop=None

    # Value scale and thresholds
    value_scale=1.0; baseline_min_val_eth=0.0; alt_min_val_eth=0.0
    if value_prop is not None:
        df_vals=run_cypher(f"MATCH (n)-[r:`{rel_type}`]->() WHERE id(n)=$nid AND r.`{value_prop}` IS NOT NULL RETURN r.`{value_prop}` AS v LIMIT 5000", {"nid": nid})
        raw_vals=df_vals['v'].dropna().tolist()
        vs=[]
        for v in raw_vals:
            if isinstance(v,(int,float)): vs.append(float(v))
            elif isinstance(v,str):
                try: vs.append(float(v))
                except: pass
        if vs:
            vmed=float(np.median(vs)); vmax=float(max(vs))
            value_scale=1e-18 if (vmed>1e12 or vmax>1e15) else 1.0
            vs_eth=[v*value_scale for v in vs]
            if len(vs_eth)>=5:
                p90=float(np.percentile(vs_eth,90)); p50=float(np.percentile(vs_eth,50))
                alt_min_val_eth=max(0.01,0.25*p50,0.1*p90)

    def expand_k_hops(max_hops=4, min_val_eth=0.0, time_kind=time_kind, start_ts_num=start_ts_num, end_ts_num=end_ts_num, max_nodes=20000):
        nodes=set([nid]); frontier=set([nid]); edges=set()
        min_val_raw=(min_val_eth/value_scale) if value_prop is not None else None
        time_where=""; params_base={}
        if time_prop is not None and time_kind is not None and start_ts_num is not None and end_ts_num is not None:
            if time_kind=='numeric':
                time_where=f" AND toFloat(r.`{time_prop}`) >= $start AND toFloat(r.`{time_prop}`) <= $end"; params_base.update({"start":float(start_ts_num),"end":float(end_ts_num)})
            else:
                start_iso=datetime.fromtimestamp(start_ts_num,tz=timezone.utc).isoformat(); end_iso=datetime.fromtimestamp(end_ts_num,tz=timezone.utc).isoformat()
                time_where=f" AND datetime(r.`{time_prop}`) >= datetime($startIso) AND datetime(r.`{time_prop}`) <= datetime($endIso)"; params_base.update({"startIso":start_iso,"endIso":end_iso})
        for _ in range(max_hops):
            if not frontier or len(nodes)>=max_nodes: break
            q=f"MATCH (s)-[r:`{rel_type}`]->(t) WHERE id(s) IN $frontier"; params={"frontier":list(frontier)}
            q+=time_where; params.update(params_base)
            if value_prop is not None and min_val_raw is not None and min_val_raw>0:
                q+=f" AND toFloat(r.`{value_prop}`) >= $minVal"; params.update({"minVal":float(min_val_raw)})
            q+=" RETURN DISTINCT id(s) AS s, id(t) AS t LIMIT 10000"
            df_step=run_cypher(q,params)
            new_frontier=set()
            for _,row in df_step.iterrows():
                s=int(row['s']); t=int(row['t']); edges.add((s,t))
                if t not in nodes:
                    new_frontier.add(t); nodes.add(t)
            frontier=new_frontier
        return nodes, edges

    def fetch_edges(nodes_set, min_val_eth=0.0, time_kind=time_kind, start_ts_num=start_ts_num, end_ts_num=end_ts_num):
        nodeIds=list(nodes_set)
        if not nodeIds: return pd.DataFrame(columns=['s','t','w'])
        q=f"MATCH (s)-[r:`{rel_type}`]->(t) WHERE id(s) IN $nodeIds AND id(t) IN $nodeIds"; params={"nodeIds":nodeIds}
        if time_prop is not None and time_kind is not None and start_ts_num is not None and end_ts_num is not None:
            if time_kind=='numeric': q+=f" AND toFloat(r.`{time_prop}`) >= $start AND toFloat(r.`{time_prop}`) <= $end"; params.update({"start":float(start_ts_num),"end":float(end_ts_num)})
            else:
                start_iso=datetime.fromtimestamp(start_ts_num,tz=timezone.utc).isoformat(); end_iso=datetime.fromtimestamp(end_ts_num,tz=timezone.utc).isoformat()
                q+=f" AND datetime(r.`{time_prop}`) >= datetime($startIso) AND datetime(r.`{time_prop}`) <= datetime($endIso)"; params.update({"startIso":start_iso,"endIso":end_iso})
        if value_prop is not None and min_val_eth is not None and min_val_eth>0:
            min_raw=min_val_eth/value_scale; q+=f" AND toFloat(r.`{value_prop}`) >= $minVal"; params.update({"minVal":float(min_raw)})
        if value_prop is not None:
            q+=f" RETURN id(s) AS s, id(t) AS t, toFloat(r.`{value_prop}`) * $vscale AS w"; params.update({"vscale":float(value_scale)})
        else:
            q+=" RETURN id(s) AS s, id(t) AS t, 1.0 AS w"
        return run_cypher(q,params)

    baseline_params={'max_hops':4,'min_val_eth':0.0,'time_kind':time_prop and time_kind,'start_ts_num':start_ts_num,'end_ts_num':end_ts_num,'max_nodes':15000}
    alt_params={'max_hops':3,'min_val_eth':alt_min_val_eth,'time_kind':time_prop and time_kind,'start_ts_num':start_ts_num,'end_ts_num':(start_ts_num+7*24*3600 if start_ts_num is not None else None),'max_nodes':10000}

    nodes_base, edges_base = expand_k_hops(**baseline_params)
    nodes_alt, edges_alt = expand_k_hops(**alt_params)

    df_edges_base=fetch_edges(nodes_base, **{k:baseline_params[k] for k in ['min_val_eth','time_kind','start_ts_num','end_ts_num']})
    df_edges_alt=fetch_edges(nodes_alt, **{k:alt_params[k] for k in ['min_val_eth','time_kind','start_ts_num','end_ts_num']})

    def taint(df_edges, K):
        out_map={}
        for _,row in df_edges.iterrows():
            s=int(row['s']); t=int(row['t']); w=float(row['w']); out_map.setdefault(s,[]).append((t,w))
        denom={s:sum(w for _,w in lst) for s,lst in out_map.items()}
        node_list=list(set(list(df_edges['s'].astype(int))+list(df_edges['t'].astype(int))+[nid]))
        id2idx={n:i for i,n in enumerate(node_list)}; idx2id={i:n for n,i in id2idx.items()}
        if nid not in id2idx: return pd.DataFrame(columns=['nodeId','score','address'])
        nN=len(node_list); cur=np.zeros(nN); cur[id2idx[nid]]=1.0; cum=np.zeros(nN)
        for _ in range(K):
            nxt=np.zeros(nN)
            for s,lst in out_map.items():
                si=id2idx.get(s); d=denom.get(s,0.0)
                if si is None or d<=0 or cur[si]==0: continue
                frac=cur[si]/d
                for t,w in lst:
                    ti=id2idx.get(t)
                    if ti is not None: nxt[ti]+=frac*w
            cum+=nxt; cur=nxt
        df=pd.DataFrame({'nodeId':[int(idx2id[i]) for i in range(nN)],'score':cum})
        if not df.empty:
            df_map=run_cypher(f"MATCH (n) WHERE id(n) IN $ids RETURN id(n) AS id, n.`{node_addr_prop}` AS addr", {"ids": df['nodeId'].astype(int).tolist()})
            id2addr={int(r['id']):r['addr'] for _,r in df_map.iterrows()}; df['address']=df['nodeId'].map(id2addr)
            df=df[(df['address'].notna()) & (df['address'].str.lower()!=stolen_addr.lower())]
