    def rwr(df_edges, alpha=0.2, tol=1e-8, max_iter=100):
        out_map={}
        for _,row in df_edges.iterrows():
            s=int(row['s']); t=int(row['t']); w=float(row['w']); out_map.setdefault(s,[]).append((t,w))
        denom={s:sum(w for _,w in lst) for s,lst in out_map.items()}
        node_list=list(set(list(df_edges['s'].astype(int))+list(df_edges['t'].astype(int))+[nid]))
        id2idx={n:i for i,n in enumerate(node_list)}; idx2id={i:n for n,i in id2idx.items()}
        if nid not in id2idx: return pd.DataFrame(columns=['nodeId','score','address'])
        nN=len(node_list); r=np.zeros(nN); r[id2idx[nid]]=1.0; p=r.copy()
        for _ in range(max_iter):
            p_new=np.zeros(nN)
            for s,lst in out_map.items():
                si=id2idx.get(s); d=denom.get(s,0.0)
                if si is None or d==0: continue
                contrib=(1-alpha)*(p[si]/d)
                if contrib==0: continue
                for t,w in lst:
                    ti=id2idx.get(t)
                    if ti is not None: p_new[ti]+=contrib*w
            p_new+=alpha*r
            if np.linalg.norm(p_new-p,1)<tol: p=p_new; break
            p=p_new
        df=pd.DataFrame({'nodeId':[int(idx2id[i]) for i in range(nN)],'score':p})
        if not df.empty:
            df_map=run_cypher(f"MATCH (n) WHERE id(n) IN $ids RETURN id(n) AS id, n.`{node_addr_prop}` AS addr", {"ids": df['nodeId'].astype(int).tolist()})
            id2addr={int(r['id']):r['addr'] for _,r in df_map.iterrows()}; df['address']=df['nodeId'].map(id2addr)
