    def to_rank_map(lst): return {rec['address'].lower():i for i,rec in enumerate(lst)}
    rtb=to_rank_map(top_taint_base); rta=to_rank_map(top_taint_alt); rrb=to_rank_map(top_rwr_base); rra=to_rank_map(top_rwr_alt)
    all_addrs=set(list(rtb.keys())+list(rta.keys())+list(rrb.keys())+list(rra.keys()))
    stab=[]
    for a in all_addrs:
        ranks=[]
        for r in [rtb,rta,rrb,rra]:
            if a in r: ranks.append(r[a])
        stab.append({'address':a,'presence':len(ranks),'avg_rank':float(np.mean(ranks)) if ranks else None,'best_rank':float(np.min(ranks)) if ranks else None})
    stab_df=pd.DataFrame(stab)
    if not stab_df.empty:
        stab_df['stability']=stab_df['presence']+stab_df['best_rank'].apply(lambda x:0 if x is None else max(0,200-x)/200.0)
    base_df=pd.DataFrame(top_rwr_base)
    if not base_df.empty:
        base_df['addr_lower']=base_df['address'].str.lower(); s=stab_df.rename(columns={'address':'addr_lower'})
        merged=base_df.merge(s[['addr_lower','stability','presence']],on='addr_lower',how='left')
        merged[['stability','presence']]=merged[['stability','presence']].fillna(0)
        in_taint=set([x['address'].lower() for x in top_taint_base])
        merged['consensus_boost']=merged['addr_lower'].apply(lambda a:0.1 if a in in_taint else 0.0)
        merged['composite']=merged['norm']+0.2*merged['stability']+0.1*merged['presence']+merged['consensus_boost']
        merged=merged.sort_values(['composite','norm','score'],ascending=[False,False,False])
        final_addresses=merged['address'].head(100).tolist()
    else:
        final_addresses=[rec['address'] for rec in top_taint_base][:100]

    uncertain=[]
    if not stab_df.empty:
        uncertain=stab_df[stab_df['presence']<=1].sort_values(['presence','best_rank'],ascending=[True,True]).head(20)['address'].tolist()

    payload={
        'ok':True,
        'meta':{
            'db':NEO4J_DATABASE,'rel_type':rel_type,'time_prop':time_prop,'value_prop':value_prop,'time_kind':time_kind,
            'value_scale_to_eth':value_scale,
            'counts':{'nodes_base':len(nodes_base),'nodes_alt':len(nodes_alt),'edges_base':len(edges_base),'edges_alt':len(edges_alt),'edges_base_rows':int(len(df_edges_base)),'edges_alt_rows':int(len(df_edges_alt))}
        },
        'top_rwr_base':top_rwr_base[:20],
        'top_taint_base':top_taint_base[:20],
        'final_addresses':final_addresses,
        'uncertain_addresses':uncertain[:20]
    }
    print(json.dumps(payload))
except Exception as e:
    print(json.dumps({"ok": False, "error": str(e)}))

