import os, sys, json, math, statistics, re
from typing import List, Dict, Any, Optional, Tuple

from neo4j import GraphDatabase
from graphdatascience import GraphDataScience

addr_stolen = "0x1db92e2eebc8e0c075a02bea49a2935bcd2dfcf4".lower()

uri = os.getenv("NEO4J_URI")
user = os.getenv("NEO4J_USERNAME")
pwd = os.getenv("NEO4J_PASSWORD")
db = os.getenv("NEO4J_DATABASE")

out: Dict[str, Any] = {"summary": "", "final_list": [], "debug": []}

if not uri or not user or not pwd:
    out["summary"] = "Database credentials not found in environment."
    print(json.dumps(out))
    sys.exit(0)

# Helper logger

def log(msg):
    out["debug"].append(str(msg))

try:
    driver = GraphDatabase.driver(uri, auth=(user, pwd))
    # Verify connectivity
    with driver.session(database=db) as s:
        ver = s.run("CALL dbms.components() YIELD name, versions RETURN name, versions[0] AS version LIMIT 1").single()
        if ver:
            log(f"DB component: {ver['name']} {ver['version']}")
except Exception as e:
    out["summary"] = f"Failed to connect to Neo4j: {e}"
    print(json.dumps(out))
    sys.exit(0)

# Try instantiate GDS client
try:
    if db:
        gds = GraphDataScience(uri, auth=(user, pwd), database=db)
    else:
        gds = GraphDataScience(uri, auth=(user, pwd))
    gds.set_database(db) if db else None
    gds_ver = None
    try:
        gds_ver = gds.version()
        log(f"GDS version: {gds_ver}")
    except Exception as ge:
        log(f"GDS version check failed: {ge}")
except Exception as e:
    out["summary"] = f"Failed to initialize Graph Data Science client: {e}"
    print(json.dumps(out))
    sys.exit(0)

# Utility for running cypher

def run_cypher(query: str, params: Dict[str, Any] = None):
    with driver.session(database=db) as s:
        return list(s.run(query, params or {}))

# Discover property keys to find the address node
prop_keys = []
try:
    rows = run_cypher("CALL db.propertyKeys() YIELD property RETURN property")
    prop_keys = [r["property"] for r in rows]
except Exception as e:
    log(f"Failed to fetch property keys: {e}")

candidate_addr_props = [
    "address", "hash", "id", "addr", "address_lower", "addressHash", "address_hash",
    "addressHex", "hex", "addressStr", "account", "accountAddress", "wallet", "node"
]
# Try all db property keys too
for k in prop_keys:
    if k not in candidate_addr_props:
        candidate_addr_props.append(k)

node_match = None
addr_prop_used = None
labels_found = []

for p in candidate_addr_props:
    try:
        q = f"MATCH (n) WHERE exists(n.`{p}`) AND toLower(n.`{p}`) = $a RETURN id(n) AS id, labels(n) AS labels, n.`{p}` AS address LIMIT 1"
        rows = run_cypher(q, {"a": addr_stolen})
        if rows:
            node_match = {"id": rows[0]["id"], "address": rows[0]["address"]}
            labels_found = rows[0]["labels"]
            addr_prop_used = p
            break
    except Exception as e:
        continue

if node_match is None:
    # Try common labels with likely property names
    common_labels = ["Address", "ACCOUNT", "Account", "Wallet", "EOA", "User", "ETHAddress", "EVMAddress"]
    label_props = ["address", "hash", "id", "addr", "address_lower"]
    for lbl in common_labels:
        for p in label_props:
            try:
                q = f"MATCH (n:`{lbl}`) WHERE exists(n.`{p}`) AND toLower(n.`{p}`) = $a RETURN id(n) AS id, labels(n) AS labels, n.`{p}` AS address LIMIT 1"
                rows = run_cypher(q, {"a": addr_stolen})
                if rows:
                    node_match = {"id": rows[0]["id"], "address": rows[0]["address"]}
                    labels_found = rows[0]["labels"]
                    addr_prop_used = p
                    break
            except Exception:
