        if node_match:
            break

if node_match is None:
    out["summary"] = "Could not find the stolen-from address in the database."
    print(json.dumps(out))
    sys.exit(0)

stolen_node_id = node_match["id"]
log(f"Found stolen-from node id={stolen_node_id}, labels={labels_found}, via property {addr_prop_used}")

# Determine outgoing relationship type representing ETH transfers
reltype_counts_out = run_cypher("MATCH (n)-[r]->() WHERE id(n)=$id RETURN type(r) AS type, count(r) AS c ORDER BY c DESC LIMIT 10", {"id": stolen_node_id})
reltype_counts_in = run_cypher("MATCH ()-[r]->(n) WHERE id(n)=$id RETURN type(r) AS type, count(r) AS c ORDER BY c DESC LIMIT 10", {"id": stolen_node_id})

rel_candidates: List[str] = []
for r in reltype_counts_out:
    rel_candidates.append(r["type"])
for r in reltype_counts_in:
    if r["type"] not in rel_candidates:
        rel_candidates.append(r["type"])

if not rel_candidates:
    out["summary"] = "The stolen-from address has no relationships in the graph."
    print(json.dumps(out))
    sys.exit(0)

# Heuristic: prefer types with names suggesting transfer
preferred_names = ["TRANSFER", "ETH_TRANSFER", "SENT", "SEND", "TX", "TRANSFERRED", "TOKEN_TRANSFER", "NATIVE_TRANSFER"]

chosen_reltype = None
for name in preferred_names:
    for t in rel_candidates:
        if name.lower() in t.lower():
            chosen_reltype = t
