    chosen_reltype = reltype_counts_out[0]["type"] if reltype_counts_out else rel_candidates[0]

log(f"Chosen relationship type: {chosen_reltype}")

# Sample relationship keys to pick amount and time properties
keys_rows = run_cypher(f"MATCH ()-[r:`{chosen_reltype}`]->() RETURN keys(r) AS k LIMIT 200")
all_r_keys = set()
for row in keys_rows:
    for k in row["k"]:
        all_r_keys.add(k)

amount_key_candidates = [k for k in all_r_keys if re.search(r"(amount|value|wei|eth)", k, re.IGNORECASE)]
if not amount_key_candidates:
