    amount_key_candidates = list(all_r_keys)

# Function to pick best numeric property as amount

def pick_amount_prop(cands: List[str]) -> Tuple[Optional[str], Optional[float], str]:
    best = None
    best_med = -1.0
    unit = "eth"
    for p in cands:
        try:
            q = f"MATCH ()-[r:`{chosen_reltype}`]->() WHERE exists(r.`{p}`) RETURN toFloat(r.`{p}`) AS v LIMIT 500"
            vals = [row["v"] for row in run_cypher(q) if row["v"] is not None]
            if len(vals) < 5:
                continue
            # filter zeros
            nz = [v for v in vals if v and v > 0]
            if len(nz) < 5:
                continue
            med = statistics.median(nz)
            if med > best_med:
                best = p
                best_med = med
        except Exception:
            continue
    if best is None:
        return None, None, unit
    # Decide wei vs eth
    unit = "wei" if best_med and best_med > 1e12 else "eth"
    return best, best_med, unit

amount_prop, amount_median, amount_unit = pick_amount_prop(amount_key_candidates)
if amount_prop is None:
