    print(json.dumps(out))
    sys.exit(0)

log(f"Chosen amount property: {amount_prop} (median={amount_median}, unit={amount_unit})")

# Pick time property

time_key_candidates = [k for k in all_r_keys if re.search(r"(time|timestamp|blockTime|ts)", k, re.IGNORECASE)]

chosen_time_prop = None
units = None
if time_key_candidates:
    best_tp = None
    best_scale = 0
    for p in time_key_candidates:
        try:
            q = f"MATCH ()-[r:`{chosen_reltype}`]->() WHERE exists(r.`{p}`) RETURN toFloat(r.`{p}`) AS v ORDER BY v DESC LIMIT 2"
            rows = run_cypher(q)
            if not rows:
                continue
            vmax = rows[0]["v"]
            if vmax and vmax > best_scale:
                best_scale = vmax
                best_tp = p
        except Exception:
