log(f"Time property: {chosen_time_prop} (units approx {units}))")

# Determine first outgoing time from stolen address
min_time = None
max_time = None
if chosen_time_prop:
    try:
        q = f"MATCH (n)-[r:`{chosen_reltype}`]->() WHERE id(n)=$id AND exists(r.`{tp}`) RETURN min(toFloat(r.`{tp}`)) AS mn, max(toFloat(r.`{tp}`)) AS mx"
        row = run_cypher(q, {"id": stolen_node_id, "tp": chosen_time_prop})[0]
        min_time = row["mn"]
        max_time = row["mx"]
    except Exception as e:
        log(f"Error fetching min/max time: {e}")

# Build helper to project graph via Cypher

def project_graph(graph_name: str, max_hops: int, min_eth: float, window_days: Optional[int], decay: bool, half_life_days: float) -> Dict[str, Any]:
    # Prepare expressions
    amt_expr = f"toFloat(rel.`{amount_prop}`)"
    if amount_unit == "wei":
        amt_expr = f"(toFloat(rel.`{amount_prop}`) / 1e18)"

    time_filter = ""
    params = {"theft_id": stolen_node_id, "min_eth": float(min_eth)}
    day_div = None
    lam = None

    if chosen_time_prop and window_days and min_time is not None:
        if units == "ms":
            day_div = 86400000.0
        elif units == "s":
            day_div = 86400.0
        elif units == "block":
            # Approx block time 12s -> convert blocks to days
            day_div = (24*60*60) / 12.0
        else:
            day_div = 86400.0
        t0 = float(min_time)
        t1 = t0 + window_days * day_div
        params.update({"t0": t0, "t1": t1})
        time_filter = f" AND toFloat(rel.`{chosen_time_prop}`) >= $t0 AND toFloat(rel.`{chosen_time_prop}`) <= $t1"
    else:
        # no time filter
        pass

    weight_expr = amt_expr
    if decay and chosen_time_prop and min_time is not None:
        # half-life to lambda
        lam = math.log(2) / max(half_life_days, 0.1)
        params.update({"lam": lam, "t0": float(min_time)})
        if not day_div:
            if units == "ms":
                day_div = 86400000.0
            elif units == "s":
                day_div = 86400.0
            elif units == "block":
                day_div = (24*60*60) / 12.0
            else:
                day_div = 86400.0
        params.update({"dayDiv": day_div})
        weight_expr = f"({amt_expr}) * exp(-$lam * ((toFloat(rel.`{chosen_time_prop}`) - $t0) / $dayDiv))"

    eps = 1e-9
    cost_expr = f"(1.0 / ({amt_expr} + {eps}))"

    node_query = f"""
    MATCH (s) WHERE id(s) = $theft_id
    MATCH p=(s)-[:`{chosen_reltype}`*1..{max_hops}]->(n)
    UNWIND nodes(p) AS m
    RETURN DISTINCT id(m) AS id
    """

    rel_query = f"""
    MATCH (s) WHERE id(s) = $theft_id
    MATCH p=(s)-[r:`{chosen_reltype}`*1..{max_hops}]->(n)
    UNWIND r AS rel
    WITH DISTINCT rel
    MATCH (src)-[rel]->(dst)
    WHERE ({amt_expr}) >= $min_eth{time_filter}
    RETURN id(src) AS source, id(dst) AS target, {weight_expr} AS weight, {cost_expr} AS cost
    """

    # Drop if exists
    try:
        try:
            gds.graph.drop(graph_name)
        except Exception:
            pass
        G = gds.graph.project.cypher(graph_name, node_query, rel_query, params)
        return {"graphName": graph_name, "nodeCount": G.node_count(), "relationshipCount": G.relationship_count(), "params": params}
    except Exception as e:
        return {"error": str(e), "graphName": graph_name}

# Helper to map node id -> address string

def node_ids_to_addresses(node_ids: List[int]) -> Dict[int, str]:
    if not node_ids:
        return {}
    # We'll attempt reading the same property used for the stolen node; if absent, try common keys
    addrs: Dict[int, str] = {}
    # Batch in chunks
    chunk = 1000
    props_try = [addr_prop_used] + [p for p in ["address","hash","id","addr","address_lower"] if p != addr_prop_used]
    for i in range(0, len(node_ids), chunk):
        part = node_ids[i:i+chunk]
        q = "WITH $ids AS ids UNWIND ids AS id MATCH (n) WHERE id(n)=id RETURN id(n) AS id, n AS n"
        rows = run_cypher(q, {"ids": part})
        for r in rows:
            nid = r["id"]
            n = r["n"]
            addr = None
            for p in props_try:
                if p in n and n[p]:
                    addr = n[p]
                    break
            if not addr:
                addr = str(nid)
            addrs[nid] = addr
    return addrs

# Build two graphs: G1 (no decay, wider window), G2 (decay, tighter window)
max_hops = 4
G1 = project_graph("G1_theft_graph", max_hops=max_hops, min_eth=0.1, window_days=30, decay=False, half_life_days=1.0)
G2 = project_graph("G2_theft_graph", max_hops=max_hops, min_eth=0.5, window_days=7, decay=True, half_life_days=1.0)

if "error" in G1:
    out["summary"] = f"Failed to project graph G1: {G1['error']}"
    print(json.dumps(out))
    sys.exit(0)
if "error" in G2:
    log(f"Warning: Failed to project decayed graph G2: {G2['error']}")

log(f"G1 projected: nodes={G1['nodeCount']}, rels={G1['relationshipCount']}")
if "nodeCount" in G2:
    log(f"G2 projected: nodes={G2['nodeCount']}, rels={G2['relationshipCount']}")

# Define algorithms

def run_bfs(graph_name: str, max_depth: int) -> Dict[int, int]:
    depths = {}
    try:
        rows = gds.run_cypher(
            "CALL gds.bfs.stream($g, {sourceNode: $s, maxDepth: $d}) YIELD nodeId, depth RETURN nodeId, depth",
            {"g": graph_name, "s": stolen_node_id, "d": max_depth},
        )
        for r in rows:
            depths[r["nodeId"]] = r["depth"]
    except Exception as e:
        # try beta API
        try:
            rows = gds.run_cypher(
                "CALL gds.beta.bfs.stream($g, {sourceNode: $s, maxDepth: $d}) YIELD nodeId, depth RETURN nodeId, depth",
                {"g": graph_name, "s": stolen_node_id, "d": max_depth},
            )
            for r in rows:
                depths[r["nodeId"]] = r["depth"]
        except Exception as e2:
            log(f"BFS failed on {graph_name}: {e2}")
    return depths


def run_ppr(graph_name: str) -> List[Tuple[int, float]]:
    rows = []
    # Try standard PPR with sourceNodes
    for call in [
        "CALL gds.pageRank.stream($g, {sourceNodes: [$s], relationshipWeightProperty: 'weight', maxIterations: 50, dampingFactor: 0.85}) YIELD nodeId, score RETURN nodeId, score ORDER BY score DESC LIMIT 5000",
        "CALL gds.pageRank.stream($g, {personalized: true, sourceNodes: [$s], relationshipWeightProperty: 'weight', maxIterations: 50, dampingFactor: 0.85}) YIELD nodeId, score RETURN nodeId, score ORDER BY score DESC LIMIT 5000",
        "CALL gds.alpha.pageRank.stream($g, {sourceNodes: [$s], relationshipWeightProperty: 'weight', maxIterations: 50, dampingFactor: 0.85}) YIELD nodeId, score RETURN nodeId, score ORDER BY score DESC LIMIT 5000",
        "CALL gds.alpha.pageRank.stream($g, {personalized: true, sourceNodes: [$s], relationshipWeightProperty: 'weight', maxIterations: 50, dampingFactor: 0.85}) YIELD nodeId, score RETURN nodeId, score ORDER BY score DESC LIMIT 5000",
    ]:
        try:
            rows = gds.run_cypher(call, {"g": graph_name, "s": stolen_node_id})
            break
        except Exception as e:
            last_err = str(e)
            continue
    if not rows:
        log(f"PPR failed on {graph_name}: {last_err}")
        return []
    return [(r["nodeId"], r["score"]) for r in rows]


def run_dijkstra(graph_name: str, max_hops_filter: int) -> List[Tuple[int, float, int]]:
    rows = []
    try:
        rows = gds.run_cypher(
            "CALL gds.shortestPath.dijkstra.stream($g, {sourceNode: $s, relationshipWeightProperty: 'cost'}) YIELD sourceNode, targetNode, totalCost, nodeIds RETURN targetNode AS nodeId, totalCost AS cost, size(nodeIds)-1 AS hops",
            {"g": graph_name, "s": stolen_node_id},
        )
    except Exception as e:
        log(f"Dijkstra failed on {graph_name}: {e}")
        return []
    out_rows = []
    for r in rows:
        if r["nodeId"] == stolen_node_id:
            continue
        hops = r["hops"] if r["hops"] is not None else 0
        if max_hops_filter and hops > max_hops_filter:
            continue
        out_rows.append((r["nodeId"], r["cost"], hops))
    # Rank by inverse cost
    out_rows.sort(key=lambda x: (x[1], x[2]))
    return out_rows

