from collections import defaultdict

def to_rank_map(lst: List[Tuple[int, float]], reverse: bool = True) -> Dict[int, int]:
    # lst is (nodeId, score); reverse True means higher score better
    ranks = {}
    for i, (nid, sc) in enumerate(sorted(lst, key=lambda x: x[1], reverse=reverse), start=1):
        if nid not in ranks:
            ranks[nid] = i
    return ranks

def to_rank_map_dij(lst: List[Tuple[int, float, int]]) -> Dict[int, int]:
    # lst is (nodeId, cost, hops); lower cost better
    # Already sorted by cost then hops; assign ranks
    ranks = {}
    for i, (nid, cost, hops) in enumerate(lst, start=1):
        if nid not in ranks:
            ranks[nid] = i
    return ranks

