r_G1_DIJ = to_rank_map_dij(DI1)
r_G2_DIJ = to_rank_map_dij(DI2) if DI2 else {}

# Stability analysis: compute average rank across variants and disagreement
all_nodes = set(r_G1_PPR) | set(r_G2_PPR) | set(r_G1_DIJ) | set(r_G2_DIJ)

stability = {}
for nid in all_nodes:
