    if nid in r_G2_DIJ:
        ranks.append(r_G2_DIJ[nid]); sources.append("G2_DIJ")
    avg_rank = statistics.mean(ranks) if ranks else 1e9
    var_rank = statistics.pvariance(ranks) if len(ranks) > 1 else 0.0
    methods = ",".join(sources)
    stability[nid] = {"avg_rank": avg_rank, "var_rank": var_rank, "methods": methods, "count": len(ranks)}

# Choose which approach to trust: If PPR rankings are more stable between G1 and G2 than Dijkstra, trust PPR, else Dijkstra
# Compute Jaccard of top-20 between G1 and G2 for each approach

def topk(lst, k):
    return [x[0] for x in lst[:k]]

k = 20
set_ppr1 = set(topk(ppr1, k))
set_ppr2 = set(topk(ppr2, k)) if ppr2 else set()
set_di1 = set([x[0] for x in DI1[:k]])
set_di2 = set([x[0] for x in DI2[:k]]) if DI2 else set()

def jacc(a: set, b: set) -> float:
    if not a and not b:
        return 1.0
    if not a or not b:
        return 0.0
    return len(a & b) / len(a | b)

ppr_jacc = jacc(set_ppr1, set_ppr2) if set_ppr2 else None
dij_jacc = jacc(set_di1, set_di2) if set_di2 else None

