MATCH (a) WHERE id(a) = $id
MATCH (a)-[r]->() RETURN type(r) AS t, count(*) AS c
UNION ALL
MATCH (a) WHERE id(a) = $id
MATCH ()-[r]->(a) RETURN type(r) AS t, count(*) AS c
"""
for r in run(q, {"id": src_id}):
    rel_counts[r["t"]] = rel_counts.get(r["t"], 0) + r["c"]
rel_type = sorted(rel_counts.items(), key=lambda kv: (0 if any(s in kv[0].upper() for s in ["TRANSFER","TX","SENT","PAYMENT"]) else 1, -kv[1]))[0][0]

