    except Exception: mut_ok=False
    pr_rows = run("CALL gds.pageRank.stream($g,$cfg) YIELD nodeId, score RETURN nodeId, score", {"g": g, "cfg": {"maxIterations": 40, "dampingFactor": 0.85}})
    try:
        sp_rows = run("CALL gds.shortestPath.deltaStepping.stream($g,$cfg) YIELD nodeId, distance RETURN nodeId, distance", {"g": g, "cfg": {"sourceNode": src_id}})
    except Exception:
        sp_rows = run("CALL gds.shortestPath.dijkstra.stream($g,$cfg) YIELD nodeId, distance RETURN nodeId, distance", {"g": g, "cfg": {"sourceNode": src_id}})
    if mut_ok:
        comm_rows = run("CALL gds.graph.nodeProperty.stream($g,$p) YIELD nodeId, propertyValue RETURN nodeId, propertyValue", {"g": g, "p": "comm"})
        comm_map = {r['nodeId']: r['propertyValue'] for r in comm_rows}
    else:
        lrows = run("CALL gds.louvain.stream($g) YIELD nodeId, communityId RETURN nodeId, communityId", {"g": g})
        comm_map = {r['nodeId']: r['communityId'] for r in lrows}
    src_comm = comm_map.get(src_id)
    node_ids = list(set([r['nodeId'] for r in pr_rows] + [r['nodeId'] for r in sp_rows]))
    addrs = run(f"MATCH (n:`{addr_label}`) WHERE id(n) IN $ids RETURN id(n) AS nodeId, n.address AS address", {"ids": node_ids})
    id2a = {r['nodeId']: r['address'] for r in addrs}
    dist_map = {r['nodeId']: r['distance'] for r in sp_rows}
    out=[]
    for r in pr_rows:
        nid=r['nodeId']
        if nid==src_id: continue
        if src_comm is not None and comm_map.get(nid)!=src_comm: continue
        if nid not in dist_map: continue
        addr = id2a.get(nid)
        if not addr: continue
        out.append({"address": addr, "pr": r['score'], "dist": dist_map[nid]})
    if not out:
        run("CALL gds.graph.drop($g,false)", {"g": g}); return []
    prs=[o['pr'] for o in out]; mn, mx = min(prs), max(prs)
    for o in out:
        prn = 1.0 if mx==mn else (o['pr']-mn)/(mx-mn)
        invd = 1.0/(1.0+min(max(o['dist'],0),10))
