    w, pm = where_params(days)
    params = {"ids": ids, **pm}
    node_q = "UNWIND $ids AS id RETURN DISTINCT id AS id"
    rel_q = f"MATCH (s:`{addr_label}`)-[r:`{rt}`]->(t:`{addr_label}`) WHERE id(s) IN $ids AND id(t) IN $ids AND {w} RETURN id(s) AS source, id(t) AS target"
    run("CALL gds.graph.project.cypher($g,$nq,$rq,$cfg) YIELD graphName RETURN graphName", {"g": name, "nq": node_q, "rq": rel_q, "cfg": {"parameters": params}})


