    project(g, ids, days)
    # Shortest paths from source to all targets
    sp = run("CALL gds.shortestPath.dijkstra.stream($g,$c) YIELD sourceNode, targetNode, totalCost, nodeIds RETURN sourceNode, targetNode, totalCost, nodeIds", {"g": g, "c": {"sourceNode": src_id}})
    # Degree
    deg = run("CALL gds.degree.stream($g,$c) YIELD nodeId, score RETURN nodeId, score", {"g": g, "c": {"orientation": "OUTGOING"}})
    deg_map = {r['nodeId']: r['score'] for r in deg}
    # Map ids to addresses
    all_ids = list(set([r['targetNode'] for r in sp if r['targetNode']!=src_id]))
    addrs = run(f"MATCH (n:`{addr_label}`) WHERE id(n) IN $ids RETURN id(n) AS id, n.address AS address", {"ids": all_ids})
    id2a = {r['id']: r['address'] for r in addrs}
    # Build scores
    out=[]
    if sp:
        max_deg = max(deg_map.values()) if deg_map else 1
        for r in sp:
            tid = r['targetNode']
            if tid==src_id: continue
            addr = id2a.get(tid)
            if not addr: continue
            # if totalCost is 0 or missing, derive from path length
            dist = r['totalCost'] if r['totalCost'] is not None else (len(r.get('nodeIds',[]))-1)
            invd = 1.0/(1.0+min(max(dist,0),10))
            dgn = (deg_map.get(tid,0)/(max_deg if max_deg>0 else 1))
            score = 0.7*invd + 0.3*dgn
            out.append({"address": addr, "score": score, "dist": dist, "deg": deg_map.get(tid,0)})
    # Deduplicate by best score per address
    best={}
    for o in out:
        if o['address'] not in best or o['score']>best[o['address']]['score']:
            best[o['address']]=o
    out=list(best.values())
    out.sort(key=lambda x: x['score'], reverse=True)
    run("CALL gds.graph.drop($g,false)", {"g": g})
    return out

# Two ways: 30d hops3 and 14d hops2
A30 = pd.DataFrame(dist_deg(30,3))
A14 = pd.DataFrame(dist_deg(14,2))

# Consensus by averaging normalized ranks
final_list=[]
if not A30.empty and not A14.empty:
    A30 = A30.dropna().drop_duplicates('address')
    A14 = A14.dropna().drop_duplicates('address')
    r30 = {a:i for i,a in enumerate(A30['address'].tolist())}
    r14 = {a:i for i,a in enumerate(A14['address'].tolist())}
    n30 = {a: (r30[a])/max(1,len(A30)-1) for a in r30}
    n14 = {a: (r14[a])/max(1,len(A14)-1) for a in r14}
    all_addrs = set(r30.keys()) | set(r14.keys())
    scored=[]
    for a in all_addrs:
        s = ( (1-n30.get(a,1)) + (1-n14.get(a,1)) )/2.0
        scored.append((a,s))
    scored.sort(key=lambda x: x[1], reverse=True)
    final_list = [a for a,_ in scored[:100]]
elif not A30.empty:
    final_list = A30.head(100)['address'].tolist()
elif not A14.empty:
    final_list = A14.head(100)['address'].tolist()

# Stability of top50

def topn(df, n=50):
    if df is None or df.empty: return set()
    return set(df.head(n)['address'].tolist())

def jacc(a,b):
    if not a and not b: return None
    if not a or not b: return 0.0
    return len(a & b)/len(a | b)

stability = {'A30_vs_A14': jacc(topn(A30), topn(A14))}

print(json.dumps({'addr_label': addr_label, 'reltype': rt, 'time_key': time_key, 'temporal': is_temporal, 'hack_time_utc': hack_time.isoformat()+'Z', 'counts': {'A30': len(A30) if A30 is not None else 0, 'A14': len(A14) if A14 is not None else 0}, 'stability': stability, 'final': final_list}))

import os, sys, json, time
from datetime import datetime, timedelta, timezone
from neo4j import GraphDatabase
import pandas as pd

SRC_ADDR = "0x1db92e2eebc8e0c075a02bea49a2935bcd2dfcf4".lower()
uri=os.getenv("NEO4J_URI"); user=os.getenv("NEO4J_USERNAME"); password=os.getenv("NEO4J_PASSWORD"); database=os.getenv("NEO4J_DATABASE")
if not uri or not user or not password:
    print(json.dumps({"error":"Missing creds"})); sys.exit(0)

driver = GraphDatabase.driver(uri, auth=(user, password))

def run(q,p=None):
    with (driver.session(database=database) if database else driver.session()) as s:
        return [r.data() for r in s.run(q,p or {})]

labels = [r["label"] for r in run("CALL db.labels() YIELD label RETURN label")]
reltypes = [r["relationshipType"] for r in run("CALL db.relationshipTypes() YIELD relationshipType RETURN relationshipType")]
addr_label = next((l for l in labels if l.lower()=="address"), (labels[0] if labels else "Address"))
rt = "TRANSFER" if "TRANSFER" in reltypes else (reltypes[0] if reltypes else None)

src_row = run(f"MATCH (n:`{addr_label}`) WHERE toLower(n.address)=$a RETURN id(n) AS id, n.address AS address", {"a": SRC_ADDR})
if not src_row: print(json.dumps({"error":"src not found"})); sys.exit(0)
src_id = src_row[0]['id']

keys_rows = run(f"MATCH (a:`{addr_label}`)-[r:`{rt}`]->() WHERE id(a)=$id RETURN keys(r) AS ks LIMIT 10", {"id": src_id})
keys=set(); [keys.update(r.get('ks',[])) for r in keys_rows]
time_key = next((k for k in ["blockTimestamp","timestamp","time","ts","block_time","blockNumberTimestamp"] if k in keys), None)

is_temporal=False
hack_time=None
if time_key:
    trow = run(f"MATCH (a:`{addr_label}`)-[r:`{rt}`]->() WHERE id(a)=$id AND r.`{time_key}` IS NOT NULL RETURN r.`{time_key}` AS t ORDER BY r.`{time_key}` ASC LIMIT 1", {"id": src_id})
    if trow:
        tval = trow[0]['t']
        if hasattr(tval,'to_native') or hasattr(tval,'year') or (isinstance(tval,str) and 'T' in tval):
            is_temporal=True
            if isinstance(tval,str): hack_time = datetime.fromisoformat(tval.replace('Z','+00:00')).astimezone(timezone.utc).replace(tzinfo=None)
            else:
                try: hack_time = tval.to_native().replace(tzinfo=None)
                except: hack_time = datetime.utcnow()-timedelta(days=30)
        else:
            try:
                t=int(tval); hack_time = datetime.utcfromtimestamp(t/1000 if t>1e12 else t)
            except: hack_time = datetime.utcnow()-timedelta(days=30)
else:
    hack_time = datetime.utcnow()-timedelta(days=30)


def where_params(days):
    if time_key:
        if is_temporal:
            return f"r.`{time_key}` >= datetime($t0) AND r.`{time_key}` <= datetime($t1)", {"t0": (hack_time).isoformat()+"Z", "t1": (hack_time+timedelta(days=days)).isoformat()+"Z"}
        else:
            t0_ms=int(time.mktime(hack_time.timetuple())*1000); t1_ms=int(time.mktime((hack_time+timedelta(days=days)).timetuple())*1000)
            return f"toInteger(r.`{time_key}`) >= $t0 AND toInteger(r.`{time_key}`) <= $t1", {"t0": t0_ms, "t1": t1_ms}
    else:
        return "true", {}


def reachable_ids(days=30, hops=3):
    w, pm = where_params(days)
    q = f"""
    MATCH (src:`{addr_label}`) WHERE toLower(src.address)=$a
    MATCH p=(src)-[rs:`{rt}`*..{hops}]->(n:`{addr_label}`)
    WHERE ALL(r IN rs WHERE {w})
    UNWIND nodes(p) AS x
    RETURN DISTINCT id(x) AS id
    UNION
    MATCH (src:`{addr_label}`) WHERE toLower(src.address)=$a
    RETURN id(src) AS id
    """.replace("{w}", w)
    params = {"a": SRC_ADDR, **pm}
    rows = run(q, params)
    return [r['id'] for r in rows]


def project(name, ids, days=30):
    try: run("CALL gds.graph.drop($g,false)", {"g": name})
    except Exception: pass
    w, pm = where_params(days)
    params = {"ids": ids, **pm}
    node_q = "UNWIND $ids AS id RETURN DISTINCT id AS id"
    rel_q = f"MATCH (s:`{addr_label}`)-[r:`{rt}`]->(t:`{addr_label}`) WHERE id(s) IN $ids AND id(t) IN $ids AND {w} RETURN id(s) AS source, id(t) AS target"
    run("CALL gds.graph.project.cypher($g,$nq,$rq,$cfg) YIELD graphName RETURN graphName", {"g": name, "nq": node_q, "rq": rel_q, "cfg": {"parameters": params}})


def bfs_deg(days=30, hops=3):
    ids = reachable_ids(days, hops)
    if not ids: return []
    g=f"g_bfs_{days}d_{hops}h"
    project(g, ids, days)
    bfs_rows = run("CALL gds.bfs.stream($g,$c) YIELD sourceNode, nodeIds RETURN sourceNode, nodeIds", {"g": g, "c": {"sourceNode": src_id}})
    deg_rows = run("CALL gds.degree.stream($g,$c) YIELD nodeId, score RETURN nodeId, score", {"g": g, "c": {"orientation": "OUTGOING"}})
    deg_map = {r['nodeId']: r['score'] for r in deg_rows}
    # Extract terminal node and distance
    out=[]
    for r in bfs_rows:
        node_ids = r.get('nodeIds', [])
        if not node_ids: continue
        target = node_ids[-1]
        if target == src_id: continue
        dist = len(node_ids)-1
        # map id to address
        addr_rows = run(f"MATCH (n:`{addr_label}`) WHERE id(n)=$id RETURN n.address AS address", {"id": target})
        address = addr_rows[0]['address'] if addr_rows else None
        if not address: continue
        invd = 1.0/(1.0+min(max(dist,0),10))
        # Normalize degree lazily: will normalize later; for now, use raw
        out.append({"address": address, "dist": dist, "deg": deg_map.get(target,0)})
    # Aggregate by best distance, max deg
    agg={}
    for o in out:
        a=o['address']
        if a not in agg:
            agg[a]={"dist": o['dist'], "deg": o['deg']}
        else:
            if o['dist'] < agg[a]['dist']: agg[a]['dist']=o['dist']
            if o['deg'] > agg[a]['deg']: agg[a]['deg']=o['deg']
    # Compute scores
    if not agg:
        run("CALL gds.graph.drop($g,false)", {"g": g}); return []
    max_deg = max([v['deg'] for v in agg.values()]) if agg else 1
    scored=[]
    for a,v in agg.items():
        invd = 1.0/(1.0+min(max(v['dist'],0),10))
        dgn = (v['deg']/max_deg) if max_deg>0 else 0
        s = 0.7*invd + 0.3*dgn
        scored.append((a,s,v['dist'],v['deg']))
    scored.sort(key=lambda x: x[1], reverse=True)
    res=[{"address": a, "score": s, "dist": d, "deg": gdeg} for a,s,d,gdeg in scored]
    run("CALL gds.graph.drop($g,false)", {"g": g})
    return res

A30 = pd.DataFrame(bfs_deg(30,3))
A14 = pd.DataFrame(bfs_deg(14,2))

# Consensus as before
final_list=[]
if not A30.empty and not A14.empty:
    A30 = A30.dropna().drop_duplicates('address')
    A14 = A14.dropna().drop_duplicates('address')
