    MATCH (n)
    WHERE any(k IN keys(n) WHERE (exists(n[k]) AND (
        toLower(n[k]) = $a OR replace(toLower(n[k]),'0x','') = $a_noprefix
    )))
    RETURN id(n) as id, labels(n) as labels, $a as address, 'UNKNOWN' as label, '' as prop
    LIMIT 3
    """
    victim_matches = run_cypher(q, {"a": addr_lower, "a_noprefix": addr_noprefix})

if not victim_matches:
    out["fatal"] = f"Victim address {victim_addr_input} not found in any node properties."
    print(json.dumps(out))
    raise SystemExit

preferred_label_order = ["Address", "Wallet", "EthereumAddress", "Account"]
chosen = None
for pref in preferred_label_order:
    for r in victim_matches:
        if pref in r.get('labels', []) or r.get('label') == pref:
            chosen = r
            break
    if chosen:
        break
if not chosen:
    chosen = victim_matches[0]

victim_node_id = chosen['id']
victim_addr_canonical = (chosen.get('address') or addr_lower).lower()
victim_label = chosen.get('label') if chosen.get('label') != 'UNKNOWN' else (chosen.get('labels') or [None])[0]

# Determine address property to use
address_prop = None
addr_props_try_list = ["address", "addr", "hash", "id", "addressLower", "address_lower"] + list(prop_candidates_by_label.get(victim_label, []))
for p in addr_props_try_list:
    try:
        test = run_cypher(f"MATCH (n:{victim_label}) WHERE id(n)=$id RETURN n.{p} as v", {"id": victim_node_id})
        if test and test[0]['v'] is not None:
            address_prop = p
            break
    except Exception:
        continue

out["victim"] = {
    "node_id": victim_node_id,
    "label": victim_label,
    "address_prop": address_prop,
    "address": victim_addr_canonical
}

# Relationship types out of victim
rel_types_rows = run_cypher("MATCH (v)-[r]->() WHERE id(v)=$id RETURN type(r) as type, count(*) as c ORDER BY c DESC", {"id": victim_node_id})
rel_types = [r['type'] for r in rel_types_rows]

candidate_rel_types = []
for rt in rel_types:
    keys_rows = run_cypher(f"MATCH (v)-[r:`{rt}`]->() WHERE id(v)=$id WITH r LIMIT 100 UNWIND keys(r) as k RETURN k, count(*) as c ORDER BY c DESC", {"id": victim_node_id})
    keys = [row['k'] for row in keys_rows]
    time_keys = [k for k in keys if any(s in k.lower() for s in ["time", "timestamp", "blocktime", "block", "ts"])]
    value_keys = [k for k in keys if any(s in k.lower() for s in ["value", "amount", "wei", "eth"])]
    score = 0
    if any(s in rt.lower() for s in ["transfer", "send", "tx", "eth"]):
        score += 2
    if time_keys:
        score += 1
    if value_keys:
        score += 2
    if score >= 2:
        candidate_rel_types.append({"type": rt, "time_keys": time_keys, "value_keys": value_keys, "score": score})

if not candidate_rel_types and rel_types:
    candidate_rel_types = [{"type": rel_types[0], "time_keys": [], "value_keys": [], "score": 1}]

candidate_rel_types.sort(key=lambda x: x['score'], reverse=True)
rel_type = candidate_rel_types[0]['type']

# Determine time/value properties
probe_keys_rows = run_cypher(f"MATCH (v)-[r:`{rel_type}`]->() WHERE id(v)=$id WITH r LIMIT 200 UNWIND keys(r) as k RETURN k, count(*) as c ORDER BY c DESC", {"id": victim_node_id})
probe_keys = [row['k'] for row in probe_keys_rows]

time_candidates_order = ["timestamp", "blockTimestamp", "block_time", "blockTime", "time", "ts", "blockNumber", "block_number"]
value_candidates_order = ["value", "amount", "valueWei", "value_wei", "wei", "amountWei", "eth"]

time_prop = None
for k in time_candidates_order + [k for k in probe_keys if k not in time_candidates_order]:
    if k in probe_keys:
        try:
            test = run_cypher(f"MATCH (v)-[r:`{rel_type}`]->() WHERE id(v)=$id AND exists(r.{k}) RETURN toFloat(r.{k}) as v LIMIT 1", {"id": victim_node_id})
            if test and test[0]['v'] is not None:
                time_prop = k
                break
        except Exception:
            continue

value_prop = None
for k in value_candidates_order + [k for k in probe_keys if k not in value_candidates_order]:
    if k in probe_keys:
        try:
            test = run_cypher(f"MATCH (v)-[r:`{rel_type}`]->() WHERE id(v)=$id AND exists(r.{k}) RETURN toFloat(r.{k}) as v ORDER BY v DESC LIMIT 1", {"id": victim_node_id})
            if test and test[0]['v'] is not None and float(test[0]['v']) > 0:
                value_prop = k
                break
        except Exception:
            continue

out["relationship"] = {"type": rel_type, "time_prop": time_prop, "value_prop": value_prop}

if time_prop is None or value_prop is None:
    out["fatal"] = f"Could not determine time/value properties on relationship type {rel_type}. Keys seen: {probe_keys}"
    print(json.dumps(out))
    raise SystemExit

# Determine t0, tmax
stats = run_cypher(
    f"""
    MATCH (v)-[r:`{rel_type}`]->(n)
    WHERE id(v)=$id AND exists(r.{time_prop}) AND exists(r.{value_prop})
    RETURN min(toFloat(r.{time_prop})) as t0,
           max(toFloat(r.{time_prop})) as tmax,
           count(r) as cnt,
           sum(toFloat(r.{value_prop})) as total_value
    """,
    {"id": victim_node_id}
)
if not stats:
    out["fatal"] = "No outgoing transfers from victim."
    print(json.dumps(out))
    raise SystemExit

stat = stats[0]
t0 = float(stat['t0'])
tmax = float(stat['tmax'])
sec_like = tmax < 10**12
win1_hours = 72
win2_hours = 168
win1_end = t0 + win1_hours * 3600.0 * (1.0 if sec_like else 1000.0)
win2_end = t0 + win2_hours * 3600.0 * (1.0 if sec_like else 1000.0)

# BFS collect

def bfs_collect(max_hops:int, start:float, end:float):
    visited = set([victim_node_id])
    frontier = {victim_node_id}
    edges = []
    for h in range(max_hops):
        if not frontier:
            break
        q = f"""
        MATCH (a)-[r:`{rel_type}`]->(b)
        WHERE id(a) IN $frontier AND exists(r.{time_prop}) AND exists(r.{value_prop})
          AND toFloat(r.{time_prop}) >= $start AND toFloat(r.{time_prop}) <= $end
        RETURN id(a) as src, id(b) as dst, toFloat(r.{value_prop}) as weight, toFloat(r.{time_prop}) as time
        """
        rows = run_cypher(q, {"frontier": list(frontier), "start": start, "end": end})
        next_frontier = set()
        for r in rows:
            src = r['src']; dst = r['dst']
            try:
                w = float(r['weight'])
            except Exception:
                continue
            try:
                tt = float(r['time'])
            except Exception:
                continue
            edges.append({"src": src, "dst": dst, "weight": w, "time": tt})
            if dst not in visited:
                next_frontier.add(dst)
                visited.add(dst)
        frontier = next_frontier
    node_ids = list(visited)
    edges_df = pd.DataFrame(edges)
    return node_ids, edges_df

node_ids_w1, edges_w1 = bfs_collect(3, t0, win1_end)
node_ids_w2, edges_w2 = bfs_collect(3, t0, win2_end)
if edges_w1.empty and edges_w2.empty:
    node_ids_w1, edges_w1 = bfs_collect(4, t0, win1_end)
    node_ids_w2, edges_w2 = bfs_collect(4, t0, win2_end)

node_ids_union = list(set(node_ids_w1) | set(node_ids_w2))
addr_map = {}
if node_ids_union:
    addr_props_try_list = [p for p in [address_prop, "address", "addr", "hash", "id", "addressLower", "address_lower"] if p]
    got = False
    for p in addr_props_try_list:
        try:
            rows = run_cypher(f"MATCH (n) WHERE id(n) IN $ids RETURN id(n) as id, n.{p} as a", {"ids": node_ids_union})
            if rows:
                addr_map = {r['id']: (r['a'] if isinstance(r['a'], str) else (str(r['a']) if r['a'] is not None else None)) for r in rows}
                got = True
                break
        except Exception as e:
            continue

thr_w1 = float(pd.Series(edges_w1['weight']).quantile(0.2)) if not edges_w1.empty else None
thr_w2 = float(pd.Series(edges_w2['weight']).quantile(0.2)) if not edges_w2.empty else None

# GDS helpers

def gds_drop_if_exists(name:str):
    try:
        res = gds.graph.exists(name)
        if isinstance(res, pd.DataFrame):
            exists_flag = bool(res.iloc[0]['exists'])
        else:
            exists_flag = bool(res['exists'])
        if exists_flag:
            gds.graph.drop(name)
    except Exception:
        try:
            gds.graph.drop(name)
        except Exception:
            pass


def project_graph(name:str, node_ids, edges_df, min_value=None):
    gds_drop_if_exists(name)
    if edges_df is None or edges_df.empty:
        return False
    ef = edges_df.copy()
    if min_value is not None:
        ef = ef[ef['weight'] >= min_value]
    if ef.empty:
        return False
    node_ids_unique = sorted(list(set(node_ids)))
    edges_param = [
        {"source": int(row.src), "target": int(row.dst), "weight": float(row.weight), "time": float(row.time)}
        for row in ef.itertuples(index=False)
    ]
    params = {"nodeIds": node_ids_unique, "edges": edges_param}
    node_query = "UNWIND $nodeIds AS id RETURN id AS id"
    rel_query = "UNWIND $edges AS r RETURN r.source AS source, r.target AS target, r.weight AS weight, r.time AS time"
    try:
        gds.graph.project.cypher(name, node_query, rel_query, parameters=params, relationshipProperties=["weight", "time"])
        return True
    except Exception as e:
        out["errors"].append(f"Graph projection {name} failed: {e}")
        return False


def run_ppr(name:str, source_node_ids, weight_property='weight', damping_factor=0.85, max_iterations=50):
    try:
        config = {
            "sourceNodes": source_node_ids,
            "dampingFactor": damping_factor,
            "maxIterations": max_iterations,
            "relationshipWeightProperty": weight_property,
            "direction": "NATURAL"
        }
        df = gds.pageRank.stream(name, config)
    except Exception:
        try:
            config = {
                "sourceNodes": source_node_ids,
                "dampingFactor": damping_factor,
                "maxIterations": max_iterations,
                "weightProperty": weight_property,
                "direction": "NATURAL"
            }
            df = gds.pageRank.stream(name, config)
        except Exception as e2:
            out["errors"].append(f"PPR failed on {name}: {e2}")
            return pd.DataFrame()
    return df


def run_betweenness(name:str):
    try:
        df = gds.betweenness.stream(name, {'direction': 'NATURAL'})
    except Exception as e:
        out["errors"].append(f"Betweenness failed on {name}: {e}")
        return pd.DataFrame()
    return df

# Project graphs
created_A = project_graph("heist_A", node_ids_w1, edges_w1, min_value=thr_w1)
created_A2 = project_graph("heist_A2", node_ids_w1, edges_w1, min_value=None)
created_B = project_graph("heist_B", node_ids_w2, edges_w2, min_value=thr_w2)

results = {}
if created_A:
    results['ppr_A'] = run_ppr("heist_A", [victim_node_id])
    results['btw_A'] = run_betweenness("heist_A")
if created_A2:
    results['ppr_A2'] = run_ppr("heist_A2", [victim_node_id])
if created_B:
    results['ppr_B'] = run_ppr("heist_B", [victim_node_id])
    results['btw_B'] = run_betweenness("heist_B")

# Map to addresses

def enrich_with_address(df: pd.DataFrame):
    if df is None or df.empty:
        return df
    dff = df.copy()
    dff['address'] = dff['nodeId'].map(addr_map)
    dff = dff[dff['address'].notna()]
    dff = dff[dff['address'].str.lower() != victim_addr_canonical]
    return dff

for k in list(results.keys()):
    results[k] = enrich_with_address(results[k])

method1_variants = []
if 'ppr_A' in results and not results['ppr_A'].empty:
    method1_variants.append(("ppr_A", results['ppr_A'].sort_values('score', ascending=False)))
if 'ppr_A2' in results and not results['ppr_A2'].empty:
    method1_variants.append(("ppr_A2", results['ppr_A2'].sort_values('score', ascending=False)))
if 'ppr_B' in results and not results['ppr_B'].empty:
    method1_variants.append(("ppr_B", results['ppr_B'].sort_values('score', ascending=False)))

method2_variants = []
if 'btw_A' in results and not results['btw_A'].empty:
    method2_variants.append(("btw_A", results['btw_A'].sort_values('score', ascending=False)))
if 'btw_B' in results and not results['btw_B'].empty:
    method2_variants.append(("btw_B", results['btw_B'].sort_values('score', ascending=False)))

stability = {}
for name, df in method1_variants:
    for a in df.head(200)['address'].tolist():
        stability[a] = stability.get(a, 0) + 1

final_ppr = None
if method1_variants:
    merged = None
    for name, df in method1_variants:
        d = df[['address', 'score']].copy()
        m = d['score'].max()
        d['score_norm'] = d['score'] / m if m and m > 0 else 0.0
        d = d.groupby('address', as_index=False)['score_norm'].max()
        d = d.rename(columns={'score_norm': f'score_{name}'})
        merged = d if merged is None else pd.merge(merged, d, on='address', how='outer')
    for col in merged.columns:
        if col.startswith('score_'):
            merged[col] = merged[col].fillna(0.0)
    score_cols = [c for c in merged.columns if c.startswith('score_')]
    merged['score_combined'] = merged[score_cols].mean(axis=1)
    merged['stability'] = merged['address'].map(lambda a: stability.get(a, 0))
    final_ppr = merged.sort_values(['score_combined', 'stability'], ascending=[False, False])

final_btw = None
if method2_variants:
    merged2 = None
    for name, df in method2_variants:
        d = df[['address', 'score']].copy()
        m = d['score'].max()
        d['score_norm'] = d['score'] / m if m and m > 0 else 0.0
        d = d.groupby('address', as_index=False)['score_norm'].max()
        d = d.rename(columns={'score_norm': f'score_{name}'})
        merged2 = d if merged2 is None else pd.merge(merged2, d, on='address', how='outer')
    for col in merged2.columns:
        if col.startswith('score_'):
            merged2[col] = merged2[col].fillna(0.0)
    score_cols2 = [c for c in merged2.columns if c.startswith('score_')]
    merged2['score_combined'] = merged2[score_cols2].mean(axis=1)
    final_btw = merged2.sort_values(['score_combined'], ascending=[False])

agreed = []
if final_ppr is not None and final_btw is not None:
    set_ppr = set(final_ppr.head(200)['address'].tolist())
    set_btw = set(final_btw.head(200)['address'].tolist())
    agreed = list(set_ppr & set_btw)

btw_score_map = {}
if final_btw is not None:
    for row in final_btw.itertuples(index=False):
        btw_score_map[row.address] = float(row.score_combined)

final_ranked = []
if final_ppr is not None:
    df = final_ppr.copy()
    df['btw'] = df['address'].map(lambda a: btw_score_map.get(a, 0.0))
    df['composite'] = 0.7 * df['score_combined'] + 0.3 * df['btw']
    max_stab = df['stability'].max() if 'stability' in df.columns else 1
    if max_stab and max_stab > 0:
        df['composite'] = df['composite'] * (0.5 + 0.5 * (df['stability'] / max_stab))
    df = df.sort_values(['composite'], ascending=False)
    final_ranked = df['address'].tolist()

final_top100 = [a for a in final_ranked if isinstance(a, str)][:100]

# Jaccard for PPR variants
ppr_sets = {name: set(df.head(100)['address'].tolist()) for name, df in method1_variants}
ppr_pairwise_jaccard = {}
keys = list(ppr_sets.keys())
for i in range(len(keys)):
    for j in range(i+1, len(keys)):
        a = ppr_sets[keys[i]]; b = ppr_sets[keys[j]]
        denom = len(a | b) if (a or b) else 1
        jac = len(a & b) / denom if denom else 0.0
        ppr_pairwise_jaccard[f"{keys[i]}__{keys[j]}"] = jac

# least stable among final_top100
least_stable = []
if final_ppr is not None and not final_ppr.empty and final_top100:
    stab_counts = final_ppr.set_index('address')['stability'].to_dict()
    ss = sorted([(a, stab_counts.get(a, 0)) for a in final_top100], key=lambda x: (x[1], final_top100.index(x[0])))
    least_stable = [a for a, s in ss[:10]]

# Also compute size of immediate recipients during first 24h for context
win0_end = t0 + 24 * 3600.0 * (1.0 if sec_like else 1000.0)
direct_recips_rows = run_cypher(
    f"""
    MATCH (v)-[r:`{rel_type}`]->(n)
    WHERE id(v)=$id AND toFloat(r.{time_prop}) >= $t0 AND toFloat(r.{time_prop}) <= $t1
    RETURN count(DISTINCT n) as direct_count, sum(toFloat(r.{value_prop})) as direct_value
    """,
    {"id": victim_node_id, "t0": t0, "t1": win0_end}
)
direct_info = direct_recips_rows[0] if direct_recips_rows else {"direct_count": 0, "direct_value": 0}

out.update({
    "final_top100": final_top100,
    "agreed_count": len(agreed),
    "graphs_created": {"A": bool(created_A), "A2": bool(created_A2), "B": bool(created_B)},
    "node_counts": {"A": len(node_ids_w1), "B": len(node_ids_w2)},
    "edge_counts": {"A": int(0 if edges_w1 is None else len(edges_w1)), "B": int(0 if edges_w2 is None else len(edges_w2))},
    "thresholds": {"A": thr_w1, "B": thr_w2},
    "ppr_pairwise_jaccard": ppr_pairwise_jaccard,
    "least_stable": least_stable,
    "direct_24h": {"count": int(direct_info.get('direct_count', 0) or 0), "value_sum": float(direct_info.get('direct_value', 0) or 0.0)},
    "victim": out.get('victim'),
    "relationship": out.get('relationship')
})

print(json.dumps(out))

import os
