# Project in-memory GDS graphs via Cypher

def gds_drop_if_exists(name):
    try:
        run_cypher("CALL gds.graph.drop($name, false)", {"name": name})
    except Exception:
        pass


def project_graph(name, node_ids, edges_df, min_value=None):
    if edges_df is None or edges_df.empty:
        return False
    ef = edges_df.copy()
    if min_value is not None:
        ef = ef[ef['weight'] >= min_value]
    if ef.empty:
        return False
    gds_drop_if_exists(name)
    node_ids_unique = sorted(list(set(node_ids)))
    edges_param = [
        {"source": int(row.src), "target": int(row.dst), "weight": float(row.weight), "time": float(row.time)}
        for row in ef.itertuples(index=False)
    ]
    params = {"nodeIds": node_ids_unique, "edges": edges_param}
    node_query = "UNWIND $nodeIds AS id RETURN id AS id"
    rel_query = "UNWIND $edges AS r RETURN r.source AS source, r.target AS target, r.weight AS weight, r.time AS time"
    try:
        run_cypher(
            "CALL gds.graph.project.cypher($name, $nodeQuery, $relQuery, $config)",
            {
                "name": name,
                "nodeQuery": node_query,
                "relQuery": rel_query,
                "config": {"parameters": params, "relationshipProperties": ["weight", "time"]}
            }
        )
        return True
    except Exception as e:
        out['errors'].append(f"Graph projection {name} failed: {e}")
        return False

# Algorithm runners via Cypher

def run_ppr(name, source_node_ids, weight_property='weight', damping_factor=0.85, max_iterations=50):
    try:
        df_rows = run_cypher(
            """
            CALL gds.pageRank.stream($name, {
              sourceNodes: $sources,
              dampingFactor: $df,
              maxIterations: $mi,
              relationshipWeightProperty: $wp,
              direction: 'NATURAL'
            }) YIELD nodeId, score
            RETURN nodeId, score
            """,
            {"name": name, "sources": source_node_ids, "df": damping_factor, "mi": max_iterations, "wp": weight_property}
        )
        return pd.DataFrame(df_rows)
    except Exception as e:
        # try old param name
        try:
            df_rows = run_cypher(
                """
                CALL gds.pageRank.stream($name, {
                  sourceNodes: $sources,
                  dampingFactor: $df,
                  maxIterations: $mi,
                  weightProperty: $wp,
                  direction: 'NATURAL'
                }) YIELD nodeId, score
                RETURN nodeId, score
                """,
                {"name": name, "sources": source_node_ids, "df": damping_factor, "mi": max_iterations, "wp": weight_property}
            )
            return pd.DataFrame(df_rows)
        except Exception as e2:
            out['errors'].append(f"PPR failed on {name}: {e2}")
            return pd.DataFrame()


def run_betweenness(name):
    try:
        df_rows = run_cypher(
            """
            CALL gds.betweenness.stream($name, {direction: 'NATURAL'})
            YIELD nodeId, score
            RETURN nodeId, score
            """,
            {"name": name}
        )
        return pd.DataFrame(df_rows)
    except Exception as e:
        out['errors'].append(f"Betweenness failed on {name}: {e}")
        return pd.DataFrame()

