import os, json
from neo4j import GraphDatabase
import pandas as pd

NEO4J_URI = os.getenv("NEO4J_URI", "bolt://localhost:7687")
NEO4J_USERNAME = os.getenv("NEO4J_USERNAME", "neo4j")
NEO4J_PASSWORD = os.getenv("NEO4J_PASSWORD", "neo4j")
NEO4J_DATABASE = os.getenv("NEO4J_DATABASE")

# We'll re-run the previous PPR+FLOW computation quickly and then extract the artifacts we need for the answer
victim_addr = "0x1db92e2eebc8e0c075a02bea49a2935bcd2dfcf4"

driver = GraphDatabase.driver(NEO4J_URI, auth=(NEO4J_USERNAME, NEO4J_PASSWORD))
session_kwargs = {}
if NEO4J_DATABASE:
    session_kwargs['database'] = NEO4J_DATABASE


def run(q, p=None):
    with driver.session(**session_kwargs) as s:
        return s.run(q, p or {}).data()

vid = run("MATCH (n:Address {address: $a}) RETURN id(n) as id", {"a": victim_addr})[0]['id']
rel_type = run("MATCH (v)-[r]->() WHERE id(v)=$id RETURN type(r) as t, count(*) as c ORDER BY c DESC LIMIT 1", {"id": vid})[0]['t']
keys = run(f"MATCH (v)-[r:`{rel_type}`]->() WHERE id(v)=$id WITH r LIMIT 1 RETURN keys(r) as k", {"id": vid})[0]['k']
value_prop = 'amount' if 'amount' in keys else ('value' if 'value' in keys else keys[0])
time_prop = 'block_number' if 'block_number' in keys else ('timestamp' if 'timestamp' in keys else keys[0])

stat = run(f"MATCH (v)-[r:`{rel_type}`]->() WHERE id(v)=$id RETURN min(toFloat(r.{time_prop})) as t0", {"id": vid})[0]
t0 = float(stat['t0'])

is_block = 'block' in time_prop.lower()
span72 = 72*3600/12 if is_block else 72*3600.0
span168 = 168*3600/12 if is_block else 168*3600.0

# BFS
def bfs_edges(max_hops, start, end):
    visited = set([vid]); frontier = {vid}; edges = []
    for _ in range(max_hops):
        if not frontier: break
        rows = run(f"""
            MATCH (a)-[r:`{rel_type}`]->(b)
            WHERE id(a) IN $frontier AND r.{time_prop} IS NOT NULL AND r.{value_prop} IS NOT NULL
              AND toFloat(r.{time_prop}) >= $start AND toFloat(r.{time_prop}) <= $end
            RETURN id(a) as src, id(b) as dst, toFloat(r.{value_prop}) as w, toFloat(r.{time_prop}) as t
        """, {"frontier": list(frontier), "start": start, "end": end})
        next_frontier = set()
        for r in rows:
            edges.append((r['src'], r['dst'], float(r['w']), float(r['t'])))
            if r['dst'] not in visited: next_frontier.add(r['dst']); visited.add(r['dst'])
        frontier = next_frontier
    return list(visited), pd.DataFrame(edges, columns=['src','dst','w','t'])

nodes72, edges72 = bfs_edges(3, t0, t0+span72)
nodes168, edges168 = bfs_edges(3, t0, t0+span168)

# Address map
ids_union = list(set(nodes72) | set(nodes168))
addr_rows = run("MATCH (n) WHERE id(n) IN $ids RETURN id(n) as id, n.address as a", {"ids": ids_union})
addr_map = {r['id']: r['a'] for r in addr_rows if r['a']}

# Helpers
import numpy as np

def ppr_scores(edges: pd.DataFrame, alpha=0.15, max_iter=50):
    if edges.empty: return {}
    out_sum = edges.groupby('src')['w'].sum().to_dict()
    P = {}
    for row in edges.itertuples(index=False):
        s,d,w,t = row
        if out_sum.get(s,0)>0:
            P.setdefault(s, []).append((d, w/out_sum[s]))
    nodes = set(edges['src']).union(set(edges['dst'])); nodes.add(vid); nodes=list(nodes); idx={n:i for i,n in enumerate(nodes)}
    n=len(nodes); r=np.zeros(n); r[idx[vid]]=1.0; p=r.copy()
    for _ in range(max_iter):
        p_new = alpha*r + (1-alpha)*mul_Pt(p, nodes, P, idx)
        if np.linalg.norm(p_new-p,1) < 1e-9: p=p_new; break
        p=p_new
    return {nodes[i]: float(p[i]) for i in range(n)}

def mul_Pt(p, nodes, P, idx):
    res=np.zeros_like(p)
    for s, neighs in P.items():
        pv = p[idx[s]]
        if pv==0: continue
        for d,pr in neighs:
            res[idx[d]] += pv*pr
    return res


def kstep_flow(edges: pd.DataFrame, K=3):
    if edges.empty: return {}
    out_sum = edges.groupby('src')['w'].sum().to_dict(); P={}
    for row in edges.itertuples(index=False):
        s,d,w,t=row
        if out_sum.get(s,0)>0: P.setdefault(s,[]).append((d,w/out_sum[s]))
    nodes=set(edges['src']).union(set(edges['dst'])); nodes.add(vid); nodes=list(nodes); idx={n:i for i,n in enumerate(nodes)}
    n=len(nodes); mass=np.zeros(n); mass[idx[vid]]=1.0; total=np.zeros(n)
    for _ in range(K):
        nm=np.zeros(n)
        for s,neighs in P.items():
            mv=mass[idx[s]]; 
            if mv==0: continue
            for d,pr in neighs:
                nm[idx[d]] += mv*pr
        total += nm; mass=nm
    return {nodes[i]: float(total[i]) for i in range(n)}

# Build variant rankings
var_dfs = {}
if not edges72.empty:
    thr72 = float(edges72['w'].quantile(0.2))
    e72 = edges72[edges72['w']>=thr72]
    sc_ppr_72 = ppr_scores(e72)
    df1 = pd.DataFrame([{'address': addr_map.get(nid), 'score':sc} for nid,sc in sc_ppr_72.items() if nid!=vid and addr_map.get(nid)]).sort_values('score', ascending=False)
    var_dfs['PPR_72h_q20'] = df1
    sc_flow_72 = kstep_flow(e72, K=3)
    df3 = pd.DataFrame([{'address': addr_map.get(nid), 'score':sc} for nid,sc in sc_flow_72.items() if nid!=vid and addr_map.get(nid)]).sort_values('score', ascending=False)
    var_dfs['FLOW3_72h_q20'] = df3

if not edges168.empty:
    thr168 = float(edges168['w'].quantile(0.2))
    e168 = edges168[edges168['w']>=thr168]
    sc_ppr_168 = ppr_scores(e168)
    df2 = pd.DataFrame([{'address': addr_map.get(nid), 'score':sc} for nid,sc in sc_ppr_168.items() if nid!=vid and addr_map.get(nid)]).sort_values('score', ascending=False)
    var_dfs['PPR_168h_q20'] = df2
    sc_flow_168 = kstep_flow(e168, K=3)
    df4 = pd.DataFrame([{'address': addr_map.get(nid), 'score':sc} for nid,sc in sc_flow_168.items() if nid!=vid and addr_map.get(nid)]).sort_values('score', ascending=False)
    var_dfs['FLOW3_168h_q20'] = df4

# Stability across variants
all_addrs = set()
for df in var_dfs.values(): all_addrs |= set(df.head(200)['address'].tolist())
stability = {a:0 for a in all_addrs}
for df in var_dfs.values():
    for a in df.head(200)['address'].tolist(): stability[a]+=1

# Combine
combined=None
for name,df in var_dfs.items():
    d=df.copy(); m=d['score'].max() or 1.0; d['score_norm']=d['score']/m; d=d[['address','score_norm']].groupby('address',as_index=False)['score_norm'].max().rename(columns={'score_norm':f'score_{name}'})
    combined = d if combined is None else pd.merge(combined, d, on='address', how='outer')

if combined is not None:
    for c in combined.columns:
        if c.startswith('score_'): combined[c]=combined[c].fillna(0.0)
    score_cols=[c for c in combined.columns if c.startswith('score_')]
    combined['score_combined']=combined[score_cols].mean(axis=1)
    combined['stability']=combined['address'].map(lambda a: stability.get(a,0))
    combined=combined.sort_values(['score_combined','stability'],ascending=[False,False])
    final_top100=combined.head(100)['address'].tolist()
else:
    final_top100=[]

# Also compute method-specific top lists for comparison
ppr_top = var_dfs.get('PPR_72h_q20', pd.DataFrame()).head(100)['address'].tolist() if 'PPR_72h_q20' in var_dfs else []
flow_top = var_dfs.get('FLOW3_72h_q20', pd.DataFrame()).head(100)['address'].tolist() if 'FLOW3_72h_q20' in var_dfs else []
overlap = len(set(ppr_top) & set(flow_top))

# Least stable: those in final list with lowest stability
least_stable = sorted([(a, stability.get(a, 0)) for a in final_top100], key=lambda x: x[1])[:10]

print(json.dumps({
    'rel_type': rel_type,
    'value_prop': value_prop,
    'time_prop': time_prop,
    'edges72': len(edges72), 'edges168': len(edges168),
    'variants': list(var_dfs.keys()),
    'overlap_ppr_flow_72': overlap,
    'final_top100': final_top100,
    'least_stable': least_stable[:10],
    'ppr_top10': ppr_top[:10],
    'flow_top10': flow_top[:10]
}))

