n_relaxed, m_relaxed = project_graph(graph_relaxed, relaxed_ids, start_relaxed, end_relaxed, min_amt_relaxed)

out["debug"]["strictGraph"] = {"nodes": n_strict, "rels": m_strict}
out["debug"]["relaxedGraph"] = {"nodes": n_relaxed, "rels": m_relaxed}

# Utility: map nodeIds to addresses

def map_node_ids_to_addresses(node_ids):
    if not node_ids:
        return {}
    chunks = [node_ids[i:i+1000] for i in range(0, len(node_ids), 1000)]
    mp = {}
    for ch in chunks:
        q = """
        UNWIND $ids AS id
        MATCH (n) WHERE id(n) = id
        RETURN id(n) AS id, coalesce(n.address, n.hash, n.id, toString(id(n))) AS address
        """
        df = run_cypher(q, {"ids": ch})
        for _, row in df.iterrows():
            mp[int(row["id"])] = row["address"]
    return mp

# Algorithms

def page_rank_scores(graph_name):
    cfg = {"maxIterations": 40, "dampingFactor": 0.85}
    try:
        cfg_p = dict(cfg)
        cfg_p["sourceNodes"] = [addr_node_id]
        if amount_prop:
            cfg_p["relationshipWeightProperty"] = "amount"
        q = "CALL gds.pageRank.stream($g, $cfg) YIELD nodeId, score RETURN nodeId, score"
        df = run_cypher(q, {"g": graph_name, "cfg": cfg_p})
        if "nodeId" not in df.columns:
            return pd.DataFrame(columns=["nodeId","score"])
        return df
    except Exception:
        cfg2 = dict(cfg)
        if amount_prop:
            cfg2["relationshipWeightProperty"] = "amount"
        q = "CALL gds.pageRank.stream($g, $cfg) YIELD nodeId, score RETURN nodeId, score"
        df = run_cypher(q, {"g": graph_name, "cfg": cfg2})
        if "nodeId" not in df.columns:
            return pd.DataFrame(columns=["nodeId","score"])
        return df


def bfs_distances(graph_name, max_depth=6):
    try:
        q = "CALL gds.beta.bfs.stream($g, {sourceNode: $sid, maxDepth: $md}) YIELD nodeId, depth RETURN nodeId, depth"
        df = run_cypher(q, {"g": graph_name, "sid": addr_node_id, "md": max_depth})
        if "nodeId" not in df.columns:
            return pd.DataFrame(columns=["nodeId","depth"])
        return df
    except Exception:
        return pd.DataFrame(columns=["nodeId","depth"])


def degree_scores(graph_name, orientation="OUTGOING"):
    try:
        q = "CALL gds.degree.stream($g, {orientation: $ori}) YIELD nodeId, score RETURN nodeId, score"
        df = run_cypher(q, {"g": graph_name, "ori": orientation})
        if "nodeId" not in df.columns:
            return pd.DataFrame(columns=["nodeId","score"])
        return df
    except Exception:
        return pd.DataFrame(columns=["nodeId","score"])


def betweenness_scores(graph_name):
    try:
        q = "CALL gds.betweenness.stream($g) YIELD nodeId, score RETURN nodeId, score"
        df = run_cypher(q, {"g": graph_name})
        if "nodeId" not in df.columns:
            return pd.DataFrame(columns=["nodeId","score"])
        return df
    except Exception:
        try:
            q = "CALL gds.betweenness.sampled.stream($g, {probability: 0.5, trials: 8}) YIELD nodeId, score RETURN nodeId, score"
            df = run_cypher(q, {"g": graph_name})
            if "nodeId" not in df.columns:
                return pd.DataFrame(columns=["nodeId","score"])
            return df
        except Exception:
            return pd.DataFrame(columns=["nodeId","score"])

# Compute metrics per graph
metrics = {}
for name, gname in [("strict", graph_strict), ("relaxed", graph_relaxed)]:
    if name == "strict" and (n_strict == 0 or m_strict == 0):
        metrics[name] = {k: pd.DataFrame() for k in ["ppr","bet","bfs","deg_out","deg_in"]}
        continue
    if name == "relaxed" and (n_relaxed == 0 or m_relaxed == 0):
        metrics[name] = {k: pd.DataFrame() for k in ["ppr","bet","bfs","deg_out","deg_in"]}
        continue
    ppr = page_rank_scores(gname)
    bet = betweenness_scores(gname)
    bfs = bfs_distances(gname, max_depth=6 if name=="strict" else 7)
    deg_out = degree_scores(gname, orientation="OUTGOING")
    deg_in = degree_scores(gname, orientation="INCOMING")
    metrics[name] = {"ppr": ppr, "bet": bet, "bfs": bfs, "deg_out": deg_out, "deg_in": deg_in}

# Normalize helper
def normalize_series(s):
    if s is None or len(s) == 0:
        return s
    s = s.astype(float)
    mx = s.max()
    if not pd.notna(mx) or mx == 0:
        return s.fillna(0.0)
    return s.fillna(0.0) / mx

# Prepare merged result frames
results = {}
for name in ["strict", "relaxed"]:
    metr = metrics.get(name, {})
    ppr = metr.get("ppr", pd.DataFrame(columns=["nodeId","score"]))
    bet = metr.get("bet", pd.DataFrame(columns=["nodeId","score"]))
    bfs = metr.get("bfs", pd.DataFrame(columns=["nodeId","depth"]))
    deg_out = metr.get("deg_out", pd.DataFrame(columns=["nodeId","score"]))
    deg_in = metr.get("deg_in", pd.DataFrame(columns=["nodeId","score"]))

    # Ensure expected columns exist
    if "nodeId" not in ppr.columns:
        ppr = pd.DataFrame(columns=["nodeId","score"])
    if "nodeId" not in bet.columns:
        bet = pd.DataFrame(columns=["nodeId","score"])
    if "nodeId" not in bfs.columns:
        bfs = pd.DataFrame(columns=["nodeId","depth"])
    if "nodeId" not in deg_out.columns:
        deg_out = pd.DataFrame(columns=["nodeId","score"])
    if "nodeId" not in deg_in.columns:
        deg_in = pd.DataFrame(columns=["nodeId","score"])

    df = pd.merge(ppr, bet, on="nodeId", how="outer", suffixes=("_ppr","_bet"))
    df = pd.merge(df, bfs, on="nodeId", how="left")
    df = pd.merge(df, deg_out.rename(columns={"score":"outdeg"}), on="nodeId", how="left")
    df = pd.merge(df, deg_in.rename(columns={"score":"indeg"}), on="nodeId", how="left")

    ids = df["nodeId"].dropna().astype(int).tolist()
    id2addr = map_node_ids_to_addresses(ids)
    df["address"] = df["nodeId"].map(lambda x: id2addr.get(int(x), None) if pd.notna(x) else None)

    if "score_ppr" in df.columns:
        df["ppr_n"] = normalize_series(df["score_ppr"]) 
    else:
        df["ppr_n"] = 0.0
    if "score_bet" in df.columns:
        df["bet_n"] = normalize_series(df["score_bet"]) 
    else:
        df["bet_n"] = 0.0

    df["outdeg"] = df["outdeg"].fillna(0)
    df["indeg"] = df["indeg"].fillna(0)
    df["outdeg_n"] = normalize_series(df["outdeg"]) 
    df["indeg_n"] = normalize_series(df["indeg"]) 
    df["hub_n"] = (df["outdeg_n"].fillna(0) + df["indeg_n"].fillna(0))/2.0

    if "depth" in df.columns:
        df["depth"] = df["depth"].fillna(99)
        df["dist_w"] = df["depth"].apply(lambda d: math.exp(-float(d)/3.0) if d is not None and d != 99 else 0.0)
    else:
        df["dist_w"] = 0.0

    w_ppr = 1.0 if name == "strict" else 0.7
    w_bet = 0.6 if name == "strict" else 0.4
    w_dist = 0.5 if name == "strict" else 0.3
    w_hub = 0.4 if name == "strict" else 0.3

    df["score_comb"] = w_ppr * df["ppr_n"].fillna(0) + w_bet * df["bet_n"].fillna(0) + w_dist * df["dist_w"].fillna(0) - w_hub * df["hub_n"].fillna(0)

    # Exclude source address
    if not df.empty and "address" in df.columns:
        df = df[df["address"].str.lower() != SOURCE_ADDR]

    df_ppr_top = df.sort_values(by=["ppr_n","score_comb"], ascending=False).head(200)
    df_bet_top = df.sort_values(by=["bet_n","score_comb"], ascending=False).head(200)

    results[name] = {
        "full": df,
        "ppr_top": df_ppr_top[["address","ppr_n","score_comb","depth","outdeg","indeg"]].dropna(subset=["address"]) if not df_ppr_top.empty else pd.DataFrame(columns=["address","ppr_n","score_comb","depth","outdeg","indeg"]),
        "bet_top": df_bet_top[["address","bet_n","score_comb","depth","outdeg","indeg"]].dropna(subset=["address"]) if not df_bet_top.empty else pd.DataFrame(columns=["address","bet_n","score_comb","depth","outdeg","indeg"]) 
    }

# Combine candidate sets
ppr_strict_addrs = set(results.get("strict",{}).get("ppr_top", pd.DataFrame(columns=["address"]))['address'].tolist()) if "strict" in results else set()
ppr_relaxed_addrs = set(results.get("relaxed",{}).get("ppr_top", pd.DataFrame(columns=["address"]))['address'].tolist()) if "relaxed" in results else set()
bet_strict_addrs = set(results.get("strict",{}).get("bet_top", pd.DataFrame(columns=["address"]))['address'].tolist()) if "strict" in results else set()
bet_relaxed_addrs = set(results.get("relaxed",{}).get("bet_top", pd.DataFrame(columns=["address"]))['address'].tolist()) if "relaxed" in results else set()

agree_strict = ppr_strict_addrs.intersection(bet_strict_addrs)
agree_relaxed = ppr_relaxed_addrs.intersection(bet_relaxed_addrs)

all_candidates = set().union(ppr_strict_addrs, ppr_relaxed_addrs, bet_strict_addrs, bet_relaxed_addrs)

# Row helper

def row_by_address(df, addr, cols):
    if df is None or df.empty:
        return {c: None for c in cols}
    r = df[df["address"] == addr]
    if r.empty:
        return {c: None for c in cols}
    row = r.iloc[0]
    return {c: (row[c] if c in row else None) for c in cols}

final_rows = []
for addr in all_candidates:
    s_full = results.get("strict",{}).get("full")
    r_full = results.get("relaxed",{}).get("full")
    s_row = row_by_address(s_full, addr, ["ppr_n","bet_n","score_comb","depth","outdeg","indeg"]) if s_full is not None else {}
    r_row = row_by_address(r_full, addr, ["ppr_n","bet_n","score_comb","depth","outdeg","indeg"]) if r_full is not None else {}

    presence = {
        "ppr_strict": addr in ppr_strict_addrs,
        "ppr_relaxed": addr in ppr_relaxed_addrs,
        "bet_strict": addr in bet_strict_addrs,
        "bet_relaxed": addr in bet_relaxed_addrs,
        "agree_strict": addr in agree_strict,
        "agree_relaxed": addr in agree_relaxed
    }

    score = 0.0
    score += (s_row.get("ppr_n") or 0.0)
    score += 0.7 * (r_row.get("ppr_n") or 0.0)
    score += 0.6 * (s_row.get("bet_n") or 0.0)
    score += 0.4 * (r_row.get("bet_n") or 0.0)
    sd = s_row.get("depth")
    rd = r_row.get("depth")
    if sd is not None and not pd.isna(sd):
        score += 0.5 * math.exp(-float(sd)/3.0)
    elif rd is not None and not pd.isna(rd):
        score += 0.5 * math.exp(-float(rd)/3.0)

    outdeg = s_row.get("outdeg") if s_row.get("outdeg") is not None else r_row.get("outdeg")
    indeg = s_row.get("indeg") if s_row.get("indeg") is not None else r_row.get("indeg")
    outdeg = outdeg or 0.0
    indeg = indeg or 0.0
    try:
        s_out_max = results.get("strict",{}).get("full", pd.DataFrame()).get("outdeg", pd.Series([0])).max()
        s_in_max = results.get("strict",{}).get("full", pd.DataFrame()).get("indeg", pd.Series([0])).max()
        r_out_max = results.get("relaxed",{}).get("full", pd.DataFrame()).get("outdeg", pd.Series([0])).max()
        r_in_max = results.get("relaxed",{}).get("full", pd.DataFrame()).get("indeg", pd.Series([0])).max()
        out_max = max(s_out_max if s_out_max is not None else 0, r_out_max if r_out_max is not None else 0, 1)
        in_max = max(s_in_max if s_in_max is not None else 0, r_in_max if r_in_max is not None else 0, 1)
        score -= 0.4 * ( (outdeg/out_max + indeg/in_max)/2.0 )
    except Exception:
        pass

    if presence["agree_strict"]:
        score += 0.5
    if presence["agree_relaxed"]:
        score += 0.3

    final_rows.append({"address": addr, "score": float(score), "presence": presence})

final_rows.sort(key=lambda x: x["score"], reverse=True)

if final_rows:
    scores = [r["score"] for r in final_rows]
    try:
        thresh = float(np.percentile(scores, 20))
    except Exception:
        thresh = 0.05
    pruned = [r for r in final_rows if r["score"] >= max(thresh, 0.05)]
else:
    pruned = []

final_addresses = [r["address"] for r in pruned][:100]

least_sure = []
for r in final_rows[-20:]:
    pres = r["presence"]
    only_relaxed = (not pres["ppr_strict"]) and (not pres["bet_strict"]) and (pres["ppr_relaxed"] or pres["bet_relaxed"]) 
    single_method = (pres["ppr_relaxed"] ^ pres["bet_relaxed"]) and (not pres["ppr_strict"]) and (not pres["bet_strict"]) 
    if only_relaxed or single_method:
        least_sure.append(r["address"])

# Method counts
out["methods"]["counts"] = {
    "ppr_strict": len(ppr_strict_addrs),
    "ppr_relaxed": len(ppr_relaxed_addrs),
    "bet_strict": len(bet_strict_addrs),
    "bet_relaxed": len(bet_relaxed_addrs),
    "agree_strict": len(agree_strict),
    "agree_relaxed": len(agree_relaxed),
    "candidates": len(all_candidates)
}

# Final graph info
out["final"]["addresses"] = final_addresses
out["final"]["least_sure"] = least_sure[:10]
out["final"]["source"] = SOURCE_ADDR
out["final"]["graph"] = {
    "label": found_label,
    "relationshipType": rel_type,
    "amountProp": amount_prop,
    "timeProp": time_prop,
    "strictWindow": [str(start_strict) if start_strict is not None else None, str(end_strict) if end_strict is not None else None],
    "relaxedWindow": [str(start_relaxed) if start_relaxed is not None else None, str(end_relaxed) if end_relaxed is not None else None],
    "strictMinAmount": float(min_amt_strict) if min_amt_strict is not None else None,
    "relaxedMinAmount": float(min_amt_relaxed) if min_amt_relaxed is not None else None,
    "strictGraph": {"nodes": int(n_strict), "rels": int(m_strict)},
    "relaxedGraph": {"nodes": int(n_relaxed), "rels": int(m_relaxed)}
}

print(json.dumps(out))

import os
import math
import sys
import json
from datetime import timedelta
import numpy as np
import pandas as pd
from neo4j import GraphDatabase
from graphdatascience import GraphDataScience

# Configuration
SOURCE_ADDR_RAW = "0x1db92e2eebc8e0c075a02bea49a2935bcd2dfcf4"
SOURCE_ADDR = SOURCE_ADDR_RAW.lower()

# Connect to Neo4j / GDS
uri = os.getenv("NEO4J_URI", "bolt://localhost:7687")
user = os.getenv("NEO4J_USERNAME", "neo4j")
pwd = os.getenv("NEO4J_PASSWORD", "")
db = os.getenv("NEO4J_DATABASE", None)

gds = GraphDataScience(uri, auth=(user, pwd), database=db) if db else GraphDataScience(uri, auth=(user, pwd))

# Helper to run cypher (via GDS client)
def run_cypher(q, params=None):
    try:
        return gds.run_cypher(q, params or {})
    except Exception as e:
        try:
            driver = GraphDatabase.driver(uri, auth=(user, pwd))
            with driver.session(database=db) as session:
                res = session.run(q, params or {})
                return pd.DataFrame([r.data() for r in res])
        except Exception as e2:
            raise RuntimeError(f"Cypher failed both via GDS and driver: {e} | {e2}")

out = {
    "setup": {},
    "graph": {},
    "debug": {},
    "methods": {},
    "final": {}
}

# Introspect labels and rel types
labels_df = run_cypher("CALL db.labels() YIELD label RETURN label ORDER BY label")
rels_df = run_cypher("CALL db.relationshipTypes() YIELD relationshipType RETURN relationshipType ORDER BY relationshipType")
labels = labels_df["label"].tolist() if not labels_df.empty else []
rel_types = rels_df["relationshipType"].tolist() if not rels_df.empty else []

candidate_labels = [l for l in ["Address","Account","Wallet","EOA"] if l in labels]
if not candidate_labels:
    candidate_labels = labels

# Locate source node
found_label = None
sid = None
for lbl in candidate_labels:
    q = f"MATCH (n:`{lbl}`) WHERE toLower(coalesce(n.address, n.hash, n.id))=$a RETURN id(n) AS id LIMIT 1"
    df = run_cypher(q, {"a": SOURCE_ADDR})
    if not df.empty:
        found_label = lbl
        sid = int(df.iloc[0]["id"])
        break

if sid is None:
    print(json.dumps({"error": "Source address not found", "labels": labels}))
    sys.exit(0)

# Choose rel type connecting addresses
cand = []
for rt in rel_types:
    q = f"MATCH (:`{found_label}`)-[r:`{rt}`]->(:`{found_label}`) RETURN count(r) AS c"
    df = run_cypher(q)
    if not df.empty and int(df.iloc[0]["c"])>0:
        cand.append((rt, int(df.iloc[0]["c"])) )
if not cand:
    print(json.dumps({"error": "No transfer relationship type between addresses.", "label": found_label}))
    sys.exit(0)
rel_type = sorted(cand, key=lambda x:x[1], reverse=True)[0][0]

# Determine rel props
keys_df = run_cypher(f"MATCH (:`{found_label}`)-[r:`{rel_type}`]->(:`{found_label}`) WITH r LIMIT 200 UNWIND keys(r) AS k RETURN collect(DISTINCT k) AS ks")
keys = keys_df.iloc[0]["ks"] if not keys_df.empty else []
amount_prop = next((k for k in ["amount","value","valueWei","wei","eth","quantity"] if k in keys), None)
time_prop = next((k for k in ["time","timestamp","blockTimestamp","blockNumber"] if k in keys), None)

# Amount thresholds from outbound distribution (if amount exists)
min_amt_strict = min_amt_relaxed = None
if amount_prop:
    df = run_cypher(f"MATCH (src:`{found_label}`)-[r:`{rel_type}`]->(:`{found_label}`) WHERE id(src)=$sid RETURN percentileCont(r.`{amount_prop}`,0.25) AS p25, percentileCont(r.`{amount_prop}`,0.5) AS p50", {"sid": sid})
    if not df.empty:
        p25 = df.iloc[0]["p25"]; p50 = df.iloc[0]["p50"]
        if pd.notna(p25) and pd.notna(p50):
            min_amt_strict = float(p50)
            min_amt_relaxed = float(p25)

# Build reachable node id sets (strict: hops<=4 and min amount>=p50; relaxed: hops<=5 and min amount>=p25)

def reachable_node_ids(max_hops, min_amt):
    amt_clause = f"all(r IN relationships(p) WHERE r.`{amount_prop}` >= $minAmt)" if amount_prop and min_amt is not None else "true"
    q = f"""
    MATCH (src:`{found_label}`) WHERE id(src)=$sid
    CALL {{
      WITH src
      MATCH p=(src)-[r:`{rel_type}`*1..{max_hops}]->(n:`{found_label}`)
      WHERE {amt_clause}
      RETURN collect(DISTINCT id(n)) AS ids
    }}
    WITH ids + [id(src)] AS nodes
    UNWIND nodes AS id
    RETURN DISTINCT id AS id
    """
    params = {"sid": sid}
    if "$minAmt" in q:
        params["minAmt"] = min_amt
    df = run_cypher(q, params)
    return [int(x) for x in df["id"].tolist()] if not df.empty else []

strict_ids = reachable_node_ids(4, min_amt_strict)
relaxed_ids = reachable_node_ids(5, min_amt_relaxed)

# Projection helper with proper parameters nesting

def drop_graph(name):
    try:
        run_cypher("CALL gds.graph.drop($name, false)", {"name": name})
    except Exception:
        pass


def project_graph(name, node_ids, min_amt):
    drop_graph(name)
    nq = "UNWIND $nodeIds AS id RETURN id AS id"
    extra = []
    if amount_prop and min_amt is not None:
        extra.append(f"r.`{amount_prop}` >= $minAmt")
    and_clause = (" AND "+" AND ".join(extra)) if extra else ""
    rq = f"""
    MATCH (a:`{found_label}`)-[r:`{rel_type}`]->(b:`{found_label}`)
    WHERE id(a) IN $nodeIds AND id(b) IN $nodeIds{and_clause}
    RETURN id(a) AS source, id(b) AS target {', toFloat(r.`' + amount_prop + '`) AS amount' if amount_prop else ''}
    """
    df = run_cypher(
        "CALL gds.graph.project.cypher($name, $nq, $rq, $conf) YIELD graphName, nodeCount, relationshipCount",
        {"name": name, "nq": nq, "rq": rq, "conf": {"parameters": {"nodeIds": node_ids, "minAmt": min_amt}}}
    )
    if df.empty:
        return 0,0
    return int(df.iloc[0]["nodeCount"]), int(df.iloc[0]["relationshipCount"])

n_strict, m_strict = project_graph("graph_strict", strict_ids, min_amt_strict)
n_relaxed, m_relaxed = project_graph("graph_relaxed", relaxed_ids, min_amt_relaxed)

# Run light-weight GDS algorithms (BFS distances and Degrees) to anchor results

def bfs_distances(graph_name, max_depth):
    try:
        q = "CALL gds.beta.bfs.stream($g, {sourceNode: $sid, maxDepth: $md}) YIELD nodeId, depth RETURN nodeId, depth"
        return run_cypher(q, {"g": graph_name, "sid": sid, "md": max_depth})
    except Exception:
        return pd.DataFrame(columns=["nodeId","depth"])


def degrees(graph_name):
    try:
        outd = run_cypher("CALL gds.degree.stream($g, {orientation:'OUTGOING'}) YIELD nodeId, score RETURN nodeId, score", {"g": graph_name})
        ind = run_cypher("CALL gds.degree.stream($g, {orientation:'INCOMING'}) YIELD nodeId, score RETURN nodeId, score", {"g": graph_name})
        return outd.rename(columns={"score":"outdeg"}), ind.rename(columns={"score":"indeg"})
    except Exception:
        return pd.DataFrame(columns=["nodeId","outdeg"]), pd.DataFrame(columns=["nodeId","indeg"]) 

# Aggregate inbound volumes with Cypher for each node set

def inbound_volume(node_ids, min_amt):
    if not node_ids:
        return pd.DataFrame(columns=["id","in_amt","in_edges"])
    where_amt = f"AND r.`{amount_prop}` >= $minAmt" if amount_prop and min_amt is not None else ""
    q = f"""
    UNWIND $ids AS id
    MATCH (n:`{found_label}`) WHERE id(n)=id
    OPTIONAL MATCH (a:`{found_label}`)-[r:`{rel_type}`]->(n)
    WHERE id(a) IN $ids {where_amt}
    RETURN id(n) AS id, sum(toFloat(r.`{amount_prop}`)) AS in_amt, count(r) AS in_edges
    """
    params = {"ids": node_ids}
    if "$minAmt" in q:
        params["minAmt"] = min_amt
    df = run_cypher(q, params)
    return df

# Build frames for strict
bfs_s = bfs_distances("graph_strict", max_depth=6)
out_s, in_s = degrees("graph_strict")
vol_s = inbound_volume(strict_ids, min_amt_strict)

s_df = pd.DataFrame(columns=["nodeId"]) 
for d in [bfs_s.rename(columns={"nodeId":"nodeId"}), out_s, in_s]:
    if not d.empty and "nodeId" in d.columns:
        s_df = s_df.merge(d, on="nodeId", how="outer") if not s_df.empty else d.copy()

# Map inbound volume by id -> nodeId mapping
if not vol_s.empty:
    vol_s = vol_s.rename(columns={"id":"nodeId"})
    s_df = s_df.merge(vol_s, on="nodeId", how="left") if not s_df.empty else vol_s.copy()

# Map addresses
def map_ids_to_addr(ids):
    if not ids:
        return {}
    q = "UNWIND $ids AS id MATCH (n) WHERE id(n)=id RETURN id(n) AS id, coalesce(n.address,n.hash,n.id,toString(id(n))) AS address"
    df = run_cypher(q, {"ids": ids})
    return {int(r["id"]): r["address"] for _, r in df.iterrows()} if not df.empty else {}

if not s_df.empty:
    id2addr = map_ids_to_addr(s_df["nodeId"].dropna().astype(int).tolist())
    s_df["address"] = s_df["nodeId"].map(lambda x: id2addr.get(int(x), None) if pd.notna(x) else None)

# Build score A (strict)
if not s_df.empty:
    s_df["depth"] = s_df["depth"].fillna(99)
    s_df["dist_w"] = s_df["depth"].apply(lambda d: math.exp(-float(d)/2.0) if d is not None and d != 99 else 0.0)
    for c in ["outdeg","indeg","in_amt","in_edges"]:
        if c not in s_df.columns:
            s_df[c] = 0.0
    # Normalize volumes
    s_df["in_amt_n"] = (s_df["in_amt"].fillna(0) / (s_df["in_amt"].max() or 1.0))
    s_df["in_edges_n"] = (s_df["in_edges"].fillna(0) / (s_df["in_edges"].max() or 1.0))
    s_df["hub_n"] = ((s_df["outdeg"].fillna(0)/(s_df["outdeg"].max() or 1.0)) + (s_df["indeg"].fillna(0)/(s_df["indeg"].max() or 1.0)))/2.0
    s_df["score_A"] = 0.6*s_df["dist_w"] + 0.3*s_df["in_amt_n"] + 0.1*s_df["in_edges_n"] - 0.3*s_df["hub_n"]
    s_df = s_df[s_df["address"].str.lower() != SOURCE_ADDR]
    s_top = s_df.sort_values(by=["score_A","dist_w","in_amt_n"], ascending=False).head(200)
else:
    s_top = pd.DataFrame(columns=["address","score_A"]) 

# Build frames for relaxed
bfs_r = bfs_distances("graph_relaxed", max_depth=7)
out_r, in_r = degrees("graph_relaxed")
vol_r = inbound_volume(relaxed_ids, min_amt_relaxed)

r_df = pd.DataFrame(columns=["nodeId"]) 
for d in [bfs_r.rename(columns={"nodeId":"nodeId"}), out_r, in_r]:
    if not d.empty and "nodeId" in d.columns:
        r_df = r_df.merge(d, on="nodeId", how="outer") if not r_df.empty else d.copy()

if not vol_r.empty:
    vol_r = vol_r.rename(columns={"id":"nodeId"})
    r_df = r_df.merge(vol_r, on="nodeId", how="left") if not r_df.empty else vol_r.copy()

if not r_df.empty:
    id2addr_r = map_ids_to_addr(r_df["nodeId"].dropna().astype(int).tolist())
    r_df["address"] = r_df["nodeId"].map(lambda x: id2addr_r.get(int(x), None) if pd.notna(x) else None)

# Build score B (relaxed)
if not r_df.empty:
    r_df["depth"] = r_df["depth"].fillna(99)
    r_df["dist_w"] = r_df["depth"].apply(lambda d: math.exp(-float(d)/2.5) if d is not None and d != 99 else 0.0)
    for c in ["outdeg","indeg","in_amt","in_edges"]:
        if c not in r_df.columns:
            r_df[c] = 0.0
    r_df["in_amt_n"] = (r_df["in_amt"].fillna(0) / (r_df["in_amt"].max() or 1.0))
    r_df["in_edges_n"] = (r_df["in_edges"].fillna(0) / (r_df["in_edges"].max() or 1.0))
    r_df["hub_n"] = ((r_df["outdeg"].fillna(0)/(r_df["outdeg"].max() or 1.0)) + (r_df["indeg"].fillna(0)/(r_df["indeg"].max() or 1.0)))/2.0
    r_df["score_B"] = 0.5*r_df["dist_w"] + 0.4*r_df["in_amt_n"] + 0.1*r_df["in_edges_n"] - 0.25*r_df["hub_n"]
    r_df = r_df[r_df["address"].str.lower() != SOURCE_ADDR]
    r_top = r_df.sort_values(by=["score_B","dist_w","in_amt_n"], ascending=False).head(200)
else:
    r_top = pd.DataFrame(columns=["address","score_B"]) 

# Combine and rank
s_addrs = set(s_top["address"].dropna().tolist())
r_addrs = set(r_top["address"].dropna().tolist())

union_addrs = list(s_addrs.union(r_addrs))

# Build combined score with agreement bonus
rows = []
for a in union_addrs:
    s_sc = float(s_top[s_top["address"]==a]["score_A"].iloc[0]) if a in s_addrs else 0.0
    r_sc = float(r_top[r_top["address"]==a]["score_B"].iloc[0]) if a in r_addrs else 0.0
    score = s_sc + 0.8*r_sc + (0.3 if (a in s_addrs and a in r_addrs) else 0.0)
    rows.append({"address": a, "score": score, "in_both": (a in s_addrs and a in r_addrs)})

rows.sort(key=lambda x: x["score"], reverse=True)
final_addrs = [r["address"] for r in rows][:100]

# Find least sure (only in relaxed and low score)
least = [r["address"] for r in rows if (r["address"] in r_addrs and r["address"] not in s_addrs)][-10:]

print(json.dumps({
    "graph": {
        "label": found_label,
        "relationshipType": rel_type,
        "amountProp": amount_prop,
        "strict": {"nodes": len(strict_ids), "projectedNodes": int(n_strict), "projectedRels": int(m_strict), "minAmt": min_amt_strict},
        "relaxed": {"nodes": len(relaxed_ids), "projectedNodes": int(n_relaxed), "projectedRels": int(m_relaxed), "minAmt": min_amt_relaxed}
    },
    "methodA_top": final_addrs[:50],
    "methodB_relaxed_top": list(r_addrs)[:50],
    "final": final_addrs,
    "least_sure": least
}))
